export enum MuscleGroup {
  CHEST = 'Peitoral',
  BACK = 'Costas',
  LEGS = 'Pernas',
  SHOULDERS = 'Ombros',
  ARMS = 'Braços',
  CORE = 'Abdômen',
  CARDIO = 'Cardio',
  FULL_BODY = 'Corpo Todo'
}

export interface Exercise {
  id: string;
  name: string;
  muscleGroup: MuscleGroup;
  sets: number;
  reps: string; // string to allow "12-15" or "Falha"
  videoUrl?: string; // URL placeholder or YouTube link
  notes?: string;
}

export interface DayPlan {
  dayOfWeek: string; // 'Segunda', 'Terça', etc.
  exercises: Exercise[];
  focus: string; // e.g., "Leg Day"
}

export interface WeeklyPlan {
  days: DayPlan[];
}

export interface Student {
  id: string;
  name: string;
  age: number;
  goal: string; // e.g., "Hipertrofia", "Emagrecimento"
  level: 'Iniciante' | 'Intermediário' | 'Avançado';
  weeklyPlan: WeeklyPlan;
  avatarUrl: string;
  restrictions?: string; // Medical or physical restrictions
}

