import { GoogleGenAI, Type } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup } from "../types";

// Helper to sanitize JSON string if Markdown code blocks are present
const cleanJsonString = (str: string) => {
  return str.replace(/```json\n|\n```/g, "").trim();
};

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) {
    console.error("API Key not found");
    return null;
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Atue como um Personal Trainer de elite. Crie uma ficha de treino semanal completa (Segunda a Domingo) para o seguinte aluno:

    Nome: ${student.name}
    Idade: ${student.age}
    Nível: ${student.level}
    Objetivo Principal: ${student.goal}
    Restrições/Observações: ${student.restrictions || "Nenhuma"}

    Notas adicionais do treinador: ${notes}

    Para dias de descanso, deixe a lista de exercícios vazia e o foco como "Descanso" ou "Recuperação Ativa".
    Use termos técnicos em Português do Brasil.
    Para os grupos musculares, escolha um destes valores exatos:
    ${Object.values(MuscleGroup).join(', ')}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) return null;

    const data = JSON.parse(text);

    // Post-process to ensure IDs and structure match internal types
    const processedPlan: WeeklyPlan = {
      days: data.days.map((day: any) => ({
        ...day,
        exercises: day.exercises.map((ex: any, idx: number) => ({
          ...ex,
          id: `gen-${Date.now()}-${idx}`, // Generate a temporary ID
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name + " exercicio")}`
        }))
      }))
    };

    return processedPlan;

  } catch (error) {
    console.error("Error generating workout plan:", error);
    return null;
  }
};

import React, { useState } from 'react';
import { Student, WeeklyPlan, DayPlan, Exercise, MuscleGroup } from '../types';
import { generateWorkoutPlan } from '../services/geminiService';
import { ArrowLeft, BrainCircuit, Loader2, PlayCircle, Plus, Trash2, Dumbbell, Save, Video } from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationNote, setGenerationNote] = useState("");
  const [showGenModal, setShowGenModal] = useState(false);

  // Exercise editing state
  const [isEditingExercise, setIsEditingExercise] = useState<string | null>(null); // ID of exercise being edited
  const [showAddExercise, setShowAddExercise] = useState(false);
  const [newExercise, setNewExercise] = useState<Partial<Exercise>>({
    name: '',
    sets: 3,
    reps: '10',
    muscleGroup: MuscleGroup.FULL_BODY
  });

  const currentDay = student.weeklyPlan.days[selectedDayIndex];

  const handleGeneratePlan = async () => {
    setIsGenerating(true);
    const newPlan = await generateWorkoutPlan(student, generationNote);
    if (newPlan) {
      onUpdateStudent({ ...student, weeklyPlan: newPlan });
      setShowGenModal(false);
    }
    setIsGenerating(false);
  };

  const handleAddExercise = () => {
    if (!newExercise.name) return;

    const exerciseToAdd: Exercise = {
      id: `man-${Date.now()}`,
      name: newExercise.name,
      muscleGroup: newExercise.muscleGroup as MuscleGroup,
      sets: newExercise.sets || 3,
      reps: newExercise.reps || '10',
      notes: newExercise.notes,
      videoUrl: newExercise.videoUrl || `https://www.youtube.com/results?search_query=${encodeURIComponent(newExercise.name || '')}`
    };

    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: [...updatedDays[selectedDayIndex].exercises, exerciseToAdd]
    };

    onUpdateStudent({
      ...student,
      weeklyPlan: { days: updatedDays }
    });

    setShowAddExercise(false);
    setNewExercise({ name: '', sets: 3, reps: '10', muscleGroup: MuscleGroup.FULL_BODY });
  };

  const handleDeleteExercise = (exId: string) => {
    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: updatedDays[selectedDayIndex].exercises.filter(e => e.id !== exId)
    };
    onUpdateStudent({ ...student, weeklyPlan: { days: updatedDays } });
  };

  return (
    <div className="animate-fade-in space-y-6 pb-20">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-700">
        <div className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="p-2 hover:bg-slate-700 rounded-full transition-colors text-slate-400 hover:text-white"
          >
            <ArrowLeft size={24} />
          </button>
          <img 
            src={student.avatarUrl} 
            alt={student.name} 
            className="w-16 h-16 rounded-full border-2 border-lime-400 object-cover"
          />
          <div>
            <h1 className="text-2xl font-bold text-white">{student.name}</h1>
            <div className="flex gap-2 text-sm text-slate-400 mt-1">
              <span className="bg-slate-900 px-2 py-0.5 rounded text-lime-400 font-medium">{student.goal}</span>
              <span className="bg-slate-900 px-2 py-0.5 rounded">{student.level}</span>
            </div>
          </div>
        </div>

        <button 
          onClick={() => setShowGenModal(true)}
          className="flex items-center gap-2 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white px-5 py-3 rounded-xl font-semibold transition-all shadow-lg hover:shadow-indigo-500/25"
        >
          <BrainCircuit size={20} />
          <span>Gerar Treino com IA</span>
        </button>
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Weekly Tabs (Vertical on desktop, horizontal scroll on mobile) */}
        <div className="lg:col-span-3 flex lg:flex-col overflow-x-auto lg:overflow-visible gap-2 pb-2 lg:pb-0">
          {student.weeklyPlan.days.map((day, idx) => (
            <button
              key={day.dayOfWeek}
              onClick={() => setSelectedDayIndex(idx)}
              className={`flex flex-col items-start p-4 rounded-xl transition-all min-w-[120px] lg:w-full border ${
                selectedDayIndex === idx 
                  ? 'bg-lime-500 text-slate-900 border-lime-400 shadow-md scale-[1.02]' 
                  : 'bg-slate-800 text-slate-400 border-slate-700 hover:bg-slate-750'
              }`}
            >
              <span className="text-sm font-semibold opacity-75 uppercase tracking-wide">{day.dayOfWeek}</span>
              <span className="font-bold text-lg truncate w-full text-left">{day.focus || 'Descanso'}</span>
              <span className="text-xs mt-2 font-medium opacity-60">{day.exercises.length} Exercícios</span>
            </button>
          ))}
        </div>

        {/* Day Details */}
        <div className="lg:col-span-9 bg-slate-800 rounded-2xl p-6 border border-slate-700 min-h-[500px]">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                {currentDay.dayOfWeek} 
                <span className="text-slate-500">/</span> 
                <span className="text-lime-400">{currentDay.focus}</span>
              </h2>
            </div>
            <button 
              onClick={() => setShowAddExercise(true)}
              className="flex items-center gap-2 bg-slate-700 hover:bg-slate-600 text-white px-4 py-2 rounded-lg transition-colors text-sm font-medium"
            >
              <Plus size={18} />
              Adicionar
            </button>
          </div>

          {currentDay.exercises.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-500 border-2 border-dashed border-slate-700 rounded-xl">
              <Dumbbell size={48} className="mb-4 opacity-20" />
              <p>Nenhum exercício programado para este dia.</p>
              <p className="text-sm">Adicione exercícios manualmente ou use a IA.</p>
            </div>
          ) : (
            <div className="space-y-4">
              {currentDay.exercises.map((ex) => (
                <div key={ex.id} className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 hover:border-slate-600 transition-all group relative">
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-xs font-bold text-slate-500 uppercase tracking-wider bg-slate-800 px-2 py-0.5 rounded">
                          {ex.muscleGroup}
                        </span>
                        {ex.videoUrl && (
                          <a 
                            href={ex.videoUrl} 
                            target="_blank" 
                            rel="noreferrer"
                            className="text-indigo-400 hover:text-indigo-300 transition-colors"
                            title="Ver vídeo"
                          >
                            <Video size={14} />
                          </a>
                        )}
                      </div>
                      <h3 className="text-lg font-bold text-white mb-2">{ex.name}</h3>
                      <div className="flex flex-wrap gap-4 text-sm text-slate-300">
                        <div className="flex flex-col">
                          <span className="text-slate-500 text-xs uppercase">Séries</span>
                          <span className="font-mono text-lime-400 font-bold text-lg">{ex.sets}</span>
                        </div>
                        <div className="flex flex-col">
                          <span className="text-slate-500 text-xs uppercase">Repetições</span>
                          <span className="font-mono text-white font-bold text-lg">{ex.reps}</span>
                        </div>
                        {ex.notes && (
                          <div className="flex flex-col flex-1 min-w-[200px]">
                            <span className="text-slate-500 text-xs uppercase">Observações</span>
                            <span className="italic text-slate-400">{ex.notes}</span>
                          </div>
                        )}
                      </div>
                    </div>

                    <button 
                      onClick={() => handleDeleteExercise(ex.id)}
                      className="opacity-0 group-hover:opacity-100 p-2 text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
                      title="Remover exercício"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* AI Generation Modal */}
      {showGenModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-slate-800 rounded-2xl p-6 w-full max-w-lg border border-slate-700 shadow-2xl">
            <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
              <BrainCircuit className="text-purple-500" />
              Gerar Ficha com IA
            </h3>
            <p className="text-slate-400 mb-4 text-sm">
              Descreva o foco específico para esta semana ou deixe em branco para uma sugestão padrão baseada no perfil do aluno.
            </p>
            <textarea
              value={generationNote}
              onChange={(e) => setGenerationNote(e.target.value)}
              placeholder="Ex: Focar em deltoide lateral, reduzir carga no agachamento devido à dor..."
              className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl p-3 h-32 mb-6 focus:ring-2 focus:ring-purple-500 focus:outline-none resize-none"
            />
            <div className="flex justify-end gap-3">
              <button 
                onClick={() => setShowGenModal(false)}
                className="px-4 py-2 text-slate-300 hover:text-white transition-colors"
                disabled={isGenerating}
              >
                Cancelar
              </button>
              <button 
                onClick={handleGeneratePlan}
                disabled={isGenerating}
                className="bg-purple-600 hover:bg-purple-700 text-white px-6 py-2 rounded-xl font-semibold flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <BrainCircuit size={20} />}
                {isGenerating ? 'Gerando...' : 'Gerar Ficha'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add Exercise Modal */}
      {showAddExercise && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-slate-800 rounded-2xl p-6 w-full max-w-md border border-slate-700 shadow-2xl">
            <h3 className="text-xl font-bold text-white mb-4">Adicionar Exercício</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs uppercase text-slate-500 font-bold mb-1">Nome</label>
                <input 
                  type="text"
                  value={newExercise.name}
                  onChange={e => setNewExercise({...newExercise, name: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white focus:border-lime-500 outline-none"
                  placeholder="Ex: Agachamento Livre"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs uppercase text-slate-500 font-bold mb-1">Grupo Muscular</label>
                  <select 
                    value={newExercise.muscleGroup}
                    onChange={e => setNewExercise({...newExercise, muscleGroup: e.target.value as MuscleGroup})}
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white focus:border-lime-500 outline-none"
                  >
                    {Object.values(MuscleGroup).map(g => (
                      <option key={g} value={g}>{g}</option>
                    ))}
                  </select>
                </div>
                <div>
                   <label className="block text-xs uppercase text-slate-500 font-bold mb-1">Repetições</label>
                   <input 
                    type="text"
                    value={newExercise.reps}
                    onChange={e => setNewExercise({...newExercise, reps: e.target.value})}
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white focus:border-lime-500 outline-none"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs uppercase text-slate-500 font-bold mb-1">Séries</label>
                 <input 
                    type="number"
                    value={newExercise.sets}
                    onChange={e => setNewExercise({...newExercise, sets: parseInt(e.target.value)})}
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white focus:border-lime-500 outline-none"
                  />
              </div>
              <div>
                <label className="block text-xs uppercase text-slate-500 font-bold mb-1">Observações</label>
                 <textarea 
                    value={newExercise.notes || ''}
                    onChange={e => setNewExercise({...newExercise, notes: e.target.value})}
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white focus:border-lime-500 outline-none h-20 resize-none"
                  />
              </div>
            </div>
            <div className="flex justify-end gap-3 mt-6">
              <button 
                onClick={() => setShowAddExercise(false)}
                className="px-4 py-2 text-slate-300 hover:text-white transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleAddExercise}
                className="bg-lime-500 hover:bg-lime-600 text-slate-900 px-6 py-2 rounded-lg font-bold transition-colors"
              >
                Adicionar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

