    if (!newExercise.name) return;

    const exerciseToAdd: Exercise = {
      id: `man-${Date.now()}`,
      name: newExercise.name,
      muscleGroup: newExercise.muscleGroup as MuscleGroup,
      sets: newExercise.sets || 3,
      reps: newExercise.reps || '10',
      notes: newExercise.notes,
      videoUrl: newExercise.videoUrl || `https://www.youtube.com/results?search_query=${encodeURIComponent(newExercise.name || '')}`
    };

    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: [...updatedDays[selectedDayIndex].exercises, exerciseToAdd]
    };

    onUpdateStudent({
      ...student,
      weeklyPlan: { days: updatedDays }
    });

    setShowAddExercise(false);
    setNewExercise({ name: '', sets: 3, reps: '10', muscleGroup: MuscleGroup.FULL_BODY });
  };

  const handleDeleteExercise = (exId: string) => {
    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: updatedDays[selectedDayIndex].exercises.filter(e => e.id !== exId)
    };
    onUpdateStudent({ ...student, weeklyPlan: { days: updatedDays } });
  };

  const handleAddProgress = () => {
    if (!newProgress.weight) return;

    const entry: ProgressEntry = {
      id: `p-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      weight: newProgress.weight || 0,
      measurements: newProgress.measurements as Measurements,
      photos: newProgress.photos || []
    };

    onUpdateStudent({
      ...student,
      progress: [entry, ...(student.progress || [])]
    });

    setShowProgressModal(false);
    setNewProgress({ weight: 0, measurements: {}, photos: [] });
  };

  return (
    <div className="animate-fade-in space-y-6 pb-20">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-700">
        <div className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="p-2 hover:bg-slate-700 rounded-full transition-colors text-slate-400 hover:text-white"
          >
            <ArrowLeft size={24} />
          </button>
          <img 
            src={student.avatarUrl} 
            alt={student.name} 
            className="w-16 h-16 rounded-full border-2 border-lime-400 object-cover"
          />
          <div>
            <h1 className="text-2xl font-bold text-white">{student.name}</h1>
            <div className="flex gap-2 text-sm text-slate-400 mt-1">
              <span className="bg-slate-900 px-2 py-0.5 rounded text-lime-400 font-medium">{student.goal}</span>
              <span className="bg-slate-900 px-2 py-0.5 rounded">{student.level}</span>
            </div>
          </div>
        </div>

        <div className="flex gap-2">
          <button 
            onClick={() => setActiveTab('WORKOUT')}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl font-semibold transition-all ${
              activeTab === 'WORKOUT' ? 'bg-lime-500 text-slate-900' : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
            }`}
          >
            <Dumbbell size={18} />
            Treino
          </button>
          <button 
            onClick={() => setActiveTab('PROGRESS')}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl font-semibold transition-all ${
              activeTab === 'PROGRESS' ? 'bg-lime-500 text-slate-900' : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
            }`}
          >
            <LineChart size={18} />
            Evolução
          </button>
        </div>
      </div>

      {activeTab === 'WORKOUT' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Weekly Tabs */}
          <div className="lg:col-span-3 flex lg:flex-col overflow-x-auto lg:overflow-visible gap-2 pb-2 lg:pb-0">
            {student.weeklyPlan.days.map((day, idx) => (
              <button
                key={day.dayOfWeek}
                onClick={() => setSelectedDayIndex(idx)}
                className={`flex flex-col items-start p-4 rounded-xl transition-all min-w-[120px] lg:w-full border ${
                  selectedDayIndex === idx 
                    ? 'bg-lime-500 text-slate-900 border-lime-400 shadow-md scale-[1.02]' 
                    : 'bg-slate-800 text-slate-400 border-slate-700 hover:bg-slate-750'
                }`}
              >
                <span className="text-sm font-semibold opacity-75 uppercase tracking-wide">{day.dayOfWeek}</span>
                <span className="font-bold text-lg truncate w-full text-left">{day.focus || 'Descanso'}</span>
                <span className="text-xs mt-2 font-medium opacity-60">{day.exercises.length} Exercícios</span>
              </button>
            ))}
            <button 
              onClick={() => setShowGenModal(true)}
              className="lg:mt-4 flex items-center justify-center gap-2 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white p-4 rounded-xl font-semibold transition-all shadow-lg hover:shadow-indigo-500/25 min-w-[120px] lg:w-full"
            >
              <BrainCircuit size={20} />
              <span>Gerar IA</span>
            </button>
          </div>

          {/* Day Details */}
          <div className="lg:col-span-9 bg-slate-800 rounded-2xl p-6 border border-slate-700 min-h-[500px]">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                  {currentDay.dayOfWeek} 
                  <span className="text-slate-500">/</span> 
                  <span className="text-lime-400">{currentDay.focus}</span>
                </h2>
              </div>
              <button 
                onClick={() => setShowAddExercise(true)}
                className="flex items-center gap-2 bg-slate-700 hover:bg-slate-600 text-white px-4 py-2 rounded-lg transition-colors text-sm font-medium"
              >
                <Plus size={18} />
                Adicionar
              </button>
            </div>

            {currentDay.exercises.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-64 text-slate-500 border-2 border-dashed border-slate-700 rounded-xl">
                <Dumbbell size={48} className="mb-4 opacity-20" />
                <p>Nenhum exercício programado para este dia.</p>
                <p className="text-sm">Adicione exercícios manualmente ou use a IA.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {currentDay.exercises.map((ex) => (
                  <div key={ex.id} className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 hover:border-slate-600 transition-all group relative">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs font-bold text-slate-500 uppercase tracking-wider bg-slate-800 px-2 py-0.5 rounded">
                            {ex.muscleGroup}
                          </span>
                          {ex.videoUrl && (
                            <a href={ex.videoUrl} target="_blank" rel="noreferrer" className="text-indigo-400 hover:text-indigo-300">
                              <Video size={14} />
                            </a>
                          )}
                        </div>
                        <h3 className="text-lg font-bold text-white mb-2">{ex.name}</h3>
                        <div className="flex flex-wrap gap-4 text-sm text-slate-300">
                          <div className="flex flex-col"><span className="text-slate-500 text-xs">Séries</span><span className="text-lime-400 font-bold text-lg">{ex.sets}</span></div>
                          <div className="flex flex-col"><span className="text-slate-500 text-xs">Repetições</span><span className="text-white font-bold text-lg">{ex.reps}</span></div>
                          {ex.notes && <div className="flex flex-col flex-1"><span className="text-slate-500 text-xs">Observações</span><span className="italic text-slate-400">{ex.notes}</span></div>}
                        </div>
                      </div>
                      <button onClick={() => handleDeleteExercise(ex.id)} className="opacity-0 group-hover:opacity-100 p-2 text-red-400 hover:bg-red-400/10 rounded-lg">
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      ) : (
        /* Progress Tab Content */
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 flex flex-col items-center justify-center text-center">
              <Scale className="text-lime-400 mb-2" size={32} />
              <span className="text-slate-400 text-sm">Peso Atual</span>
              <span className="text-3xl font-bold text-white">
                {student.progress && student.progress.length > 0 ? `${student.progress[0].weight} kg` : '--'}
              </span>
            </div>
            <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 flex flex-col items-center justify-center text-center">
              <Calendar className="text-indigo-400 mb-2" size={32} />
              <span className="text-slate-400 text-sm">Última Avaliação</span>
              <span className="text-xl font-bold text-white">
                {student.progress && student.progress.length > 0 ? student.progress[0].date : 'Nenhuma'}
              </span>
            </div>
            <div className="md:col-span-2 bg-slate-800 p-6 rounded-2xl border border-slate-700 flex items-center justify-between">
              <div>
                <h3 className="text-lg font-bold text-white">Histórico de Medidas</h3>
                <p className="text-slate-400 text-sm">Acompanhe a evolução física do aluno.</p>
              </div>
              <button 
                onClick={() => setShowProgressModal(true)}
                className="bg-lime-500 hover:bg-lime-600 text-slate-900 px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg"
              >
                <Plus size={20} />
                Novo Registro
              </button>
            </div>
          </div>

          <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700">
            <h3 className="text-xl font-bold text-white mb-6">Linha do Tempo</h3>
            {(!student.progress || student.progress.length === 0) ? (
              <div className="text-center py-20 text-slate-500">
                <Ruler size={48} className="mx-auto mb-4 opacity-20" />
                <p>Nenhum registro de evolução ainda.</p>
              </div>
            ) : (
              <div className="space-y-6">
                {student.progress.map((entry, idx) => (
                  <div key={entry.id} className="relative pl-8 border-l-2 border-slate-700 pb-8 last:pb-0">
                    <div className="absolute left-[-9px] top-0 w-4 h-4 rounded-full bg-lime-400 border-4 border-slate-800"></div>
                    <div className="bg-slate-900/40 border border-slate-700 p-6 rounded-2xl hover:border-slate-500 transition-all">
                      <div className="flex flex-wrap items-start justify-between gap-4 mb-4">
                        <div>
                          <span className="text-lime-400 font-bold text-sm tracking-widest uppercase">{entry.date}</span>
                          <h4 className="text-2xl font-bold text-white">{entry.weight} kg</h4>
                        </div>
                        <div className="flex gap-2">
                           {entry.photos && entry.photos.map((photo, pIdx) => (
                             <img key={pIdx} src={photo} alt="Progress" className="w-16 h-24 object-cover rounded-lg border border-slate-600" />
                           ))}
                        </div>
                      </div>

                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                        {Object.entries(entry.measurements).map(([key, val]) => (
                          val && (
                            <div key={key} className="bg-slate-800/50 p-3 rounded-xl border border-slate-700">
                              <span className="text-slate-500 text-xs uppercase block">{key === 'chest' ? 'Peito' : key === 'waist' ? 'Cintura' : key === 'hips' ? 'Quadril' : key === 'bicepsR' ? 'Braço D' : key === 'bicepsL' ? 'Braço E' : key === 'thighR' ? 'Coxa D' : key === 'thighL' ? 'Coxa E' : key}</span>
                              <span className="text-white font-bold">{val} cm</span>
                            </div>
                          )
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Progress Entry Modal */}
      {showProgressModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center p-4 z-50">
          <div className="bg-slate-800 rounded-3xl p-8 w-full max-w-2xl border border-slate-700 shadow-2xl overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-2xl font-bold text-white flex items-center gap-2">
                <Ruler className="text-lime-400" />
                Registrar Evolução
              </h3>
              <button onClick={() => setShowProgressModal(false)} className="text-slate-500 hover:text-white">
                <X size={24} />
              </button>
            </div>

            <div className="space-y-6">
              <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-700">
                <label className="block text-xs uppercase text-slate-500 font-bold mb-2">Peso Corporal (kg)</label>
                <div className="flex items-center gap-4">
                  <Scale className="text-slate-600" />
                  <input 
                    type="number"
                    step="0.1"
                    value={newProgress.weight}
                    onChange={e => setNewProgress({...newProgress, weight: parseFloat(e.target.value)})}
                    className="flex-1 bg-transparent text-3xl font-bold text-white outline-none"
                    placeholder="0.0"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {[
                  { label: 'Cintura', key: 'waist' },
                  { label: 'Peito', key: 'chest' },
                  { label: 'Quadril', key: 'hips' },
                  { label: 'Braço D', key: 'bicepsR' },
                  { label: 'Braço E', key: 'bicepsL' },
                  { label: 'Coxa D', key: 'thighR' },
                  { label: 'Coxa E', key: 'thighL' },
                ].map(item => (
                  <div key={item.key} className="bg-slate-900/30 p-3 rounded-xl border border-slate-700">
                    <label className="block text-xs text-slate-500 mb-1">{item.label} (cm)</label>
                    <input 
                      type="number"
                      value={newProgress.measurements?.[item.key as keyof Measurements] || ''}
                      onChange={e => setNewProgress({
                        ...newProgress, 
                        measurements: { 
                          ...newProgress.measurements, 
                          [item.key]: parseFloat(e.target.value) 
                        }
                      })}
                      className="bg-transparent text-white font-bold w-full outline-none"
                    />
                  </div>
                ))}
              </div>

              <div>
                <label className="block text-xs uppercase text-slate-500 font-bold mb-2">Fotos de Progresso (URL)</label>
                <div className="flex gap-2">
                  <input 
                    type="text"
                    className="flex-1 bg-slate-900 border border-slate-700 rounded-xl p-3 text-white outline-none"
                    placeholder="Link da imagem..."
                    onKeyDown={e => {
                      if (e.key === 'Enter') {
                        const val = (e.target as HTMLInputElement).value;
                        if (val) {
                          setNewProgress({...newProgress, photos: [...(newProgress.photos || []), val]});
                          (e.target as HTMLInputElement).value = '';
                        }
                      }
                    }}
                  />
                  <button className="bg-slate-700 p-3 rounded-xl text-white"><Camera size={20} /></button>
                </div>
                {newProgress.photos && newProgress.photos.length > 0 && (
                  <div className="flex gap-2 mt-4">
                    {newProgress.photos.map((p, i) => (
                      <div key={i} className="relative">
                        <img src={p} className="w-16 h-16 rounded-lg object-cover" />
                        <button 
                          onClick={() => setNewProgress({...newProgress, photos: newProgress.photos?.filter((_, idx) => idx !== i)})}
                          className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-0.5"
                        ><X size={12} /></button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>

            <div className="flex gap-3 mt-8">
              <button 
                onClick={() => setShowProgressModal(false)}
                className="flex-1 px-4 py-3 rounded-xl font-bold text-slate-400 hover:bg-slate-700 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleAddProgress}
                className="flex-1 bg-lime-500 hover:bg-lime-600 text-slate-900 px-4 py-3 rounded-xl font-bold transition-all shadow-lg"
              >
                Salvar Avaliação
              </button>
            </div>
          </div>
        </div>
      )}

      {/* AI Generation Modal (Keep existing) */}
      {showGenModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-slate-800 rounded-2xl p-6 w-full max-w-lg border border-slate-700 shadow-2xl">
            <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
              <BrainCircuit className="text-purple-500" />
              Gerar Ficha com IA
            </h3>
            <textarea
              value={generationNote}
              onChange={(e) => setGenerationNote(e.target.value)}
              placeholder="Ex: Focar em deltoide lateral..."
              className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl p-3 h-32 mb-6 outline-none resize-none"
            />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowGenModal(false)} className="px-4 py-2 text-slate-300">Cancelar</button>
              <button onClick={handleGeneratePlan} disabled={isGenerating} className="bg-purple-600 text-white px-6 py-2 rounded-xl font-semibold flex items-center gap-2">
                {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <BrainCircuit size={20} />}
                {isGenerating ? 'Gerando...' : 'Gerar Ficha'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add Exercise Modal (Keep existing) */}
      {showAddExercise && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-slate-800 rounded-2xl p-6 w-full max-w-md border border-slate-700 shadow-2xl">
            <h3 className="text-xl font-bold text-white mb-4">Adicionar Exercício</h3>
            <div className="space-y-4">
              <input type="text" value={newExercise.name} onChange={e => setNewExercise({...newExercise, name: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white outline-none" placeholder="Nome" />
              <select value={newExercise.muscleGroup} onChange={e => setNewExercise({...newExercise, muscleGroup: e.target.value as MuscleGroup})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white outline-none">
                {Object.values(MuscleGroup).map(g => <option key={g} value={g}>{g}</option>)}
              </select>
              <div className="grid grid-cols-2 gap-4">
                <input type="text" value={newExercise.reps} onChange={e => setNewExercise({...newExercise, reps: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white outline-none" placeholder="Reps" />
                <input type="number" value={newExercise.sets} onChange={e => setNewExercise({...newExercise, sets: parseInt(e.target.value)})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white outline-none" placeholder="Sets" />
              </div>
            </div>
            <div className="flex justify-end gap-3 mt-6">
              <button onClick={() => setShowAddExercise(false)} className="px-4 py-2 text-slate-300">Cancelar</button>
              <button onClick={handleAddExercise} className="bg-lime-500 text-slate-900 px-6 py-2 rounded-lg font-bold">Adicionar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Student, ViewState } from './types';
import { INITIAL_STUDENTS, WEEK_DAYS } from './constants';
