  const handleConfirmCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    // FIX: Added missing required 'progress' property to match the Student interface
    const newStudent: Student = {
      id: Date.now().toString(),
      name: formData.name,
      age: formData.age,
      goal: formData.goal,
      level: formData.level,
      restrictions: formData.restrictions,
      avatarUrl: `https://picsum.photos/200/200?random=${Date.now()}`,
      weeklyPlan: {
        days: WEEK_DAYS.map(day => ({
          dayOfWeek: day,
          exercises: [],
          focus: 'A definir'
        }))
      },
      progress: []
    };

    setStudents([newStudent, ...students]);
    setSelectedStudentId(newStudent.id);
    setViewState('STUDENT_DETAILS');
    setShowCreateModal(false);

    // Reset form
    setFormData({
      name: '',
      age: 25,
      goal: 'Hipertrofia',
      level: 'Iniciante',
      restrictions: ''
    });
  };

  const filteredStudents = students.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.goal.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const activeStudent = students.find(s => s.id === selectedStudentId);

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 flex">
      {/* Sidebar - Desktop */}
      <aside className="hidden lg:flex flex-col w-64 border-r border-slate-800 bg-slate-900 h-screen sticky top-0 p-6">
        <div className="flex items-center gap-3 mb-10">
          <div className="bg-lime-500 p-2 rounded-lg">
            <Dumbbell className="text-slate-900 w-6 h-6" />
          </div>
          <span className="text-xl font-bold tracking-tight">Personal<span className="text-lime-400">Pro</span></span>
        </div>

        <nav className="space-y-2 flex-1">
          <button 
            onClick={() => setViewState('DASHBOARD')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${
              viewState === 'DASHBOARD' 
              ? 'bg-slate-800 text-lime-400 shadow-sm' 
              : 'text-slate-400 hover:bg-slate-800/50 hover:text-slate-200'
            }`}
          >
            <LayoutDashboard size={20} />
            Dashboard
          </button>
          <div className="pt-4">
            <div className="px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Gestão</div>
             <button 
              onClick={() => setViewState('DASHBOARD')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium ${
                viewState === 'STUDENT_DETAILS' 
                ? 'bg-slate-800 text-lime-400 shadow-sm' 
                : 'text-slate-400 hover:bg-slate-800/50 hover:text-slate-200'
              }`}
            >
              <Users size={20} />
              Alunos
            </button>
          </div>
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-800">
