                  <span className="text-xs font-bold text-green-400 bg-green-400/10 px-2 py-1 rounded">+2 novos</span>
                </div>
                <h3 className="text-slate-400 text-sm font-medium mb-1">Total de Alunos</h3>
                <p className="text-3xl font-bold text-white">{students.length}</p>
