               <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-sm">
                <div className="flex justify-between items-start mb-4">
                  <div className="p-3 bg-lime-500/10 rounded-xl">
                    <Dumbbell className="text-lime-400" size={24} />
                  </div>
                </div>
                <h3 className="text-slate-400 text-sm font-medium mb-1">Treinos Ativos</h3>
                <p className="text-3xl font-bold text-white">{students.filter(s => s.weeklyPlan.days.some(d => d.exercises.length > 0)).length}</p>
              </div>
            </div>

            {/* Student List Section */}
            <section>
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-bold text-white">Seus Alunos</h2>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
                  <input 
                    type="text" 
                    placeholder="Buscar aluno..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="bg-slate-800 border border-slate-700 text-white pl-10 pr-4 py-2 rounded-xl focus:border-lime-500 outline-none w-64 transition-all"
                  />
