              {filteredStudents.length === 0 ? (
                <div className="bg-slate-800/50 border-2 border-dashed border-slate-700 rounded-2xl p-12 text-center">
                  <Users className="mx-auto text-slate-600 mb-4" size={48} />
                  <p className="text-slate-400 text-lg">Nenhum aluno encontrado.</p>
                  <button onClick={() => setShowCreateModal(true)} className="text-lime-400 font-bold mt-2 hover:underline">Cadastrar novo aluno</button>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                  {filteredStudents.map(student => (
                    <div 
                      key={student.id}
                      onClick={() => handleStudentClick(student.id)}
                      className="bg-slate-800 p-6 rounded-2xl border border-slate-700 hover:border-lime-500/50 cursor-pointer group transition-all hover:shadow-xl hover:-translate-y-1"
                    >
                      <div className="flex items-center gap-4 mb-4">
                        <img 
                          src={student.avatarUrl} 
                          alt={student.name} 
                          className="w-14 h-14 rounded-full object-cover border-2 border-slate-600 group-hover:border-lime-400 transition-colors"
                        />
                        <div>
                          <h3 className="font-bold text-lg text-white group-hover:text-lime-400 transition-colors">{student.name}</h3>
                          <p className="text-sm text-slate-400">{student.level} • {student.age} anos</p>
                        </div>
                      </div>

                      <div className="bg-slate-900/50 rounded-xl p-3 mb-4">
                        <p className="text-xs text-slate-500 uppercase font-bold mb-1">Objetivo</p>
                        <p className="text-sm text-white font-medium">{student.goal}</p>
                      </div>

                      <div className="flex items-center justify-between text-sm text-slate-400 group-hover:text-white transition-colors">
                        <span>Ver ficha completa</span>
                        <ChevronRight size={18} className="text-slate-600 group-hover:text-lime-400 group-hover:translate-x-1 transition-all" />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </section>
          </div>
        )}

        {viewState === 'STUDENT_DETAILS' && activeStudent && (
          <StudentDetails 
            student={activeStudent} 
            onBack={() => setViewState('DASHBOARD')}
            onUpdateStudent={handleUpdateStudent}
          />
        )}
      </main>

      {/* Create Student Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center p-4 z-50">
          <div className="bg-slate-800 rounded-3xl p-8 w-full max-w-lg border border-slate-700 shadow-2xl animate-fade-in">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-white">Novo Aluno</h2>
              <button onClick={() => setShowCreateModal(false)} className="text-slate-500 hover:text-white transition-colors">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleConfirmCreate} className="space-y-5">
              <div>
                <label className="block text-xs uppercase text-slate-500 font-bold mb-2">Nome Completo</label>
                <input 
                  autoFocus
                  required
                  type="text"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white focus:border-lime-500 focus:ring-1 focus:ring-lime-500 outline-none transition-all"
                  placeholder="Ex: João das Neves"
                />
