              </div>

              <div>
                <label className="block text-xs uppercase text-slate-500 font-bold mb-2">Objetivo Principal</label>
                <input 
                  type="text"
                  value={formData.goal}
                  onChange={e => setFormData({...formData, goal: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white focus:border-lime-500 outline-none"
                  placeholder="Ex: Emagrecimento, Hipertrofia..."
                />
