              <div>
                <label className="block text-xs uppercase text-slate-500 font-bold mb-2">Restrições Médicas / Observações</label>
                <textarea 
                  value={formData.restrictions}
                  onChange={e => setFormData({...formData, restrictions: e.target.value})}
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white focus:border-lime-500 outline-none h-24 resize-none"
                  placeholder="Ex: Lesão no joelho, hipertensão..."
