              </div>

              <div className="pt-4 flex gap-3">
                <button 
                  type="button"
                  onClick={() => setShowCreateModal(false)}
                  className="flex-1 px-4 py-3 rounded-xl font-bold text-slate-400 hover:bg-slate-700 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 bg-lime-500 hover:bg-lime-600 text-slate-900 px-4 py-3 rounded-xl font-bold transition-all shadow-lg hover:shadow-lime-500/20"
