              </div>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .animate-fade-in {
          animation: fadeIn 0.4s ease-out;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Student, WeeklyPlan, DayPlan, Exercise, MuscleGroup, ProgressEntry, Measurements } from '../types';
import { generateWorkoutPlan } from '../services/geminiService';
import { ArrowLeft, BrainCircuit, Loader2, Plus, Trash2, Dumbbell, Video, LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X } from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationNote, setGenerationNote] = useState("");
  const [showGenModal, setShowGenModal] = useState(false);

  // Progress state
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [newProgress, setNewProgress] = useState<Partial<ProgressEntry>>({
    weight: 0,
    measurements: {},
    photos: []
  });

  // Exercise editing state
  const [showAddExercise, setShowAddExercise] = useState(false);
  const [newExercise, setNewExercise] = useState<Partial<Exercise>>({
    name: '',
    sets: 3,
    reps: '10',
    muscleGroup: MuscleGroup.FULL_BODY
  });

  const currentDay = student.weeklyPlan.days[selectedDayIndex];

  const handleGeneratePlan = async () => {
    setIsGenerating(true);
    const newPlan = await generateWorkoutPlan(student, generationNote);
    if (newPlan) {
      onUpdateStudent({ ...student, weeklyPlan: newPlan });
      setShowGenModal(false);
    }
    setIsGenerating(false);
  };

  const handleAddExercise = () => {
    if (!newExercise.name) return;

    const exerciseToAdd: Exercise = {
      id: `man-${Date.now()}`,
      name: newExercise.name,
      muscleGroup: newExercise.muscleGroup as MuscleGroup,
      sets: newExercise.sets || 3,
      reps: newExercise.reps || '10',
      notes: newExercise.notes,
      videoUrl: newExercise.videoUrl || `https://www.youtube.com/results?search_query=${encodeURIComponent(newExercise.name || '')}`
    };

    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: [...updatedDays[selectedDayIndex].exercises, exerciseToAdd]
    };

    onUpdateStudent({
      ...student,
      weeklyPlan: { days: updatedDays }
    });

    setShowAddExercise(false);
    setNewExercise({ name: '', sets: 3, reps: '10', muscleGroup: MuscleGroup.FULL_BODY });
  };

  const handleDeleteExercise = (exId: string) => {
    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: updatedDays[selectedDayIndex].exercises.filter(e => e.id !== exId)
    };
    onUpdateStudent({ ...student, weeklyPlan: { days: updatedDays } });
  };

  const handleAddProgress = () => {
    if (!newProgress.weight) return;

    const entry: ProgressEntry = {
      id: `p-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      weight: newProgress.weight || 0,
      measurements: newProgress.measurements as Measurements,
      photos: newProgress.photos || []
    };

    onUpdateStudent({
      ...student,
      progress: [entry, ...(student.progress || [])]
    });

    setShowProgressModal(false);
    setNewProgress({ weight: 0, measurements: {}, photos: [] });
  };

  return (
    <div className="animate-fade-in space-y-6 pb-20">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-700">
        <div className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="p-2 hover:bg-slate-700 rounded-full transition-colors text-slate-400 hover:text-white"
          >
            <ArrowLeft size={24} />
          </button>
          <img 
            src={student.avatarUrl} 
            alt={student.name} 
            className="w-16 h-16 rounded-full border-2 border-lime-400 object-cover"
          />
          <div>
            <h1 className="text-2xl font-bold text-white">{student.name}</h1>
            <div className="flex gap-2 text-sm text-slate-400 mt-1">
              <span className="bg-slate-900 px-2 py-0.5 rounded text-lime-400 font-medium">{student.goal}</span>
              <span className="bg-slate-900 px-2 py-0.5 rounded">{student.level}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex bg-slate-900 p-1 rounded-xl border border-slate-700">
            <button 
              onClick={() => setActiveTab('WORKOUT')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-semibold transition-all ${
                activeTab === 'WORKOUT' ? 'bg-lime-500 text-slate-900' : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              <Dumbbell size={18} />
              <span className="hidden sm:inline">Treino</span>
            </button>
            <button 
              onClick={() => setActiveTab('PROGRESS')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-semibold transition-all ${
                activeTab === 'PROGRESS' ? 'bg-lime-500 text-slate-900' : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              <LineChart size={18} />
              <span className="hidden sm:inline">Evolução</span>
            </button>
          </div>

          {activeTab === 'WORKOUT' && (
            <button 
              onClick={() => setShowGenModal(true)}
              className="hidden md:flex items-center gap-2 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white px-5 py-2.5 rounded-xl font-bold transition-all shadow-lg hover:shadow-indigo-500/25 border border-indigo-400/20"
            >
              <BrainCircuit size={20} />
              <span>IA</span>
            </button>
          )}
        </div>
      </div>

      {activeTab === 'WORKOUT' ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Mobile IA Button */}
          <button 
            onClick={() => setShowGenModal(true)}
            className="md:hidden flex items-center justify-center gap-2 bg-gradient-to-r from-indigo-500 to-purple-600 text-white p-4 rounded-xl font-bold transition-all shadow-lg"
          >
            <BrainCircuit size={20} />
            <span>Gerar Treino com IA</span>
          </button>

          {/* Weekly Tabs */}
          <div className="lg:col-span-3 flex lg:flex-col overflow-x-auto lg:overflow-visible gap-2 pb-2 lg:pb-0">
            {student.weeklyPlan.days.map((day, idx) => (
              <button
                key={day.dayOfWeek}
                onClick={() => setSelectedDayIndex(idx)}
                className={`flex flex-col items-start p-4 rounded-xl transition-all min-w-[120px] lg:w-full border ${
                  selectedDayIndex === idx 
                    ? 'bg-lime-500 text-slate-900 border-lime-400 shadow-md scale-[1.02]' 
                    : 'bg-slate-800 text-slate-400 border-slate-700 hover:bg-slate-750'
                }`}
              >
                <span className="text-sm font-semibold opacity-75 uppercase tracking-wide">{day.dayOfWeek}</span>
                <span className="font-bold text-lg truncate w-full text-left">{day.focus || 'Descanso'}</span>
                <span className="text-xs mt-2 font-medium opacity-60">{day.exercises.length} Exercícios</span>
              </button>
            ))}
          </div>

          {/* Day Details */}
          <div className="lg:col-span-9 bg-slate-800 rounded-2xl p-6 border border-slate-700 min-h-[500px]">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                  {currentDay.dayOfWeek} 
                  <span className="text-slate-500">/</span> 
                  <span className="text-lime-400">{currentDay.focus}</span>
                </h2>
              </div>
              <button 
                onClick={() => setShowAddExercise(true)}
                className="flex items-center gap-2 bg-slate-700 hover:bg-slate-600 text-white px-4 py-2 rounded-lg transition-colors text-sm font-medium border border-slate-600"
              >
                <Plus size={18} />
                Adicionar
              </button>
            </div>

            {currentDay.exercises.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-64 text-slate-500 border-2 border-dashed border-slate-700 rounded-xl">
                <Dumbbell size={48} className="mb-4 opacity-20" />
                <p>Nenhum exercício programado para este dia.</p>
                <p className="text-sm">Adicione exercícios manualmente ou use a IA.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {currentDay.exercises.map((ex) => (
                  <div key={ex.id} className="bg-slate-900/50 p-4 rounded-xl border border-slate-700 hover:border-slate-600 transition-all group relative">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs font-bold text-slate-500 uppercase tracking-wider bg-slate-800 px-2 py-0.5 rounded">
                            {ex.muscleGroup}
                          </span>
                          {ex.videoUrl && (
                            <a href={ex.videoUrl} target="_blank" rel="noreferrer" className="text-indigo-400 hover:text-indigo-300">
                              <Video size={14} />
                            </a>
                          )}
                        </div>
                        <h3 className="text-lg font-bold text-white mb-2">{ex.name}</h3>
                        <div className="flex flex-wrap gap-4 text-sm text-slate-300">
                          <div className="flex flex-col"><span className="text-slate-500 text-xs">Séries</span><span className="text-lime-400 font-bold text-lg">{ex.sets}</span></div>
                          <div className="flex flex-col"><span className="text-slate-500 text-xs">Repetições</span><span className="text-white font-bold text-lg">{ex.reps}</span></div>
                          {ex.notes && <div className="flex flex-col flex-1"><span className="text-slate-500 text-xs">Observações</span><span className="italic text-slate-400">{ex.notes}</span></div>}
                        </div>
                      </div>
                      <button onClick={() => handleDeleteExercise(ex.id)} className="opacity-0 group-hover:opacity-100 p-2 text-red-400 hover:bg-red-400/10 rounded-lg">
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      ) : (
        /* Progress Tab Content */
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 flex flex-col items-center justify-center text-center">
              <Scale className="text-lime-400 mb-2" size={32} />
              <span className="text-slate-400 text-sm">Peso Atual</span>
              <span className="text-3xl font-bold text-white">
                {student.progress && student.progress.length > 0 ? `${student.progress[0].weight} kg` : '--'}
              </span>
            </div>
            <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 flex flex-col items-center justify-center text-center">
              <Calendar className="text-indigo-400 mb-2" size={32} />
              <span className="text-slate-400 text-sm">Última Avaliação</span>
              <span className="text-xl font-bold text-white">
                {student.progress && student.progress.length > 0 ? student.progress[0].date : 'Nenhuma'}
              </span>
            </div>
            <div className="md:col-span-2 bg-slate-800 p-6 rounded-2xl border border-slate-700 flex items-center justify-between">
              <div>
                <h3 className="text-lg font-bold text-white">Histórico de Medidas</h3>
                <p className="text-slate-400 text-sm">Acompanhe a evolução física do aluno.</p>
              </div>
              <button 
                onClick={() => setShowProgressModal(true)}
                className="bg-lime-500 hover:bg-lime-600 text-slate-900 px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg"
              >
                <Plus size={20} />
                Novo Registro
              </button>
            </div>
          </div>

          <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700">
            <h3 className="text-xl font-bold text-white mb-6">Linha do Tempo</h3>
            {(!student.progress || student.progress.length === 0) ? (
              <div className="text-center py-20 text-slate-500">
                <Ruler size={48} className="mx-auto mb-4 opacity-20" />
                <p>Nenhum registro de evolução ainda.</p>
              </div>
            ) : (
              <div className="space-y-6">
                {student.progress.map((entry, idx) => (
                  <div key={entry.id} className="relative pl-8 border-l-2 border-slate-700 pb-8 last:pb-0">
                    <div className="absolute left-[-9px] top-0 w-4 h-4 rounded-full bg-lime-400 border-4 border-slate-800"></div>
                    <div className="bg-slate-900/40 border border-slate-700 p-6 rounded-2xl hover:border-slate-500 transition-all">
                      <div className="flex flex-wrap items-start justify-between gap-4 mb-4">
                        <div>
                          <span className="text-lime-400 font-bold text-sm tracking-widest uppercase">{entry.date}</span>
                          <h4 className="text-2xl font-bold text-white">{entry.weight} kg</h4>
                        </div>
                        <div className="flex gap-2">
                           {entry.photos && entry.photos.map((photo, pIdx) => (
                             <img key={pIdx} src={photo} alt="Progress" className="w-16 h-24 object-cover rounded-lg border border-slate-600" />
                           ))}
                        </div>
                      </div>

                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                        {Object.entries(entry.measurements).map(([key, val]) => (
                          val && (
                            <div key={key} className="bg-slate-800/50 p-3 rounded-xl border border-slate-700">
                              <span className="text-slate-500 text-xs uppercase block">{key === 'chest' ? 'Peito' : key === 'waist' ? 'Cintura' : key === 'hips' ? 'Quadril' : key === 'bicepsR' ? 'Braço D' : key === 'bicepsL' ? 'Braço E' : key === 'thighR' ? 'Coxa D' : key === 'thighL' ? 'Coxa E' : key}</span>
