import { GoogleGenAI, Type } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup, NutriPlan } from "../types";

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) {
    console.error("API Key not found");
    return null;
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Atue como um Personal Trainer de elite. Crie uma ficha de treino semanal completa (Segunda a Domingo) para o seguinte aluno:

    Nome: ${student.name}
    Idade: ${student.age}
    Nível: ${student.level}
    Objetivo Principal: ${student.goal}
    Restrições/Observações: ${student.restrictions || "Nenhuma"}

    Notas adicionais do treinador: ${notes}

    Para dias de descanso, deixe a lista de exercícios vazia e o foco como "Descanso" ou "Recuperação Ativa".
    Use termos técnicos em Português do Brasil.
    Para os grupos musculares, escolha um destes valores exatos:
    ${Object.values(MuscleGroup).join(', ')}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) return null;

    const data = JSON.parse(text);

    const processedPlan: WeeklyPlan = {
      days: data.days.map((day: any) => ({
        ...day,
        exercises: day.exercises.map((ex: any, idx: number) => ({
          ...ex,
          id: `gen-${Date.now()}-${idx}`,
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name + " exercicio")}`
        }))
      }))
    };

    return processedPlan;
  } catch (error) {
    console.error("Error generating workout plan:", error);
    return null;
  }
};

export const generateNutriPlan = async (student: Student, notes: string): Promise<NutriPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const latestWeight = student.progress && student.progress.length > 0 ? student.progress[0].weight : 75;

  const prompt = `
    Atue como um Nutricionista Esportivo de elite. Crie um plano alimentar semanal para:
    Nome: ${student.name}
    Peso: ${latestWeight}kg
    Objetivo: ${student.goal}
    Restrições: ${student.restrictions || "Nenhuma"}
    Notas do Coach: ${notes}

    Gere:
    1. Menu semanal (6 refeições/dia)
    2. 3 Receitas fitness detalhadas com macros
    3. Lista de compras organizada por categoria
    4. Alvos de macros diários (Proteína, Carbo, Gordura, Calorias)
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weeklyMeals: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  meals: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        time: { type: Type.STRING },
                        label: { type: Type.STRING },
                        description: { type: Type.STRING }
                      }
                    }
                  }
                }
              }
            },
            recipes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                  instructions: { type: Type.STRING },
                  macros: {
                    type: Type.OBJECT,
                    properties: {
                      protein: { type: Type.NUMBER },
                      carbs: { type: Type.NUMBER },
                      fats: { type: Type.NUMBER },
                      calories: { type: Type.NUMBER }
                    }
                  }
                }
              }
            },
            shoppingList: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  category: { type: Type.STRING }
                }
              }
            },
            dailyMacrosTarget: {
              type: Type.OBJECT,
              properties: {
                protein: { type: Type.NUMBER },
                carbs: { type: Type.NUMBER },
                fats: { type: Type.NUMBER },
                calories: { type: Type.NUMBER }
              }
            }
          }
        }
      }
    });

    const data = JSON.parse(response.text);
    return {
      ...data,
      recipes: data.recipes.map((r: any, i: number) => ({ ...r, id: `rec-${i}` })),
      shoppingList: data.shoppingList.map((s: any) => ({ ...s, checked: false }))
    };
  } catch (e) {
    console.error(e);
    return null;
  }
};

import React, { useState } from 'react';
import { Student, WeeklyPlan, DayPlan, Exercise, MuscleGroup, ProgressEntry, Measurements, NutriPlan, Recipe } from '../types';
import { generateWorkoutPlan, generateNutriPlan } from '../services/geminiService';
import { 
  ArrowLeft, BrainCircuit, Loader2, Plus, Trash2, Dumbbell, Video, 
  LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X, 
  Apple, Utensils, ShoppingCart, Activity, Clock, ChevronDown, CheckSquare, Square
} from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationNote, setGenerationNote] = useState("");
  const [showGenModal, setShowGenModal] = useState(false);
  const [showNutriGenModal, setShowNutriGenModal] = useState(false);

  // Progress state
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [newProgress, setNewProgress] = useState<Partial<ProgressEntry>>({
    weight: 0,
    measurements: {},
    photos: []
  });

  // Exercise editing state
  const [showAddExercise, setShowAddExercise] = useState(false);
  const [newExercise, setNewExercise] = useState<Partial<Exercise>>({
    name: '',
    sets: 3,
    reps: '10',
    muscleGroup: MuscleGroup.FULL_BODY
  });

  const currentDay = student.weeklyPlan.days[selectedDayIndex];

  const handleGeneratePlan = async () => {
    setIsGenerating(true);
    const newPlan = await generateWorkoutPlan(student, generationNote);
    if (newPlan) {
      onUpdateStudent({ ...student, weeklyPlan: newPlan });
      setShowGenModal(false);
    }
    setIsGenerating(false);
  };

  const handleGenerateNutri = async () => {
    setIsGenerating(true);
    const plan = await generateNutriPlan(student, generationNote);
    if (plan) {
      onUpdateStudent({ ...student, nutriPlan: plan });
      setShowNutriGenModal(false);
    }
    setIsGenerating(false);
  };

  const toggleShoppingItem = (itemName: string) => {
    if (!student.nutriPlan) return;
    const updatedList = student.nutriPlan.shoppingList.map(i => 
      i.item === itemName ? { ...i, checked: !i.checked } : i
    );
    onUpdateStudent({
      ...student,
      nutriPlan: { ...student.nutriPlan, shoppingList: updatedList }
    });
  };

  const handleAddExercise = () => {
    if (!newExercise.name) return;
    const exerciseToAdd: Exercise = {
      id: `man-${Date.now()}`,
      name: newExercise.name,
      muscleGroup: newExercise.muscleGroup as MuscleGroup,
      sets: newExercise.sets || 3,
      reps: newExercise.reps || '10',
      notes: newExercise.notes,
      videoUrl: newExercise.videoUrl || `https://www.youtube.com/results?search_query=${encodeURIComponent(newExercise.name || '')}`
    };
    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: [...updatedDays[selectedDayIndex].exercises, exerciseToAdd]
    };
    onUpdateStudent({ ...student, weeklyPlan: { days: updatedDays } });
    setShowAddExercise(false);
    setNewExercise({ name: '', sets: 3, reps: '10', muscleGroup: MuscleGroup.FULL_BODY });
  };

  const handleDeleteExercise = (exId: string) => {
    const updatedDays = [...student.weeklyPlan.days];
    updatedDays[selectedDayIndex] = {
      ...updatedDays[selectedDayIndex],
      exercises: updatedDays[selectedDayIndex].exercises.filter(e => e.id !== exId)
    };
    onUpdateStudent({ ...student, weeklyPlan: { days: updatedDays } });
  };

  const handleAddProgress = () => {
    if (!newProgress.weight) return;
    const entry: ProgressEntry = {
      id: `p-${Date.now()}`,
      date: new Date().toISOString().split('T')[0],
      weight: newProgress.weight || 0,
      measurements: newProgress.measurements as Measurements,
      photos: newProgress.photos || []
    };
    onUpdateStudent({ ...student, progress: [entry, ...(student.progress || [])] });
    setShowProgressModal(false);
    setNewProgress({ weight: 0, measurements: {}, photos: [] });
  };

  return (
    <div className="animate-fade-in space-y-6 pb-20">
      {/* Header */}
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4 bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-700">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-700 rounded-full transition-colors text-slate-400 hover:text-white"><ArrowLeft size={24} /></button>
          <img src={student.avatarUrl} alt={student.name} className="w-16 h-16 rounded-full border-2 border-lime-400 object-cover" />
          <div>
            <h1 className="text-2xl font-bold text-white">{student.name}</h1>
            <div className="flex gap-2 text-sm text-slate-400 mt-1">
              <span className="bg-slate-900 px-2 py-0.5 rounded text-lime-400 font-medium">{student.goal}</span>
              <span className="bg-slate-900 px-2 py-0.5 rounded">{student.level}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 xl:pb-0">
          <div className="flex bg-slate-900 p-1 rounded-xl border border-slate-700 shrink-0">
            <button onClick={() => setActiveTab('WORKOUT')} className={`flex items-center gap-2 px-4 py-2 rounded-lg font-semibold transition-all ${activeTab === 'WORKOUT' ? 'bg-lime-500 text-slate-900' : 'text-slate-400 hover:text-slate-200'}`}>
