            </button>
            <button onClick={() => setActiveTab('PROGRESS')} className={`flex items-center gap-2 px-4 py-2 rounded-lg font-semibold transition-all ${activeTab === 'PROGRESS' ? 'bg-lime-500 text-slate-900' : 'text-slate-400 hover:text-slate-200'}`}>
              <LineChart size={18} /><span className="hidden sm:inline">Evolução</span>
            </button>
            <button onClick={() => setActiveTab('NUTRI')} className={`flex items-center gap-2 px-4 py-2 rounded-lg font-semibold transition-all ${activeTab === 'NUTRI' ? 'bg-lime-500 text-slate-900' : 'text-slate-400 hover:text-slate-200'}`}>
              <Apple size={18} /><span className="hidden sm:inline">Nutri IA</span>
            </button>
          </div>

          {activeTab === 'WORKOUT' && (
            <button onClick={() => setShowGenModal(true)} className="hidden md:flex items-center gap-2 bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white px-5 py-2.5 rounded-xl font-bold transition-all shadow-lg border border-indigo-400/20">
              <BrainCircuit size={20} /><span>IA</span>
