          )}
          {activeTab === 'NUTRI' && (
            <button onClick={() => setShowNutriGenModal(true)} className="hidden md:flex items-center gap-2 bg-gradient-to-r from-emerald-500 to-teal-600 hover:from-emerald-600 hover:to-teal-700 text-white px-5 py-2.5 rounded-xl font-bold transition-all shadow-lg border border-emerald-400/20">
