                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'PROGRESS' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 flex flex-col items-center justify-center text-center"><Scale className="text-lime-400 mb-2" size={32} /><span className="text-slate-400 text-sm">Peso Atual</span><span className="text-3xl font-bold text-white">{student.progress?.length ? `${student.progress[0].weight} kg` : '--'}</span></div>
            <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 flex flex-col items-center justify-center text-center"><Calendar className="text-indigo-400 mb-2" size={32} /><span className="text-slate-400 text-sm">Última Avaliação</span><span className="text-xl font-bold text-white">{student.progress?.length ? student.progress[0].date : 'Nenhuma'}</span></div>
