                  <div key={item.key} className="bg-slate-900/30 p-3 rounded-xl border border-slate-700"><label className="block text-xs text-slate-500 mb-1">{item.label} (cm)</label><input type="number" value={newProgress.measurements?.[item.key as keyof Measurements] || ''} onChange={e => setNewProgress({...newProgress, measurements: {...newProgress.measurements, [item.key]: parseFloat(e.target.value)}})} className="bg-transparent text-white font-bold w-full outline-none" /></div>
                ))}
              </div>
            </div>
            <div className="flex gap-3 mt-8"><button onClick={() => setShowProgressModal(false)} className="flex-1 px-4 py-3 rounded-xl font-bold text-slate-400 hover:bg-slate-700">Cancelar</button><button onClick={handleAddProgress} className="flex-1 bg-lime-500 hover:bg-lime-600 text-slate-900 px-4 py-3 rounded-xl font-bold shadow-lg">Salvar Avaliação</button></div>
