          <div className="bg-slate-800 rounded-2xl p-6 w-full max-w-lg border border-slate-700 shadow-2xl">
            <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2"><BrainCircuit className="text-purple-500" />Gerar Ficha com IA</h3>
            <p className="text-slate-400 mb-4 text-sm">Descreva o foco específico para esta semana.</p>
            <textarea value={generationNote} onChange={(e) => setGenerationNote(e.target.value)} placeholder="Ex: Focar em deltoide lateral..." className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl p-3 h-32 mb-6 outline-none resize-none focus:ring-2 focus:ring-purple-500" />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowGenModal(false)} className="px-4 py-2 text-slate-300 hover:text-white">Cancelar</button>
              <button onClick={handleGeneratePlan} disabled={isGenerating} className="bg-gradient-to-r from-indigo-500 to-purple-600 text-white px-6 py-2 rounded-xl font-semibold flex items-center gap-2">
                {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <BrainCircuit size={20} />}
                {isGenerating ? 'Gerando...' : 'Gerar Ficha'}
              </button>
            </div>
          </div>
        </div>
      )}

      {showNutriGenModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-slate-800 rounded-2xl p-6 w-full max-w-lg border border-slate-700 shadow-2xl">
            <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2"><BrainCircuit className="text-emerald-500" />Gerar Dieta com IA</h3>
            <p className="text-slate-400 mb-4 text-sm">Informe preferências alimentares ou alergias.</p>
            <textarea value={generationNote} onChange={(e) => setGenerationNote(e.target.value)} placeholder="Ex: Dieta sem lactose, foco em pré-treino..." className="w-full bg-slate-900 text-white border border-slate-700 rounded-xl p-3 h-32 mb-6 outline-none resize-none focus:ring-2 focus:ring-emerald-500" />
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowNutriGenModal(false)} className="px-4 py-2 text-slate-300 hover:text-white">Cancelar</button>
              <button onClick={handleGenerateNutri} disabled={isGenerating} className="bg-gradient-to-r from-emerald-500 to-teal-600 text-white px-6 py-2 rounded-xl font-semibold flex items-center gap-2">
                {isGenerating ? <Loader2 className="animate-spin" size={20} /> : <BrainCircuit size={20} />}
                {isGenerating ? 'Calculando Dieta...' : 'Gerar Dieta'}
              </button>
