              <select value={newExercise.muscleGroup} onChange={e => setNewExercise({...newExercise, muscleGroup: e.target.value as MuscleGroup})} className="w-full bg-slate-900 border border-slate-700 rounded-lg p-2 text-white outline-none focus:border-lime-500">
