              </div>
            </div>
            <div className="flex justify-end gap-3 mt-6">
              <button onClick={() => setShowAddExercise(false)} className="px-4 py-2 text-slate-300 hover:text-white">Cancelar</button>
              <button onClick={handleAddExercise} className="bg-lime-500 text-slate-900 px-6 py-2 rounded-lg font-bold">Adicionar</button>
            </div>
