            </div>

            <div className="space-y-5">
              <div>
                <label className="flex items-center gap-2 text-xs font-bold text-slate-500 uppercase mb-2">
                  Nome do Exercício
                  <Info size={12} className="text-slate-600" />
                </label>
                <input 
                  autoFocus
                  type="text" 
                  value={newExercise.name} 
                  onChange={e => setNewExercise({...newExercise, name: e.target.value})} 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white outline-none focus:border-lime-500 transition-all" 
                  placeholder="Ex: Supino Reto, Agachamento Livre..." 
                />
              </div>

              <div>
                <label className="text-xs font-bold text-slate-500 uppercase block mb-2">Grupo Muscular Principal</label>
                <select 
                  value={newExercise.muscleGroup} 
                  onChange={e => setNewExercise({...newExercise, muscleGroup: e.target.value as MuscleGroup})} 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white outline-none focus:border-lime-500 transition-all"
                >
                  {Object.values(MuscleGroup).map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase block mb-2">Séries</label>
                  <input 
                    type="number" 
                    value={newExercise.sets} 
                    onChange={e => setNewExercise({...newExercise, sets: parseInt(e.target.value) || 0})} 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white outline-none focus:border-lime-500 transition-all" 
                    placeholder="Ex: 4" 
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase block mb-2">Repetições</label>
                  <input 
                    type="text" 
                    value={newExercise.reps} 
                    onChange={e => setNewExercise({...newExercise, reps: e.target.value})} 
                    className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white outline-none focus:border-lime-500 transition-all" 
                    placeholder="Ex: 12 ou Falha" 
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-500 uppercase block mb-2">Notas e Instruções (Opcional)</label>
                <textarea 
                  value={newExercise.notes} 
                  onChange={e => setNewExercise({...newExercise, notes: e.target.value})} 
                  className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-white outline-none focus:border-lime-500 h-20 resize-none transition-all" 
                  placeholder="Ex: 2 min de descanso, foco na cadência excêntrica..." 
                />
              </div>
            </div>

            <div className="flex gap-3 mt-8">
              <button onClick={() => setShowAddExercise(false)} className="flex-1 px-4 py-3 rounded-xl font-bold text-slate-400 hover:bg-slate-700 transition-all">Cancelar</button>
              <button onClick={handleAddExercise} className="flex-1 bg-lime-500 text-slate-900 px-4 py-3 rounded-xl font-bold shadow-lg shadow-lime-500/10 hover:bg-lime-600 transition-all">Adicionar à Ficha</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
