import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup, NutriPlan, YogaPlan, ProgressEntry } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como Personal Trainer. Crie um treino semanal para ${student.name}, objetivo: ${student.goal}, nível: ${student.level}. Restrições: ${student.restrictions}. Notas: ${notes}. Retorne JSON com estrutura de dias e exercícios.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          }
        }
      }
    });
    const data = JSON.parse(response.text);
    return {
      days: data.days.map((day: any) => ({
        ...day,
        exercises: day.exercises.map((ex: any, i: number) => ({
          ...ex,
          id: `ex-${Date.now()}-${i}`,
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name)}`
        }))
      }))
    };
  } catch (e) { console.error(e); return null; }
};

export const generateYogaPlan = async (student: Student, focus: string): Promise<YogaPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como instrutor de Yoga experiente. Crie uma prática personalizada para:
    Aluno: ${student.name}
    Nível: ${student.level}
    Foco desejado: ${focus || student.goal}
    Restrições: ${student.restrictions}
    Gere uma sequência de 6 a 8 posturas (asanas) detalhando nome, duração e benefícios.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            level: { type: Type.STRING },
            duration: { type: Type.NUMBER },
            poses: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  duration: { type: Type.STRING },
                  description: { type: Type.STRING },
                  benefits: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) { console.error(e); return null; }
};

export const generateProgressInsights = async (student: Student): Promise<string> => {
  if (!process.env.API_KEY || !student.progress.length) return "";
  const ai = getAI();
  const latest = student.progress[0];
  const prompt = `Analise a evolução física deste aluno:
    Nome: ${student.name}, Objetivo: ${student.goal}.
    Peso: ${latest.weight}kg, Altura: ${student.height}cm.
    Medidas: ${JSON.stringify(latest.measurements)}.
    Gere um parágrafo curto de incentivo e sugestão técnica de treino/dieta em Português.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt
    });
    return response.text || "";
  } catch (e) { return "Continue focado em seus objetivos!"; }
};

export const generateMeditationAudio = async (theme: string): Promise<string | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Gere um script curto de meditação guiada (máximo 100 palavras) sobre ${theme}. Fale calmamente.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      }
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (e) { return null; }
};

