export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);

  // Audio state
  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // BMI Calculation
  const latestWeight = student.progress.length ? student.progress[0].weight : 0;
  const bmi = latestWeight && student.height ? (latestWeight / Math.pow(student.height / 100, 2)).toFixed(1) : '0';

  const getBmiStatus = (val: number) => {
    if (val < 18.5) return { label: 'Abaixo do peso', color: 'text-blue-400' };
    if (val < 25) return { label: 'Peso normal', color: 'text-lime-400' };
    if (val < 30) return { label: 'Sobrepeso', color: 'text-yellow-400' };
    return { label: 'Obesidade', color: 'text-red-400' };
  };

  // Logic to handle AI-based workout generation
  const handleGenWorkout = async () => {
    setIsGenerating(true);
    const plan = await generateWorkoutPlan(student, student.restrictions || "");
    if (plan) onUpdateStudent({ ...student, weeklyPlan: plan });
    setIsGenerating(false);
  };

  const handleGenYoga = async () => {
    setIsGenerating(true);
    const plan = await generateYogaPlan(student, "");
    if (plan) onUpdateStudent({ ...student, yogaPlan: plan });
    setIsGenerating(false);
  };

  const handleGenInsights = async () => {
    setIsGenerating(true);
    const insights = await generateProgressInsights(student);
    const updatedProgress = [...student.progress];
    if (updatedProgress.length) {
      updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
      onUpdateStudent({ ...student, progress: updatedProgress });
    }
    setIsGenerating(false);
  };

  const playMeditation = async (theme: string) => {
    setIsGenerating(true);
    const data = await generateMeditationAudio(theme);
    if (data) {
      setAudioBase64(data);
      setIsPlaying(true);
    }
    setIsGenerating(false);
  };

  return (
    <div className="animate-fade-in space-y-8 pb-32">
      {/* Dynamic Header */}
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6 bg-[#1e293b] p-8 rounded-[2.5rem] shadow-2xl border border-slate-800">
        <div className="flex items-center gap-6">
          <Tooltip text="Voltar para lista">
            <button onClick={onBack} className="p-3 hover:bg-slate-800 rounded-2xl transition-all text-slate-400 hover:text-white border border-slate-700">
              <ArrowLeft size={24} />
            </button>
          </Tooltip>
          <img src={student.avatarUrl} className="w-20 h-20 rounded-[1.5rem] border-4 border-lime-400 object-cover shadow-xl shadow-lime-400/10" />
          <div onClick={() => setShowEditStudentModal(true)} className="cursor-pointer group">
            <div className="flex items-center gap-3">
              <h1 className="text-3xl font-black text-white group-hover:text-lime-400 transition-all">{student.name}</h1>
              <Edit2 size={18} className="text-slate-600 opacity-0 group-hover:opacity-100 transition-all" />
            </div>
            <div className="flex gap-2 mt-2">
              <span className="bg-slate-900 px-3 py-1 rounded-lg text-lime-400 text-xs font-black uppercase tracking-widest">{student.goal}</span>
              <span className="bg-slate-900 px-3 py-1 rounded-lg text-slate-400 text-xs font-black uppercase tracking-widest">{student.level}</span>
            </div>
