import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup, NutriPlan, YogaPlan, ProgressEntry } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como Personal Trainer de elite. Crie um treino semanal completo para ${student.name}, objetivo: ${student.goal}, nível: ${student.level}. Restrições: ${student.restrictions}. Notas: ${notes}. Retorne JSON com estrutura de dias e exercícios. Para grupos musculares use: ${Object.values(MuscleGroup).join(', ')}.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          }
        }
      }
    });
    const data = JSON.parse(response.text);
    return {
      days: data.days.map((day: any) => ({
        ...day,
        exercises: day.exercises.map((ex: any, i: number) => ({
          ...ex,
          id: `ex-${Date.now()}-${i}`,
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name + " exercicio")}`
        }))
      }))
    };
  } catch (e) { console.error(e); return null; }
};

export const generateYogaPlan = async (student: Student, focus: string): Promise<YogaPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como instrutor de Yoga experiente. Crie uma prática personalizada para:
    Aluno: ${student.name}
    Nível: ${student.level}
    Foco desejado: ${focus || student.goal}
    Restrições: ${student.restrictions}
    Gere uma sequência de 6 a 8 posturas (asanas) detalhando nome, duração e benefícios.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            level: { type: Type.STRING },
            duration: { type: Type.NUMBER },
            poses: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  duration: { type: Type.STRING },
                  description: { type: Type.STRING },
                  benefits: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) { console.error(e); return null; }
};

export const generateProgressInsights = async (student: Student): Promise<string> => {
  if (!process.env.API_KEY || !student.progress.length) return "";
  const ai = getAI();
  const latest = student.progress[0];
  const prompt = `Analise a evolução física deste aluno:
    Nome: ${student.name}, Objetivo: ${student.goal}.
    Peso: ${latest.weight}kg, Altura: ${student.height}cm.
    Medidas: ${JSON.stringify(latest.measurements)}.
    Gere um parágrafo curto de incentivo e sugestão técnica de treino/dieta em Português.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt
    });
    return response.text || "";
  } catch (e) { return "Continue focado em seus objetivos!"; }
};

export const generateMeditationAudio = async (theme: string): Promise<string | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Gere um script curto de meditação guiada (máximo 100 palavras) sobre ${theme}. Fale calmamente.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      }
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (e) { return null; }
};

export const generateNutriPlan = async (student: Student, notes: string): Promise<NutriPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como um Nutricionista Esportivo de elite. Crie um plano alimentar semanal para:
    Nome: ${student.name}, Peso: ${student.progress[0]?.weight || 70}kg, Objetivo: ${student.goal}.
    Notas: ${notes}.
    Retorne JSON com: weeklyMeals (7 dias, 5-6 refeições/dia), recipes (3 receitas), shoppingList (organizada por categoria), dailyMacrosTarget.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weeklyMeals: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  meals: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        time: { type: Type.STRING },
                        label: { type: Type.STRING },
                        description: { type: Type.STRING }
                      }
                    }
                  }
                }
              }
            },
            recipes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                  instructions: { type: Type.STRING },
                  macros: {
                    type: Type.OBJECT,
                    properties: {
                      protein: { type: Type.NUMBER },
                      carbs: { type: Type.NUMBER },
                      fats: { type: Type.NUMBER },
                      calories: { type: Type.NUMBER }
                    }
                  }
                }
              }
            },
            shoppingList: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  category: { type: Type.STRING }
                }
              }
            },
            dailyMacrosTarget: {
              type: Type.OBJECT,
              properties: {
                protein: { type: Type.NUMBER },
                carbs: { type: Type.NUMBER },
                fats: { type: Type.NUMBER },
                calories: { type: Type.NUMBER }
              }
            }
          }
        }
      }
    });

    const data = JSON.parse(response.text);
    return {
      ...data,
      recipes: data.recipes.map((r: any, i: number) => ({ ...r, id: `rec-${i}` })),
      shoppingList: data.shoppingList.map((s: any) => ({ ...s, checked: false }))
    };
  } catch (e) {
    console.error("Erro ao gerar dieta:", e);
    return null;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Student, WeeklyPlan, DayPlan, Exercise, MuscleGroup, ProgressEntry, Measurements, YogaPlan, NutriPlan } from '../types';
import { generateWorkoutPlan, generateYogaPlan, generateProgressInsights, generateMeditationAudio, generateNutriPlan } from '../services/geminiService';
import { 
  ArrowLeft, BrainCircuit, Loader2, Plus, Trash2, Dumbbell, Video, 
  LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X, 
  Apple, Utensils, ShoppingCart, Activity, Clock, Edit2, Info,
  Sparkles, Flower2, Wind, Timer, Play, CheckCircle2, Circle
} from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

const Tooltip: React.FC<{ text: string; children: React.ReactNode }> = ({ text, children }) => (
  <div className="relative group">
    {children}
    <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 bg-slate-950 text-white text-[10px] font-bold rounded-lg opacity-0 group-hover:opacity-100 transition-all pointer-events-none whitespace-nowrap z-[100] border border-slate-800 shadow-2xl">
      {text}
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-950"></div>
    </div>
  </div>
);

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);

  // Audio state
  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // BMI Calculation
  const latestWeight = student.progress.length ? student.progress[0].weight : 0;
  const bmi = latestWeight && student.height ? (latestWeight / Math.pow(student.height / 100, 2)).toFixed(1) : '0';

  const getBmiStatus = (val: number) => {
    if (val < 18.5) return { label: 'Abaixo do peso', color: 'text-blue-400' };
    if (val < 25) return { label: 'Peso normal', color: 'text-lime-400' };
    if (val < 30) return { label: 'Sobrepeso', color: 'text-yellow-400' };
    return { label: 'Obesidade', color: 'text-red-400' };
  };

  const handleGenWorkout = async () => {
    setIsGenerating(true);
    const plan = await generateWorkoutPlan(student, student.restrictions || "");
    if (plan) onUpdateStudent({ ...student, weeklyPlan: plan });
    setIsGenerating(false);
  };

  const handleGenYoga = async () => {
    setIsGenerating(true);
    const plan = await generateYogaPlan(student, "");
    if (plan) onUpdateStudent({ ...student, yogaPlan: plan });
    setIsGenerating(false);
  };

  const handleGenNutri = async () => {
    setIsGenerating(true);
    const plan = await generateNutriPlan(student, "");
    if (plan) onUpdateStudent({ ...student, nutriPlan: plan });
    setIsGenerating(false);
  };

  const handleGenInsights = async () => {
    setIsGenerating(true);
    const insights = await generateProgressInsights(student);
    const updatedProgress = [...student.progress];
    if (updatedProgress.length) {
      updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
      onUpdateStudent({ ...student, progress: updatedProgress });
    }
    setIsGenerating(false);
  };

  const playMeditation = async (theme: string) => {
    setIsGenerating(true);
    const data = await generateMeditationAudio(theme);
    if (data) {
      setAudioBase64(data);
      setIsPlaying(true);
    }
    setIsGenerating(false);
  };

  const toggleShoppingItem = (itemName: string) => {
    if (!student.nutriPlan) return;
    const updatedList = student.nutriPlan.shoppingList.map(i => 
      i.item === itemName ? { ...i, checked: !i.checked } : i
    );
    onUpdateStudent({
      ...student,
      nutriPlan: { ...student.nutriPlan, shoppingList: updatedList }
    });
  };

  return (
    <div className="animate-fade-in space-y-8 pb-32">
      {/* Dynamic Header */}
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6 bg-[#1e293b] p-8 rounded-[2.5rem] shadow-2xl border border-slate-800">
        <div className="flex items-center gap-6">
          <Tooltip text="Voltar para lista">
            <button onClick={onBack} className="p-3 hover:bg-slate-800 rounded-2xl transition-all text-slate-400 hover:text-white border border-slate-700">
              <ArrowLeft size={24} />
            </button>
          </Tooltip>
          <img src={student.avatarUrl} className="w-20 h-20 rounded-[1.5rem] border-4 border-lime-400 object-cover shadow-xl shadow-lime-400/10" />
          <div onClick={() => setShowEditStudentModal(true)} className="cursor-pointer group">
            <div className="flex items-center gap-3">
              <h1 className="text-3xl font-black text-white group-hover:text-lime-400 transition-all">{student.name}</h1>
              <Edit2 size={18} className="text-slate-600 opacity-0 group-hover:opacity-100 transition-all" />
            </div>
            <div className="flex gap-2 mt-2">
              <span className="bg-slate-900 px-3 py-1 rounded-lg text-lime-400 text-xs font-black uppercase tracking-widest">{student.goal}</span>
              <span className="bg-slate-900 px-3 py-1 rounded-lg text-slate-400 text-xs font-black uppercase tracking-widest">{student.level}</span>
            </div>
          </div>
        </div>

        <nav className="flex bg-slate-900/50 p-1.5 rounded-3xl border border-slate-800 overflow-x-auto no-scrollbar">
          {[
            { id: 'WORKOUT', icon: Dumbbell, label: 'Treino', color: 'lime-400' },
            { id: 'PROGRESS', icon: LineChart, label: 'Evolução', color: 'indigo-400' },
            { id: 'NUTRI', icon: Apple, label: 'Nutri', color: 'emerald-400' },
            { id: 'YOGA', icon: Flower2, label: 'Yoga', color: 'purple-400' },
            { id: 'MEDITATION', icon: Wind, label: 'Mente', color: 'sky-400' },
          ].map(tab => (
            <Tooltip key={tab.id} text={`Abrir aba de ${tab.label}`}>
              <button 
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex items-center gap-2 px-5 py-3 rounded-2xl font-black transition-all ${
                  activeTab === tab.id ? `bg-slate-800 text-${tab.color}` : 'text-slate-500 hover:text-slate-300'
                }`}
              >
                <tab.icon size={20} />
                <span className="hidden sm:inline uppercase text-[10px] tracking-widest">{tab.label}</span>
              </button>
            </Tooltip>
          ))}
        </nav>
      </div>

      {activeTab === 'WORKOUT' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-3 space-y-3">
             {student.weeklyPlan.days.map((day, idx) => (
                <button key={idx} onClick={() => setSelectedDayIndex(idx)} className={`w-full p-6 rounded-3xl border transition-all text-left group ${selectedDayIndex === idx ? 'bg-lime-400 border-lime-400 text-slate-900 shadow-xl' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>
                  <p className="text-[10px] font-black uppercase mb-1 opacity-60 tracking-tighter">{day.dayOfWeek}</p>
                  <p className="font-black text-lg leading-tight">{day.focus || 'Descanso'}</p>
                </button>
             ))}
             <button onClick={handleGenWorkout} disabled={isGenerating} className="w-full mt-6 bg-gradient-to-br from-indigo-500 to-purple-600 p-6 rounded-3xl text-white font-black flex items-center justify-between shadow-2xl active:scale-95 transition-all">
                <span>{isGenerating ? 'GERANDO...' : 'INTELIGÊNCIA IA'}</span>
                {isGenerating ? <Loader2 className="animate-spin" /> : <BrainCircuit />}
             </button>
          </div>
          <div className="lg:col-span-9 bg-[#1e293b] rounded-[2.5rem] p-10 border border-slate-800">
             <div className="flex justify-between items-center mb-10">
                <h2 className="text-3xl font-black text-white italic underline decoration-lime-400 decoration-8 underline-offset-8">PROGRAMAÇÃO</h2>
                <Tooltip text="Adicionar exercício avulso">
                   <button className="bg-slate-800 p-4 rounded-2xl text-white hover:bg-slate-700 transition-all border border-slate-700"><Plus size={24} /></button>
                </Tooltip>
             </div>
             {student.weeklyPlan.days[selectedDayIndex].exercises.map(ex => (
                <div key={ex.id} className="bg-slate-900/40 border border-slate-800/50 p-8 rounded-[2rem] mb-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-6 hover:border-lime-400/30 transition-all">
                   <div>
                      <span className="text-xs font-black text-lime-400 uppercase tracking-widest">{ex.muscleGroup}</span>
                      <h3 className="text-2xl font-black text-white mt-1">{ex.name}</h3>
                      <p className="text-slate-500 mt-2 font-medium">{ex.notes}</p>
                   </div>
                   <div className="flex items-center gap-10">
                      <div className="text-center">
                         <p className="text-slate-500 text-[10px] font-black uppercase">Séries</p>
                         <p className="text-3xl font-black text-white">{ex.sets}</p>
                      </div>
                      <div className="text-center">
                         <p className="text-slate-500 text-[10px] font-black uppercase">Reps</p>
                         <p className="text-3xl font-black text-white">{ex.reps}</p>
                      </div>
                      <Tooltip text="Ver execução em vídeo">
                         <a href={ex.videoUrl} target="_blank" className="p-4 bg-slate-800 rounded-2xl text-lime-400 hover:scale-110 transition-all"><Video size={24} /></a>
                      </Tooltip>
                   </div>
                </div>
             ))}
          </div>
        </div>
      )}

      {activeTab === 'PROGRESS' && (
        <div className="space-y-8">
           <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="bg-[#1e293b] p-8 rounded-[2.5rem] border border-slate-800 shadow-xl relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-8 opacity-5"><Scale size={100} /></div>
                 <h4 className="text-slate-500 font-black uppercase tracking-widest text-[10px] mb-4">Massa Corporal</h4>
                 <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-white">{latestWeight}</span>
                    <span className="text-xl font-bold text-slate-500">KG</span>
                 </div>
              </div>
              <div className="bg-[#1e293b] p-8 rounded-[2.5rem] border border-slate-800 shadow-xl relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-8 opacity-5"><Activity size={100} /></div>
                 <h4 className="text-slate-500 font-black uppercase tracking-widest text-[10px] mb-4">Índice IMC</h4>
                 <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-white">{bmi}</span>
                    <span className={`text-sm font-black uppercase ${getBmiStatus(parseFloat(bmi)).color}`}>{getBmiStatus(parseFloat(bmi)).label}</span>
                 </div>
              </div>
              <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-8 rounded-[2.5rem] shadow-xl flex flex-col justify-between">
                 <div>
                    <h4 className="text-indigo-200 font-black uppercase tracking-widest text-[10px] mb-2">IA Coach Analysis</h4>
                    <p className="text-white text-sm font-medium leading-relaxed italic">{student.progress[0]?.aiInsights || "Aguardando próxima avaliação para gerar insights estratégicos."}</p>
                 </div>
                 <button onClick={handleGenInsights} disabled={isGenerating} className="mt-4 bg-white/20 hover:bg-white/30 p-3 rounded-xl text-white font-black text-[10px] uppercase tracking-tighter flex items-center justify-center gap-2 transition-all">
                    {isGenerating ? <Loader2 className="animate-spin" /> : <Sparkles size={14} />} 
                    Atualizar Diagnóstico
                 </button>
              </div>
           </div>

           <div className="bg-[#1e293b] rounded-[2.5rem] p-10 border border-slate-800">
              <div className="flex justify-between items-center mb-10">
                 <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Medidas Antropométricas</h3>
                 <button onClick={() => setShowProgressModal(true)} className="bg-lime-400 text-slate-900 px-6 py-3 rounded-2xl font-black flex items-center gap-2 shadow-xl hover:scale-95 transition-all">
                    <Plus size={20} /> Novo Check-in
                 </button>
              </div>
              {student.progress.map(entry => (
                 <div key={entry.id} className="bg-slate-900/40 p-8 rounded-[2rem] border border-slate-800/50 mb-6">
                    <div className="flex justify-between items-center mb-8">
                       <p className="text-lime-400 font-black text-lg">{entry.date}</p>
                       <p className="text-white font-bold">{entry.weight} kg</p>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-6">
                       {Object.entries(entry.measurements).map(([key, val]) => (
                          <div key={key} className="bg-slate-800/50 p-4 rounded-2xl border border-slate-700 text-center">
                             <p className="text-slate-500 font-black text-[10px] uppercase mb-1">{key}</p>
                             <p className="text-white font-black text-xl">{val}cm</p>
                          </div>
                       ))}
                    </div>
                 </div>
              ))}
           </div>
        </div>
      )}

      {activeTab === 'NUTRI' && (
        <div className="space-y-8 animate-fade-in">
           {!student.nutriPlan ? (
              <div className="bg-[#1e293b] rounded-[3rem] p-20 text-center border border-slate-800 shadow-2xl relative overflow-hidden">
                 <Apple size={80} className="mx-auto text-emerald-400 mb-8" />
                 <h2 className="text-4xl font-black text-white mb-4 tracking-tighter">Alimentação Estratégica</h2>
                 <p className="text-slate-400 max-w-lg mx-auto text-lg mb-12">Gere um plano alimentar otimizado com IA baseado no seu peso e meta de {student.goal}.</p>
                 <button onClick={handleGenNutri} disabled={isGenerating} className="bg-emerald-500 hover:bg-emerald-600 text-slate-900 px-12 py-5 rounded-3xl font-black text-xl shadow-2xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-4 mx-auto">
                    {isGenerating ? <Loader2 className="animate-spin" /> : <BrainCircuit />}
                    Gerar Plano Nutricional
                 </button>
              </div>
           ) : (
             <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
               <div className="lg:col-span-3 space-y-4">
                  <div className="bg-[#1e293b] p-6 rounded-3xl border border-slate-800">
                    <h4 className="text-slate-500 font-black uppercase text-[10px] mb-4">Meta Diária</h4>
                    <div className="space-y-2">
                      <div className="flex justify-between"><span className="text-slate-400">Proteínas</span><span className="text-white font-bold">{student.nutriPlan.dailyMacrosTarget.protein}g</span></div>
                      <div className="flex justify-between"><span className="text-slate-400">Carbos</span><span className="text-white font-bold">{student.nutriPlan.dailyMacrosTarget.carbs}g</span></div>
                      <div className="flex justify-between"><span className="text-slate-400">Gorduras</span><span className="text-white font-bold">{student.nutriPlan.dailyMacrosTarget.fats}g</span></div>
                      <div className="pt-2 border-t border-slate-800 flex justify-between"><span className="text-emerald-400 font-black">Calorias</span><span className="text-emerald-400 font-black">{student.nutriPlan.dailyMacrosTarget.calories}</span></div>
                    </div>
                  </div>
                  <div className="flex lg:flex-col overflow-x-auto gap-2">
                    {student.nutriPlan.weeklyMeals.map((day, idx) => (
                      <button key={idx} onClick={() => setSelectedNutriDayIndex(idx)} className={`p-4 rounded-2xl border transition-all text-left whitespace-nowrap lg:whitespace-normal ${selectedNutriDayIndex === idx ? 'bg-emerald-500 border-emerald-500 text-slate-900 shadow-xl' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>
                        <span className="font-black text-sm">{day.dayOfWeek}</span>
                      </button>
                    ))}
                  </div>
               </div>
               <div className="lg:col-span-9 space-y-8">
                 <div className="bg-[#1e293b] rounded-[2.5rem] p-10 border border-slate-800">
                    <h3 className="text-2xl font-black text-white mb-8">Refeições - {student.nutriPlan.weeklyMeals[selectedNutriDayIndex].dayOfWeek}</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {student.nutriPlan.weeklyMeals[selectedNutriDayIndex].meals.map((meal, i) => (
                        <div key={i} className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800">
                          <div className="flex items-center justify-between mb-2">
                            <span className="text-emerald-400 font-black text-xs">{meal.time}</span>
                            <span className="text-white font-black">{meal.label}</span>
                          </div>
                          <p className="text-slate-400 text-sm">{meal.description}</p>
                        </div>
                      ))}
                    </div>
                 </div>
                 <div className="bg-[#1e293b] rounded-[2.5rem] p-10 border border-slate-800">
                    <h3 className="text-2xl font-black text-white mb-8">Lista de Compras</h3>
                    <div className="columns-1 md:columns-2 gap-8">
                       {student.nutriPlan.shoppingList.map((item, i) => (
                         <div key={i} onClick={() => toggleShoppingItem(item.item)} className="flex items-center gap-3 mb-3 cursor-pointer group">
                           {item.checked ? <CheckCircle2 className="text-emerald-400" size={20} /> : <Circle className="text-slate-700 group-hover:text-slate-500" size={20} />}
                           <span className={`font-medium ${item.checked ? 'text-slate-600 line-through' : 'text-slate-200'}`}>{item.item}</span>
                         </div>
                       ))}
                    </div>
                 </div>
               </div>
             </div>
           )}
        </div>
      )}

      {activeTab === 'YOGA' && (
        <div className="space-y-8 animate-fade-in">
           {!student.yogaPlan ? (
              <div className="bg-[#1e293b] rounded-[3rem] p-20 text-center border border-slate-800 shadow-2xl relative overflow-hidden">
                 <div className="absolute inset-0 bg-gradient-to-b from-purple-500/5 to-transparent pointer-events-none"></div>
                 <Flower2 size={80} className="mx-auto text-purple-400 mb-8 animate-pulse" />
                 <h2 className="text-4xl font-black text-white mb-4 tracking-tighter">Prática Milenar</h2>
                 <p className="text-slate-400 max-w-lg mx-auto text-lg mb-12">Combine força e flexibilidade com uma rotina de Yoga desenhada especificamente para seu biotipo e restrições.</p>
                 <button onClick={handleGenYoga} disabled={isGenerating} className="bg-purple-500 hover:bg-purple-600 text-white px-12 py-5 rounded-3xl font-black text-xl shadow-2xl shadow-purple-500/20 active:scale-95 transition-all flex items-center gap-4 mx-auto">
                    {isGenerating ? <Loader2 className="animate-spin" /> : <Sparkles />}
                    Gerar Sequência Yoga
                 </button>
              </div>
           ) : (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                 <div className="lg:col-span-4 bg-gradient-to-br from-purple-600 to-indigo-700 p-10 rounded-[2.5rem] shadow-2xl text-white">
                    <h3 className="text-4xl font-black mb-4 tracking-tighter">{student.yogaPlan.name}</h3>
                    <div className="flex gap-4 mb-8">
                       <span className="bg-white/20 px-3 py-1 rounded-lg text-xs font-black uppercase tracking-widest">{student.yogaPlan.level}</span>
                       <span className="bg-white/20 px-3 py-1 rounded-lg text-xs font-black uppercase tracking-widest">{student.yogaPlan.duration} MIN</span>
                    </div>
                    <p className="text-indigo-100 font-medium leading-relaxed italic">"O yoga não trata de se tocar nos pés, mas sim do que aprendemos no caminho até lá."</p>
                    <button onClick={handleGenYoga} className="w-full mt-10 bg-white text-purple-600 py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-slate-100 transition-all">
                       <BrainCircuit size={20} /> Atualizar Sequência
                    </button>
                 </div>
                 <div className="lg:col-span-8 space-y-6">
                    {student.yogaPlan.poses.map((pose, i) => (
                       <div key={i} className="bg-[#1e293b] p-8 rounded-[2rem] border border-slate-800 hover:border-purple-500/30 transition-all flex flex-col md:flex-row justify-between gap-6">
                          <div className="flex-1">
                             <div className="flex items-center gap-3 mb-2">
                                <span className="bg-purple-500 text-white w-8 h-8 rounded-full flex items-center justify-center font-black text-sm">{i+1}</span>
                                <h4 className="text-2xl font-black text-white">{pose.name}</h4>
                             </div>
                             <p className="text-slate-400 font-medium mb-4">{pose.description}</p>
                             <div className="flex items-center gap-2 text-purple-400 text-xs font-black uppercase tracking-widest">
                                <Sparkles size={14} /> {pose.benefits}
                             </div>
                          </div>
                          <div className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800 flex flex-col items-center justify-center min-w-[120px]">
                             <Clock size={24} className="text-slate-600 mb-2" />
                             <p className="text-white font-black text-xl">{pose.duration}</p>
                          </div>
                       </div>
                    ))}
                 </div>
              </div>
           )}
        </div>
      )}

      {activeTab === 'MEDITATION' && (
        <div className="space-y-8 animate-fade-in">
           <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-8">
                 <div className="bg-[#1e293b] p-10 rounded-[3rem] border border-slate-800 shadow-2xl">
                    <h3 className="text-3xl font-black text-white mb-8 tracking-tighter flex items-center gap-4">
                       <Wind className="text-sky-400" />
                       Guia de Mindfulness IA
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                       {['Foco Profundo', 'Sono Restaurador', 'Calma Instantânea', 'Visualização de Metas'].map(theme => (
                          <button key={theme} onClick={() => playMeditation(theme)} className="bg-slate-900/50 border border-slate-800 p-6 rounded-[2rem] hover:border-sky-400/50 transition-all flex items-center justify-between group">
                             <div className="text-left">
                                <h4 className="text-white font-black text-lg">{theme}</h4>
                                <p className="text-slate-500 text-xs uppercase font-bold tracking-widest">IA Vocal Guide</p>
                             </div>
                             <div className="bg-sky-400 text-slate-900 p-3 rounded-2xl group-hover:scale-110 transition-all">
                                <Play size={20} fill="currentColor" />
                             </div>
                          </button>
                       ))}
                    </div>
                    {isPlaying && (
                       <div className="mt-10 p-6 bg-sky-500/10 rounded-3xl border border-sky-400/20 flex items-center justify-between">
                          <div className="flex items-center gap-4 text-sky-400">
                             <div className="animate-pulse bg-sky-400 w-3 h-3 rounded-full"></div>
                             <span className="font-black uppercase tracking-widest text-xs">Transmitindo Guia IA...</span>
                          </div>
                          <button onClick={() => setIsPlaying(false)} className="text-slate-400 hover:text-white transition-colors"><X /></button>
                       </div>
                    )}
                 </div>

                 <div className="bg-[#1e293b] p-10 rounded-[3rem] border border-slate-800">
                    <h3 className="text-2xl font-black text-white mb-8 tracking-tighter">Desafios de Hábito</h3>
                    <div className="space-y-4">
                       {student.meditationChallenges.map((challenge, i) => (
