        <div className="flex items-center gap-6">
          <Tooltip text="Voltar para lista">
            <button onClick={onBack} className="p-3 hover:bg-slate-800 rounded-2xl transition-all text-slate-400 hover:text-white border border-slate-700">
              <ArrowLeft size={24} />
            </button>
          </Tooltip>
          <img src={student.avatarUrl} className="w-20 h-20 rounded-[1.5rem] border-4 border-lime-400 object-cover shadow-xl shadow-lime-400/10" />
          <div onClick={() => setShowEditStudentModal(true)} className="cursor-pointer group">
            <div className="flex items-center gap-3">
              <h1 className="text-3xl font-black text-white group-hover:text-lime-400 transition-all">{student.name}</h1>
              <Edit2 size={18} className="text-slate-600 opacity-0 group-hover:opacity-100 transition-all" />
            </div>
            <div className="flex gap-2 mt-2">
              <span className="bg-slate-900 px-3 py-1 rounded-lg text-lime-400 text-xs font-black uppercase tracking-widest">{student.goal}</span>
              <span className="bg-slate-900 px-3 py-1 rounded-lg text-slate-400 text-xs font-black uppercase tracking-widest">{student.level}</span>
            </div>
          </div>
        </div>

        <nav className="flex bg-slate-900/50 p-1.5 rounded-3xl border border-slate-800 overflow-x-auto no-scrollbar">
          {[
            { id: 'WORKOUT', icon: Dumbbell, label: 'Treino', color: 'lime-400' },
            { id: 'PROGRESS', icon: LineChart, label: 'Evolução', color: 'indigo-400' },
            { id: 'NUTRI', icon: Apple, label: 'Nutri', color: 'emerald-400' },
            { id: 'YOGA', icon: Flower2, label: 'Yoga', color: 'purple-400' },
            { id: 'MEDITATION', icon: Wind, label: 'Mente', color: 'sky-400' },
          ].map(tab => (
            <Tooltip key={tab.id} text={`Abrir aba de ${tab.label}`}>
              <button 
                onClick={() => setActiveTab(tab.id as any)}
                className={`flex items-center gap-2 px-5 py-3 rounded-2xl font-black transition-all ${
                  activeTab === tab.id ? `bg-slate-800 text-${tab.color}` : 'text-slate-500 hover:text-slate-300'
                }`}
              >
                <tab.icon size={20} />
                <span className="hidden sm:inline uppercase text-[10px] tracking-widest">{tab.label}</span>
              </button>
            </Tooltip>
          ))}
        </nav>
      </div>

      {activeTab === 'WORKOUT' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-3 space-y-3">
             {student.weeklyPlan.days.map((day, idx) => (
                <button key={idx} onClick={() => setSelectedDayIndex(idx)} className={`w-full p-6 rounded-3xl border transition-all text-left group ${selectedDayIndex === idx ? 'bg-lime-400 border-lime-400 text-slate-900 shadow-xl' : 'bg-slate-800 border-slate-700 text-slate-400'}`}>
                  <p className="text-[10px] font-black uppercase mb-1 opacity-60 tracking-tighter">{day.dayOfWeek}</p>
                  <p className="font-black text-lg leading-tight">{day.focus || 'Descanso'}</p>
                </button>
             ))}
             <button onClick={handleGenWorkout} disabled={isGenerating} className="w-full mt-6 bg-gradient-to-br from-indigo-500 to-purple-600 p-6 rounded-3xl text-white font-black flex items-center justify-between shadow-2xl active:scale-95 transition-all">
                <span>{isGenerating ? 'GERANDO...' : 'INTELIGÊNCIA IA'}</span>
                {isGenerating ? <Loader2 className="animate-spin" /> : <BrainCircuit />}
             </button>
          </div>
          <div className="lg:col-span-9 bg-[#1e293b] rounded-[2.5rem] p-10 border border-slate-800">
             <div className="flex justify-between items-center mb-10">
                <h2 className="text-3xl font-black text-white italic underline decoration-lime-400 decoration-8 underline-offset-8">PROGRAMAÇÃO</h2>
                <Tooltip text="Adicionar exercício avulso">
                   <button className="bg-slate-800 p-4 rounded-2xl text-white hover:bg-slate-700 transition-all border border-slate-700"><Plus size={24} /></button>
                </Tooltip>
