             ) : (
               student.weeklyPlan.days[selectedDayIndex].exercises.map(ex => (
                  <div key={ex.id} className="bg-slate-900/40 border border-slate-800/50 p-8 rounded-[2rem] mb-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-6 hover:border-lime-400/30 transition-all">
                     <div>
                        <span className="text-xs font-black text-lime-400 uppercase tracking-widest">{ex.muscleGroup}</span>
                        <h3 className="text-2xl font-black text-white mt-1">{ex.name}</h3>
                        <p className="text-slate-500 mt-2 font-medium">{ex.notes}</p>
