                     <div className="flex items-center gap-10">
                        <div className="text-center">
                           <p className="text-slate-500 text-[10px] font-black uppercase">Séries</p>
                           <p className="text-3xl font-black text-white">{ex.sets}</p>
                        </div>
                        <div className="text-center">
                           <p className="text-slate-500 text-[10px] font-black uppercase">Reps</p>
                           <p className="text-3xl font-black text-white">{ex.reps}</p>
                        </div>
                        <Tooltip text="Ver execução em vídeo">
                           <a href={ex.videoUrl} target="_blank" rel="noreferrer" className="p-4 bg-slate-800 rounded-2xl text-lime-400 hover:scale-110 transition-all"><Video size={24} /></a>
                        </Tooltip>
                     </div>
                  </div>
               ))
             )}
          </div>
        </div>
      )}

      {activeTab === 'PROGRESS' && (
        <div className="space-y-8">
           <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="bg-[#1e293b] p-8 rounded-[2.5rem] border border-slate-800 shadow-xl relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-8 opacity-5"><Scale size={100} /></div>
                 <h4 className="text-slate-500 font-black uppercase tracking-widest text-[10px] mb-4">Massa Corporal</h4>
                 <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-white">{latestWeight}</span>
                    <span className="text-xl font-bold text-slate-500">KG</span>
                 </div>
              </div>
              <div className="bg-[#1e293b] p-8 rounded-[2.5rem] border border-slate-800 shadow-xl relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-8 opacity-5"><Activity size={100} /></div>
                 <h4 className="text-slate-500 font-black uppercase tracking-widest text-[10px] mb-4">Índice IMC</h4>
                 <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-white">{bmi}</span>
                    <span className={`text-sm font-black uppercase ${getBmiStatus(parseFloat(bmi)).color}`}>{getBmiStatus(parseFloat(bmi)).label}</span>
