              </div>
              <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-8 rounded-[2.5rem] shadow-xl flex flex-col justify-between">
                 <div>
                    <h4 className="text-indigo-200 font-black uppercase tracking-widest text-[10px] mb-2">IA Coach Analysis</h4>
                    <p className="text-white text-sm font-medium leading-relaxed italic">{student.progress[0]?.aiInsights || "Aguardando próxima avaliação para gerar insights estratégicos."}</p>
                 </div>
                 <button onClick={handleGenInsights} disabled={isGenerating} className="mt-4 bg-white/20 hover:bg-white/30 p-3 rounded-xl text-white font-black text-[10px] uppercase tracking-tighter flex items-center justify-center gap-2 transition-all">
                    {isGenerating ? <Loader2 className="animate-spin" /> : <Sparkles size={14} />} 
                    Atualizar Diagnóstico
                 </button>
              </div>
           </div>

           <div className="bg-[#1e293b] rounded-[2.5rem] p-10 border border-slate-800">
              <div className="flex justify-between items-center mb-10">
                 <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Medidas Antropométricas</h3>
                 <button onClick={() => setShowProgressModal(true)} className="bg-lime-400 text-slate-900 px-6 py-3 rounded-2xl font-black flex items-center gap-2 shadow-xl hover:scale-95 transition-all">
