                 <button onClick={handleGenNutri} disabled={isGenerating} className="bg-emerald-500 hover:bg-emerald-600 text-slate-900 px-12 py-5 rounded-3xl font-black text-xl shadow-2xl shadow-emerald-500/20 active:scale-95 transition-all flex items-center gap-4 mx-auto">
