                    <div className="flex gap-4 mb-8">
                       <span className="bg-white/20 px-3 py-1 rounded-lg text-xs font-black uppercase tracking-widest">{student.yogaPlan.level}</span>
                       <span className="bg-white/20 px-3 py-1 rounded-lg text-xs font-black uppercase tracking-widest">{student.yogaPlan.duration} MIN</span>
