                             <div className="flex items-center gap-3 mb-2">
                                <span className="bg-purple-500 text-white w-8 h-8 rounded-full flex items-center justify-center font-black text-sm">{i+1}</span>
                                <h4 className="text-2xl font-black text-white">{pose.name}</h4>
                             </div>
                             <p className="text-slate-400 font-medium mb-4">{pose.description}</p>
