                       </div>
                    )}
                 </div>

                 <div className="bg-[#1e293b] p-10 rounded-[3rem] border border-slate-800">
                    <h3 className="text-2xl font-black text-white mb-8 tracking-tighter flex items-center justify-between">
                       Desafios Semanais
                       <Tooltip text="Sua jornada de consistência mental">
                          <Info size={16} className="text-slate-600" />
                       </Tooltip>
                    </h3>
                    <div className="space-y-4">
                       {student.meditationChallenges.length === 0 ? (
                         <div className="text-center py-10 text-slate-600 italic">Nenhum desafio ativo. Gere uma nova dieta ou treino para atualizar!</div>
                       ) : (
                         student.meditationChallenges.map((challenge, i) => (
                            <div key={i} className={`p-6 rounded-2xl border flex items-center justify-between transition-all ${challenge.completed ? 'bg-lime-400/5 border-lime-400/30' : 'bg-slate-900/50 border-slate-800'}`}>
                               <div className="flex items-center gap-4">
                                  {challenge.completed ? <CheckCircle2 className="text-lime-400" /> : <Circle className="text-slate-700" />}
                                  <div>
                                     <h4 className={`font-black ${challenge.completed ? 'text-lime-400 line-through' : 'text-white'}`}>{challenge.title}</h4>
                                     <p className="text-slate-500 text-sm font-medium">{challenge.description}</p>
                                  </div>
                               </div>
                            </div>
                         ))
                       )}
                    </div>
                 </div>
              </div>

              <div className="space-y-8">
                 {/* Functional Timer */}
                 <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-10 rounded-[3rem] border border-slate-700 shadow-2xl text-center relative overflow-hidden group">
                    <div className="absolute -top-10 -left-10 w-40 h-40 bg-sky-500/10 rounded-full blur-3xl group-hover:bg-sky-500/20 transition-all"></div>
                    <TimerIcon size={48} className="mx-auto text-sky-400 mb-6" />
                    <h4 className="text-white font-black text-5xl mb-2 tabular-nums tracking-tighter">{formatTime(timeLeft)}</h4>
                    <p className="text-slate-500 uppercase font-black text-[10px] tracking-widest mb-10">Tempo de Imersão</p>

                    <div className="flex flex-col gap-3">
                      <button 
                        onClick={() => setTimerRunning(!timerRunning)}
                        className={`w-full py-5 rounded-2xl font-black text-lg transition-all active:scale-95 flex items-center justify-center gap-3 ${
                          timerRunning ? 'bg-slate-700 text-white' : 'bg-sky-400 text-slate-900'
                        }`}
                      >
                        {timerRunning ? <Pause size={20} /> : <Play size={20} />}
                        {timerRunning ? 'PAUSAR' : 'INICIAR SESSÃO'}
                      </button>
                      <button 
                        onClick={() => { setTimerRunning(false); setTimeLeft(900); }}
                        className="w-full py-4 rounded-2xl font-black text-[10px] tracking-widest text-slate-500 hover:text-white transition-all flex items-center justify-center gap-2"
                      >
                        <RotateCcw size={14} /> REINICIAR TIMER
                      </button>
                    </div>
                 </div>

                 {/* Ambience Sounds */}
                 <div className="bg-[#1e293b] p-10 rounded-[3rem] border border-slate-800 shadow-xl">
                    <h3 className="text-xl font-black text-white mb-8 tracking-tighter flex items-center justify-between">
                      Sons Ambiente
                      <Volume2 size={18} className="text-slate-600" />
                    </h3>
                    <div className="space-y-3">
                       {['Chuva Tropical', 'Floresta Zen', 'Ondas do Mar', 'Ruído Branco'].map(sound => (
                          <button 
                            key={sound} 
                            onClick={() => setActiveAmbient(activeAmbient === sound ? null : sound)}
                            className={`w-full p-4 rounded-2xl flex items-center justify-between transition-all border ${
                              activeAmbient === sound ? 'bg-sky-500/10 border-sky-400/50 text-sky-400' : 'bg-slate-900/50 border-slate-800 text-slate-400 hover:border-slate-700'
                            }`}
                          >
                             <div className="flex items-center gap-3">
                                {activeAmbient === sound ? <Volume2 size={16} /> : <VolumeX size={16} className="opacity-20" />}
                                <span className="font-bold text-sm">{sound}</span>
                             </div>
                             {activeAmbient === sound && <div className="w-1 h-1 bg-sky-400 rounded-full animate-ping"></div>}
                          </button>
                       ))}
                    </div>
                    {activeAmbient && (
                      <p className="mt-6 text-[10px] font-black text-slate-600 uppercase text-center animate-pulse">Tocando loop ambiente...</p>
                    )}
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Improved Tooltip Component needed a bit more refinement in CSS to look "World Class" */}
      <style>{`
        .animate-fade-in { animation: fadeIn 0.5s cubic-bezier(0.16, 1, 0.3, 1); }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

        /* Modern range styling for audio */
        audio::-webkit-media-controls-panel {
          background-color: #0f172a;
        }
      `}</style>
    </div>
  );
};

export enum MuscleGroup {
  CHEST = 'Peitoral',
  BACK = 'Costas',
  LEGS = 'Pernas',
  SHOULDERS = 'Ombros',
  ARMS = 'Braços',
  CORE = 'Abdômen',
  CARDIO = 'Cardio',
  FULL_BODY = 'Corpo Todo'
}

export interface Exercise {
  id: string;
  name: string;
  muscleGroup: MuscleGroup;
  sets: number;
  reps: string;
  videoUrl?: string;
  notes?: string;
}

export interface DayPlan {
  dayOfWeek: string;
  exercises: Exercise[];
  focus: string;
}

export interface WeeklyPlan {
  days: DayPlan[];
}

export interface YogaPose {
  name: string;
  duration: string;
  description: string;
  benefits: string;
}

export interface YogaPlan {
  name: string;
  level: string;
  duration: number; // minutes
  poses: YogaPose[];
}

export interface Measurements {
  chest?: number;
  waist?: number;
  hips?: number;
  bicepsL?: number;
  bicepsR?: number;
  thighL?: number;
  thighR?: number;
  neck?: number;
  forearm?: number;
  calf?: number;
}

export interface ProgressEntry {
  id: string;
  date: string;
  weight: number;
  measurements: Measurements;
  photos: string[];
  aiInsights?: string;
}

export interface Meal {
  time: string;
  label: string;
  description: string;
}

export interface DayNutriPlan {
  dayOfWeek: string;
  meals: Meal[];
}

export interface Recipe {
  id: string;
  name: string;
  ingredients: string[];
  instructions: string;
  macros: { protein: number; carbs: number; fats: number; calories: number };
}

export interface ShoppingItem {
  item: string;
  category: string;
  checked: boolean;
}

export interface NutriPlan {
  weeklyMeals: DayNutriPlan[];
  recipes: Recipe[];
  shoppingList: ShoppingItem[];
  dailyMacrosTarget: { protein: number; carbs: number; fats: number; calories: number };
}

export interface MeditationChallenge {
  title: string;
  description: string;
  completed: boolean;
}

export interface Student {
  id: string;
  name: string;
  age: number;
  height: number; // in cm
  weight: number; // in kg
  sedentaryLevel: 'Sedentário' | 'Levemente Ativo' | 'Moderadamente Ativo' | 'Muito Ativo' | 'Atleta';
