import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup, NutriPlan, YogaPlan, ProgressEntry } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como Personal Trainer de elite. Crie um treino semanal completo para ${student.name}, objetivo: ${student.goal}, nível: ${student.level}. 
    Idade: ${student.age} anos, Peso: ${student.weight}kg, Sedentarismo: ${student.sedentaryLevel}.
    Restrições: ${student.restrictions}. Notas: ${notes}. Retorne JSON com estrutura de dias e exercícios. Para grupos musculares use: ${Object.values(MuscleGroup).join(', ')}.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          }
        }
      }
    });
    const data = JSON.parse(response.text);
    return {
      days: data.days.map((day: any) => ({
        ...day,
        exercises: day.exercises.map((ex: any, i: number) => ({
          ...ex,
          id: `ex-${Date.now()}-${i}`,
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name + " exercicio")}`
        }))
      }))
    };
  } catch (e) { console.error(e); return null; }
};

export const generateYogaPlan = async (student: Student, focus: string): Promise<YogaPlan | null> => {
