export const generateProgressInsights = async (student: Student): Promise<string> => {
  if (!process.env.API_KEY) return "";
  const ai = getAI();
  const latest = student.progress[0];
  const weightToUse = latest ? latest.weight : student.weight;
  const measurements = latest ? latest.measurements : {};

  const prompt = `Analise a evolução física deste aluno e forneça um diagnóstico COMPLETO e PROFISSIONAL:
    Nome: ${student.name}, Objetivo: ${student.goal}.
    Idade: ${student.age}, Altura: ${student.height}cm, Peso Atual: ${weightToUse}kg.
    Nível de Atividade (Sedentarismo): ${student.sedentaryLevel}.
    Medidas Antropométricas Atuais: ${JSON.stringify(measurements)}.
    Gere um diagnóstico de pelo menos 2 parágrafos cobrindo: 
    1. Análise do IMC e estado físico atual.
    2. Recomendações estratégicas de treinamento e ajuste metabólico baseado no nível de atividade.
    Seja motivador mas técnico em Português.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt
    });
    return response.text || "";
  } catch (e) { return "Continue focado em seus objetivos para vermos os próximos resultados!"; }
};

export const generateMeditationAudio = async (theme: string): Promise<string | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Gere um script curto de meditação guiada (máximo 100 palavras) sobre ${theme}. Fale calmamente.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      }
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (e) { return null; }
};

export const generateNutriPlan = async (student: Student, notes: string): Promise<NutriPlan | null> => {
