                 <div className="bg-[#1e293b] p-12 rounded-[3.5rem] border border-slate-800 shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none group-hover:scale-110 transition-transform">
                      <BrainCircuit size={160} />
                    </div>
                    <h3 className="text-3xl font-black text-white mb-10 tracking-tighter flex items-center gap-4">
                       <Wind className="text-sky-400" /> Mente Atenta IA
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                       {['Foco Profundo', 'Sono Restaurador', 'Calma Instantânea', 'Visualização de Metas'].map(theme => (
                          <button key={theme} onClick={() => playMeditation(theme)} className="w-full bg-slate-900/50 border border-slate-800 p-8 rounded-[2.5rem] hover:border-sky-400/50 transition-all flex items-center justify-between group cursor-pointer hover:shadow-xl hover:shadow-sky-500/5">
                             <div className="text-left">
                                <h4 className="text-white font-black text-xl mb-1">{theme}</h4>
                                <p className="text-slate-500 text-[10px] uppercase font-black tracking-widest opacity-60">Sessão Guiada</p>
                             </div>
                             <div className="bg-sky-400 text-slate-900 p-4 rounded-2xl group-hover:scale-110 transition-all shadow-lg shadow-sky-400/20">
                                {isGenerating ? <Loader2 className="animate-spin" size={24} /> : <Play size={24} fill="currentColor" />}
                             </div>
                          </button>
                       ))}
                    </div>

                    {audioBase64 && (
                       <div className="mt-12 p-10 bg-sky-500/5 rounded-[2.5rem] border border-sky-400/20 shadow-inner">
                          <div className="flex items-center justify-between mb-8">
                             <div className="flex items-center gap-4 text-sky-400">
                                <div className="animate-ping bg-sky-400 w-3 h-3 rounded-full"></div>
                                <span className="font-black uppercase tracking-widest text-[10px]">Reproduzindo Sessão IA</span>
                             </div>
                             <button onClick={() => { setAudioBase64(null); setIsPlayingIA(false); }} className="p-2 hover:bg-slate-800 rounded-xl transition-colors text-slate-500 hover:text-white">
                               <X size={24} />
                             </button>
                          </div>
                          <audio ref={audioRef} src={`data:audio/mp3;base64,${audioBase64}`} controls autoPlay={isPlayingIA} className="w-full h-12 filter invert opacity-90 custom-audio" />
                       </div>
                    )}
                 </div>

                 <div className="bg-[#1e293b] p-12 rounded-[3.5rem] border border-slate-800 shadow-xl">
                    <h3 className="text-2xl font-black text-white mb-10 tracking-tighter flex items-center justify-between">
                       Desafios de Hábito
                       <Info size={18} className="text-slate-700" />
                    </h3>
                    <div className="space-y-4">
                       {student.meditationChallenges.map((challenge, i) => (
                          <div key={i} className={`p-8 rounded-[2rem] border flex items-center justify-between transition-all group ${challenge.completed ? 'bg-lime-400/5 border-lime-400/20' : 'bg-slate-900/50 border-slate-800 hover:border-slate-700'}`}>
                             <div className="flex items-center gap-6">
                                {challenge.completed ? <CheckCircle2 className="text-lime-400" size={28} /> : <Circle className="text-slate-800 group-hover:text-slate-600" size={28} />}
                                <div>
                                   <h4 className={`font-black text-xl ${challenge.completed ? 'text-lime-400 line-through' : 'text-white'}`}>{challenge.title}</h4>
                                   <p className="text-slate-500 font-medium text-sm mt-1">{challenge.description}</p>
                                </div>
                             </div>
                          </div>
                       ))}
                    </div>
                 </div>
              </div>

              <div className="space-y-8">
                 <div className="bg-gradient-to-br from-[#0f172a] to-[#1e293b] p-12 rounded-[3.5rem] border border-slate-800 shadow-2xl text-center relative overflow-hidden group">
                    <div className="absolute inset-0 bg-sky-500/5 pointer-events-none group-hover:opacity-20 transition-opacity"></div>
                    <TimerIcon size={56} className="mx-auto text-sky-400 mb-8" />
                    <h4 className="text-white font-black text-6xl mb-3 tabular-nums tracking-tighter">{formatTime(timeLeft)}</h4>
                    <p className="text-slate-500 uppercase font-black text-[10px] tracking-widest mb-12 opacity-60">Timer de Imersão</p>

                    <div className="flex flex-col gap-4">
                      <button onClick={() => setTimerRunning(!timerRunning)} className={`w-full py-6 rounded-3xl font-black text-xl transition-all active:scale-95 flex items-center justify-center gap-4 shadow-xl ${timerRunning ? 'bg-slate-800 text-white' : 'bg-sky-400 text-slate-950 shadow-sky-400/20'}`}>
                        {timerRunning ? <Pause size={24} /> : <Play size={24} fill="currentColor" />}
                        {timerRunning ? 'PAUSAR' : 'RELAXAR AGORA'}
                      </button>
                      <button onClick={() => { setTimerRunning(false); setTimeLeft(900); }} className="w-full py-4 text-slate-600 hover:text-white font-black text-[10px] uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-2">
                        <RotateCcw size={14} /> Resetar
                      </button>
                    </div>
                 </div>

                 <div className="bg-[#1e293b] p-12 rounded-[3.5rem] border border-slate-800 shadow-xl">
                    <h3 className="text-xl font-black text-white mb-10 tracking-tighter flex items-center justify-between">
                      Sons Ambiente <Volume2 size={20} className="text-slate-700" />
                    </h3>
                    <div className="space-y-4">
                       {['Chuva Tropical', 'Floresta Zen', 'Ondas do Mar', 'Ruído Branco'].map(sound => (
                          <button key={sound} onClick={() => setActiveAmbient(activeAmbient === sound ? null : sound)} className={`w-full p-6 rounded-[1.5rem] flex items-center justify-between transition-all border ${activeAmbient === sound ? 'bg-sky-500/10 border-sky-400/50 text-sky-400' : 'bg-slate-900/50 border-slate-800 text-slate-500 hover:text-slate-300'}`}>
                             <div className="flex items-center gap-4">
                                {activeAmbient === sound ? <Volume2 size={20} className="animate-pulse" /> : <VolumeX size={20} className="opacity-30" />}
                                <span className="font-bold text-lg">{sound}</span>
                             </div>
                             {activeAmbient === sound && <div className="w-2 h-2 bg-sky-400 rounded-full animate-ping"></div>}
                          </button>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Manual Workout Editor Modal */}
      {showEditWorkoutModal && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6 z-[60]">
          <div className="bg-[#0f172a] rounded-[3rem] p-12 w-full max-w-5xl border border-slate-800 shadow-2xl overflow-y-auto max-h-[90vh] animate-scale-in">
            <div className="flex justify-between items-center mb-12">
              <h2 className="text-4xl font-black text-white tracking-tighter uppercase leading-none">
                EDITAR DIA: <span className="text-lime-400">{student.weeklyPlan.days[selectedDayIndex].dayOfWeek}</span>
              </h2>
              <button onClick={() => setShowEditWorkoutModal(false)} className="bg-slate-800 p-3 rounded-2xl text-slate-400 hover:text-white transition-all"><X size={32} /></button>
            </div>

            <div className="space-y-8">
              <div className="bg-slate-900/40 p-10 rounded-[2.5rem] border border-slate-800 shadow-inner">
                <label className="text-xs font-black text-slate-600 uppercase tracking-widest mb-4 block">Título do Foco do Dia</label>
                <input type="text" value={student.weeklyPlan.days[selectedDayIndex].focus} onChange={(e) => {
                     const updatedWeeklyPlan = { ...student.weeklyPlan };
                     updatedWeeklyPlan.days[selectedDayIndex].focus = e.target.value;
                     onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
                   }} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 text-white font-black text-3xl outline-none focus:ring-4 focus:ring-lime-400/20 transition-all" />
              </div>

              <div className="space-y-6">
                {student.weeklyPlan.days[selectedDayIndex].exercises.map((ex) => (
                  <div key={ex.id} className="bg-slate-900/60 p-10 rounded-[2.5rem] border border-slate-800 space-y-8 relative group hover:border-slate-600 transition-all">
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                      <div className="md:col-span-4">
                        <label className="text-[10px] font-black text-slate-700 uppercase mb-2 block tracking-widest">Exercício</label>
                        <input type="text" value={ex.name} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'name', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-5 text-white font-black text-xl" />
                      </div>
                      <div className="md:col-span-3">
                        <label className="text-[10px] font-black text-slate-700 uppercase mb-2 block tracking-widest">Grupo Muscular</label>
                        <select value={ex.muscleGroup} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'muscleGroup', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-5 text-white font-black text-lg appearance-none">
                          {Object.values(MuscleGroup).map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                      </div>
                      <div className="md:col-span-2">
                        <label className="text-[10px] font-black text-slate-700 uppercase mb-2 block tracking-widest">Sets</label>
                        <input type="number" value={ex.sets} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'sets', parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-5 text-white font-black text-2xl text-center" />
                      </div>
                      <div className="md:col-span-2">
                        <label className="text-[10px] font-black text-slate-700 uppercase mb-2 block tracking-widest">Reps</label>
                        <input type="text" value={ex.reps} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'reps', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-5 text-white font-black text-2xl text-center" />
                      </div>
                      <div className="md:col-span-1 flex items-end">
                        <button onClick={() => deleteExercise(selectedDayIndex, ex.id)} className="w-full h-16 bg-red-500/10 text-red-500 flex items-center justify-center rounded-2xl hover:bg-red-500 hover:text-white transition-all shadow-lg">
                          <Trash2 size={24} />
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <button onClick={() => addExercise(selectedDayIndex)} className="w-full border-4 border-dashed border-slate-800 p-8 rounded-[2.5rem] text-slate-700 hover:text-white hover:border-slate-500 hover:bg-slate-900/40 transition-all font-black text-xl flex items-center justify-center gap-4">
                <Plus size={28} /> NOVO EXERCÍCIO
              </button>
            </div>

            <button onClick={() => setShowEditWorkoutModal(false)} className="w-full mt-12 bg-lime-400 py-6 rounded-[2rem] font-black text-slate-950 text-2xl shadow-2xl shadow-lime-400/20 active:scale-95 transition-all">
               SALVAR PROGRAMAÇÃO
            </button>
          </div>
        </div>
      )}

      {/* Yoga Prompt Modal */}
      {showYogaPrompt && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6 z-[60]">
          <div className="bg-[#0f172a] rounded-[3rem] p-12 w-full max-w-2xl border border-slate-800 shadow-2xl animate-scale-in">
            <h3 className="text-4xl font-black text-white mb-8 tracking-tighter uppercase italic">Refinar Prática IA</h3>
            <p className="text-slate-500 mb-6 text-lg font-medium">No que deseja focar hoje? Nossos algoritmos ajustarão as posturas e duração.</p>
            <textarea value={yogaInput} onChange={(e) => setYogaInput(e.target.value)} className="w-full bg-slate-900 border-2 border-slate-800 rounded-[2rem] p-10 text-white font-black text-2xl min-h-[250px] outline-none focus:border-purple-500/50 transition-all placeholder:text-slate-800 shadow-inner" placeholder="Ex: Mobilidade quadril, alívio de estresse, equilíbrio..." />
            <div className="flex gap-6 mt-12">
               <button onClick={() => setShowYogaPrompt(false)} className="flex-1 py-6 text-slate-600 font-black text-xl hover:text-white transition-colors">CANCELAR</button>
               <button onClick={handleGenYoga} className="flex-1 bg-purple-600 text-white py-6 rounded-2xl font-black text-2xl shadow-2xl shadow-purple-500/20 active:scale-95 transition-all">GERAR FLUXO</button>
            </div>
          </div>
        </div>
      )}

      {/* Progress Entry Modal - Novo Check-in */}
      {showProgressModal && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl flex items-center justify-center p-6 z-[60]">
          <div className="bg-[#0f172a] rounded-[3rem] p-12 w-full max-w-3xl border border-slate-800 shadow-2xl overflow-y-auto max-h-[90vh] animate-scale-in">
            <div className="flex justify-between items-center mb-12">
              <h3 className="text-4xl font-black text-white flex items-center gap-6 leading-none italic uppercase">
                <Ruler className="text-lime-400" size={48} /> AVALIAÇÃO FÍSICA
              </h3>
              <button onClick={() => setShowProgressModal(false)} className="bg-slate-800 p-3 rounded-2xl text-slate-400 hover:text-white transition-all"><X size={32} /></button>
            </div>

            <div className="space-y-12">
              <div className="bg-slate-900/60 p-12 rounded-[3rem] border border-slate-800 text-center shadow-inner">
                 <label className="text-[10px] font-black text-slate-700 uppercase tracking-[0.3em] mb-4 block">Peso Corporal (kg)</label>
                 <div className="flex items-center justify-center gap-6">
                    <Scale className="text-slate-800" size={56} />
                    <input autoFocus type="number" defaultValue={weightToUse} className="bg-transparent text-white text-8xl font-black outline-none w-56 text-center tabular-nums leading-none" />
                 </div>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 gap-8">
                 {['Peito', 'Cintura', 'Quadril', 'Bíceps D', 'Bíceps E', 'Coxa D', 'Coxa E', 'Panturrilha'].map(item => (
                   <div key={item} className="bg-slate-900/40 p-6 rounded-3xl border border-slate-800 hover:border-lime-400/20 transition-all">
                      <label className="text-[10px] font-black text-slate-700 uppercase mb-3 block tracking-widest leading-none">{item} (cm)</label>
                      <input type="number" className="bg-transparent text-white font-black text-4xl w-full outline-none leading-none tabular-nums" placeholder="0" />
                   </div>
                 ))}
              </div>
            </div>

            <button onClick={() => setShowProgressModal(false)} className="w-full mt-12 bg-lime-400 py-6 rounded-[2rem] font-black text-slate-950 text-2xl shadow-2xl shadow-lime-400/20 active:scale-95 transition-all">
               SALVAR DADOS
            </button>
          </div>
        </div>
      )}

      <style>{`
        .animate-fade-in { animation: fadeIn 0.6s cubic-bezier(0.16, 1, 0.3, 1); }
        .animate-scale-in { animation: scaleIn 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes scaleIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        audio::-webkit-media-controls-panel { background-color: #0f172a; border-radius: 2rem; }
        .custom-audio::-webkit-media-controls-play-button,
        .custom-audio::-webkit-media-controls-mute-button {
          filter: invert(100%) sepia(100%) saturate(10000%) hue-rotate(180deg);
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Student, WeeklyPlan, DayPlan, Exercise, MuscleGroup, ProgressEntry, Measurements, YogaPlan, NutriPlan } from '../types';
import { generateWorkoutPlan, generateYogaPlan, generateProgressInsights, generateMeditationAudio, generateNutriPlan } from '../services/geminiService';
import { 
  ArrowLeft, BrainCircuit, Loader2, Plus, Trash2, Dumbbell, Video, 
  LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X, 
  Apple, Utensils, ShoppingCart, Activity, Clock, Edit2, Info,
  Sparkles, Flower2, Wind, Timer as TimerIcon, Play, Pause, RotateCcw, CheckCircle2, Circle, Volume2, VolumeX, Flame
} from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

const Tooltip: React.FC<{ text: string; children: React.ReactNode }> = ({ text, children }) => (
  <div className="relative group">
    {children}
    <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 bg-slate-950 text-white text-[10px] font-bold rounded-lg opacity-0 group-hover:opacity-100 transition-all pointer-events-none whitespace-nowrap z-[100] border border-slate-800 shadow-2xl">
      {text}
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-950"></div>
    </div>
  </div>
);

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [showEditWorkoutModal, setShowEditWorkoutModal] = useState(false);
  const [showYogaPrompt, setShowYogaPrompt] = useState(false);
  const [yogaInput, setYogaInput] = useState("");

  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [isPlayingIA, setIsPlayingIA] = useState(false);
  const [activeAmbient, setActiveAmbient] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const [timeLeft, setTimeLeft] = useState(900);
  const [timerRunning, setTimerRunning] = useState(false);

  useEffect(() => {
    let interval: number;
    if (timerRunning && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [timerRunning, timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmi = weightToUse && student.height ? (weightToUse / Math.pow(student.height / 100, 2)).toFixed(1) : '0';

  const getBmiStatus = (val: number) => {
    if (val < 18.5) return { label: 'Abaixo do peso', color: 'text-blue-400' };
    if (val < 25) return { label: 'Peso normal', color: 'text-lime-400' };
    if (val < 30) return { label: 'Sobrepeso', color: 'text-yellow-400' };
    return { label: 'Obesidade', color: 'text-red-400' };
  };

  const handleGenWorkout = async () => {
    setIsGenerating(true);
    const plan = await generateWorkoutPlan(student, student.restrictions || "");
    if (plan) onUpdateStudent({ ...student, weeklyPlan: plan });
    setIsGenerating(false);
  };

  const handleGenYoga = async () => {
    setIsGenerating(true);
    const plan = await generateYogaPlan(student, yogaInput);
    if (plan) onUpdateStudent({ ...student, yogaPlan: plan });
    setIsGenerating(false);
    setShowYogaPrompt(false);
  };

  const handleGenNutri = async () => {
    setIsGenerating(true);
    const plan = await generateNutriPlan(student, "");
    if (plan) onUpdateStudent({ ...student, nutriPlan: plan });
    setIsGenerating(false);
  };

  const handleGenInsights = async () => {
    setIsGenerating(true);
    const insights = await generateProgressInsights(student);
    const updatedProgress = [...student.progress];
    if (updatedProgress.length) {
      updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
      onUpdateStudent({ ...student, progress: updatedProgress });
    } else {
      onUpdateStudent({ 
        ...student, 
        progress: [{ 
          id: 'temp-insight', 
          date: new Date().toLocaleDateString(), 
          weight: student.weight, 
          measurements: {}, 
          photos: [], 
          aiInsights: insights 
        }] 
      });
    }
    setIsGenerating(false);
  };

  const playMeditation = async (theme: string) => {
    setIsGenerating(true);
    const data = await generateMeditationAudio(theme);
    if (data) {
      setAudioBase64(data);
      setIsPlayingIA(true);
    }
    setIsGenerating(false);
  };

  const toggleShoppingItem = (itemName: string) => {
    if (!student.nutriPlan) return;
    const updatedList = student.nutriPlan.shoppingList.map(i => 
      i.item === itemName ? { ...i, checked: !i.checked } : i
    );
    onUpdateStudent({
      ...student,
      nutriPlan: { ...student.nutriPlan, shoppingList: updatedList }
    });
  };

  const updateExercise = (dayIdx: number, exId: string, field: keyof Exercise, value: any) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIdx].exercises = updatedWeeklyPlan.days[dayIdx].exercises.map(ex => 
      ex.id === exId ? { ...ex, [field]: value } : ex
    );
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const deleteExercise = (dayIdx: number, exId: string) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIdx].exercises = updatedWeeklyPlan.days[dayIdx].exercises.filter(ex => ex.id !== exId);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const addExercise = (dayIdx: number) => {
    const newEx: Exercise = {
      id: Date.now().toString(),
      name: "Novo Exercício",
      muscleGroup: MuscleGroup.FULL_BODY,
      sets: 3,
      reps: "12",
      notes: ""
    };
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIdx].exercises.push(newEx);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  return (
    <div className="animate-fade-in space-y-8 pb-32">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-[#1e293b] p-6 rounded-3xl border border-slate-800 shadow-xl">
        <div className="flex items-center gap-6">
          <button onClick={onBack} className="p-2 hover:bg-slate-800 rounded-xl transition-all text-slate-400 hover:text-white">
            <ArrowLeft size={24} />
          </button>
          <img src={student.avatarUrl} className="w-16 h-16 rounded-2xl border-2 border-lime-400 object-cover" />
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-2xl font-black text-white">{student.name}</h1>
              <button onClick={() => setShowEditStudentModal(true)} className="text-slate-500 hover:text-white"><Edit2 size={16} /></button>
            </div>
            <div className="flex gap-2 mt-1">
              <span className="text-[10px] font-black uppercase tracking-widest text-lime-400">{student.goal}</span>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">•</span>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{student.level}</span>
            </div>
          </div>
        </div>

        <nav className="flex bg-slate-900/50 p-1 rounded-2xl border border-slate-800">
          {[
