              <div className="space-y-4">
                {student.weeklyPlan.days[selectedDayIndex].exercises.map((ex) => (
                  <div key={ex.id} className="bg-slate-900/60 p-6 rounded-2xl border border-slate-800 grid grid-cols-1 md:grid-cols-12 gap-4">
                      <div className="md:col-span-4">
                        <label className="text-[8px] font-black text-slate-700 uppercase mb-1 block">Exercício</label>
                        <input type="text" value={ex.name} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'name', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-white font-bold" />
                      </div>
                      <div className="md:col-span-3">
                        <label className="text-[8px] font-black text-slate-700 uppercase mb-1 block">Grupo</label>
                        <select value={ex.muscleGroup} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'muscleGroup', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-white font-bold">
                          {Object.values(MuscleGroup).map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                      </div>
                      <div className="md:col-span-2">
                        <label className="text-[8px] font-black text-slate-700 uppercase mb-1 block">Sets</label>
                        <input type="number" value={ex.sets} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'sets', parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-white font-bold text-center" />
                      </div>
                      <div className="md:col-span-2">
                        <label className="text-[8px] font-black text-slate-700 uppercase mb-1 block">Reps</label>
                        <input type="text" value={ex.reps} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'reps', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-lg p-2 text-white font-bold text-center" />
                      </div>
                      <div className="md:col-span-1 flex items-end">
                        <button onClick={() => deleteExercise(selectedDayIndex, ex.id)} className="w-full bg-red-500/10 text-red-500 flex items-center justify-center rounded-lg p-2 hover:bg-red-500 hover:text-white transition-all">
                          <Trash2 size={18} />
                        </button>
                      </div>
                  </div>
                ))}
                <button onClick={() => addExercise(selectedDayIndex)} className="w-full border-2 border-dashed border-slate-800 p-4 rounded-2xl text-slate-600 hover:text-white font-bold text-xs flex items-center justify-center gap-2">
                  <Plus size={16} /> NOVO EXERCÍCIO
                </button>
              </div>
            </div>

            <button onClick={() => setShowEditWorkoutModal(false)} className="w-full mt-8 bg-lime-400 py-4 rounded-xl font-black text-slate-950 shadow-xl shadow-lime-400/10">
               SALVAR
            </button>
          </div>
        </div>
      )}

      {/* Yoga Prompt Modal */}
      {showYogaPrompt && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-xl flex items-center justify-center p-4 z-[60]">
          <div className="bg-[#0f172a] rounded-[2.5rem] p-8 w-full max-w-lg border border-slate-800 shadow-2xl">
            <h3 className="text-xl font-black text-white mb-4">Prática Personalizada</h3>
            <textarea value={yogaInput} onChange={(e) => setYogaInput(e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-xl p-6 text-white text-sm min-h-[150px] outline-none" placeholder="Ex: Mobilidade quadril, relaxamento, força no core..." />
            <div className="flex gap-4 mt-8">
               <button onClick={() => setShowYogaPrompt(false)} className="flex-1 py-4 text-slate-600 font-bold">CANCELAR</button>
               <button onClick={handleGenYoga} className="flex-1 bg-purple-600 text-white py-4 rounded-xl font-black shadow-lg">GERAR</button>
            </div>
          </div>
        </div>
      )}

      {/* Progress Entry Modal - Novo Check-in */}
      {showProgressModal && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-xl flex items-center justify-center p-4 z-[60]">
          <div className="bg-[#0f172a] rounded-[2rem] p-10 w-full max-w-2xl border border-slate-800 shadow-2xl">
            <h3 className="text-2xl font-black text-white flex items-center gap-4 mb-8">
              <Ruler className="text-lime-400" /> AVALIAÇÃO
            </h3>
            <div className="space-y-8">
              <div className="bg-slate-900/60 p-8 rounded-2xl border border-slate-800 text-center">
                 <label className="text-[10px] font-black text-slate-700 uppercase mb-2 block">Peso Corporaç (kg)</label>
                 <input autoFocus type="number" defaultValue={weightToUse} className="bg-transparent text-white text-6xl font-black outline-none w-full text-center tabular-nums" />
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                 {['Peito', 'Cintura', 'Quadril', 'Bíceps', 'Coxa', 'Panturrilha'].map(item => (
                   <div key={item} className="bg-slate-900/40 p-4 rounded-xl border border-slate-800">
                      <label className="text-[8px] font-black text-slate-700 uppercase mb-1 block">{item} (cm)</label>
                      <input type="number" className="bg-transparent text-white font-black text-lg w-full outline-none" placeholder="0" />
                   </div>
                 ))}
              </div>
            </div>
            <button onClick={() => setShowProgressModal(false)} className="w-full mt-10 bg-lime-400 py-4 rounded-xl font-black text-slate-950 shadow-xl shadow-lime-400/10">
               SALVAR
            </button>
          </div>
        </div>
      )}

      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s ease-out; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        audio::-webkit-media-controls-panel { background-color: #0f172a; border-radius: 1rem; }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Student, WeeklyPlan, DayPlan, Exercise, MuscleGroup, ProgressEntry, Measurements, YogaPlan, NutriPlan } from '../types';
import { generateWorkoutPlan, generateYogaPlan, generateProgressInsights, generateMeditationAudio, generateNutriPlan } from '../services/geminiService';
import { 
  ArrowLeft, BrainCircuit, Loader2, Plus, Trash2, Dumbbell, Video, 
  LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X, 
  Apple, Utensils, ShoppingCart, Activity, Clock, Edit2, Info,
  Sparkles, Flower2, Wind, Timer as TimerIcon, Play, Pause, RotateCcw, CheckCircle2, Circle, Volume2, VolumeX, Flame
} from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

const Tooltip: React.FC<{ text: string; children: React.ReactNode }> = ({ text, children }) => (
  <div className="relative group">
    {children}
    <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 bg-slate-950 text-white text-[10px] font-bold rounded-lg opacity-0 group-hover:opacity-100 transition-all pointer-events-none whitespace-nowrap z-[100] border border-slate-800 shadow-2xl">
      {text}
      <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-950"></div>
    </div>
  </div>
);

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [showEditWorkoutModal, setShowEditWorkoutModal] = useState(false);
  const [showYogaPrompt, setShowYogaPrompt] = useState(false);
  const [yogaInput, setYogaInput] = useState("");

  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [isPlayingIA, setIsPlayingIA] = useState(false);
  const [activeAmbient, setActiveAmbient] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const [timeLeft, setTimeLeft] = useState(900);
  const [timerRunning, setTimerRunning] = useState(false);

  useEffect(() => {
    let interval: number;
    if (timerRunning && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [timerRunning, timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmi = weightToUse && student.height ? (weightToUse / Math.pow(student.height / 100, 2)).toFixed(1) : '0';

  const getBmiStatus = (val: number) => {
    if (val < 18.5) return { label: 'Abaixo do peso', color: 'text-blue-400' };
    if (val < 25) return { label: 'Peso normal', color: 'text-lime-400' };
    if (val < 30) return { label: 'Sobrepeso', color: 'text-yellow-400' };
    return { label: 'Obesidade', color: 'text-red-400' };
  };

  const handleGenWorkout = async () => {
    setIsGenerating(true);
    const plan = await generateWorkoutPlan(student, student.restrictions || "");
    if (plan) onUpdateStudent({ ...student, weeklyPlan: plan });
    setIsGenerating(false);
  };

  const handleGenYoga = async () => {
    setIsGenerating(true);
    const plan = await generateYogaPlan(student, yogaInput);
    if (plan) onUpdateStudent({ ...student, yogaPlan: plan });
    setIsGenerating(false);
    setShowYogaPrompt(false);
  };

  const handleGenNutri = async () => {
    setIsGenerating(true);
    const plan = await generateNutriPlan(student, "");
    if (plan) onUpdateStudent({ ...student, nutriPlan: plan });
    setIsGenerating(false);
  };

  const handleGenInsights = async () => {
    setIsGenerating(true);
    const insights = await generateProgressInsights(student);
    const updatedProgress = [...student.progress];
    if (updatedProgress.length) {
      updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
      onUpdateStudent({ ...student, progress: updatedProgress });
    } else {
      onUpdateStudent({ 
        ...student, 
        progress: [{ 
          id: 'temp-insight', 
          date: new Date().toLocaleDateString(), 
          weight: student.weight, 
          measurements: {}, 
          photos: [], 
          aiInsights: insights 
        }] 
      });
    }
    setIsGenerating(false);
  };

  const playMeditation = async (theme: string) => {
    setIsGenerating(true);
    const data = await generateMeditationAudio(theme);
    if (data) {
      setAudioBase64(data);
      setIsPlayingIA(true);
    }
    setIsGenerating(false);
  };

  const toggleShoppingItem = (itemName: string) => {
    if (!student.nutriPlan) return;
    const updatedList = student.nutriPlan.shoppingList.map(i => 
      i.item === itemName ? { ...i, checked: !i.checked } : i
    );
    onUpdateStudent({
      ...student,
      nutriPlan: { ...student.nutriPlan, shoppingList: updatedList }
    });
  };

  const updateExercise = (dayIdx: number, exId: string, field: keyof Exercise, value: any) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIdx].exercises = updatedWeeklyPlan.days[dayIdx].exercises.map(ex => 
      ex.id === exId ? { ...ex, [field]: value } : ex
    );
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const deleteExercise = (dayIdx: number, exId: string) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIdx].exercises = updatedWeeklyPlan.days[dayIdx].exercises.filter(ex => ex.id !== exId);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const addExercise = (dayIdx: number) => {
    const newEx: Exercise = {
      id: Date.now().toString(),
      name: "Novo Exercício",
      muscleGroup: MuscleGroup.FULL_BODY,
      sets: 3,
      reps: "12",
      notes: ""
    };
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIdx].exercises.push(newEx);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  return (
    <div className="animate-fade-in space-y-8 pb-32">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-[#1e293b] p-6 rounded-3xl border border-slate-800 shadow-xl">
        <div className="flex items-center gap-6">
          <button onClick={onBack} className="p-2 hover:bg-slate-800 rounded-xl transition-all text-slate-400 hover:text-white">
            <ArrowLeft size={24} />
          </button>
          <img src={student.avatarUrl} className="w-16 h-16 rounded-2xl border-2 border-lime-400 object-cover" />
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-2xl font-black text-white">{student.name}</h1>
              <button onClick={() => setShowEditStudentModal(true)} className="text-slate-500 hover:text-white"><Edit2 size={16} /></button>
            </div>
            <div className="flex gap-2 mt-1">
              <span className="text-[10px] font-black uppercase tracking-widest text-lime-400">{student.goal}</span>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">•</span>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{student.level}</span>
            </div>
          </div>
        </div>

        <nav className="flex bg-slate-900/50 p-1 rounded-2xl border border-slate-800">
          {[
            { id: 'WORKOUT', icon: Dumbbell, label: 'Treino', color: 'lime-400' },
            { id: 'PROGRESS', icon: LineChart, label: 'Evolução', color: 'indigo-400' },
            { id: 'NUTRI', icon: Apple, label: 'Nutri', color: 'emerald-400' },
            { id: 'YOGA', icon: Flower2, label: 'Yoga', color: 'purple-400' },
            { id: 'MEDITATION', icon: Wind, label: 'Mente', color: 'sky-400' },
          ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-xs transition-all ${
                activeTab === tab.id ? `bg-slate-800 text-${tab.color}` : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              <tab.icon size={16} />
              <span className="hidden sm:inline uppercase tracking-widest">{tab.label}</span>
            </button>
          ))}
        </nav>
      </div>

      {activeTab === 'WORKOUT' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-3 space-y-3">
             {student.weeklyPlan.days.map((day, idx) => (
                <button key={idx} onClick={() => setSelectedDayIndex(idx)} className={`w-full p-5 rounded-2xl border transition-all text-left group ${selectedDayIndex === idx ? 'bg-lime-400 border-lime-400 text-slate-900 shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-800/60'}`}>
                  <p className="text-[10px] font-black uppercase mb-1 opacity-60">{day.dayOfWeek}</p>
                  <p className="font-bold text-base leading-tight">{day.focus || 'Descanso'}</p>
                </button>
             ))}
             <button onClick={handleGenWorkout} disabled={isGenerating} className="w-full mt-6 bg-slate-900 border border-slate-800 p-5 rounded-2xl text-lime-400 font-black flex items-center justify-between hover:bg-slate-800 transition-all">
                <span className="text-xs uppercase tracking-widest">{isGenerating ? 'GERANDO...' : 'INTELIGÊNCIA IA'}</span>
                {isGenerating ? <Loader2 className="animate-spin" size={18} /> : <BrainCircuit size={18} />}
             </button>

             {/* New Button: Editar Treino IA */}
             <button onClick={() => setShowEditWorkoutModal(true)} className="w-full mt-2 bg-slate-800/50 border border-slate-700 p-4 rounded-2xl text-white font-black flex items-center justify-between hover:bg-slate-700 transition-all">
                <span className="text-[10px] uppercase tracking-widest">Editar Treino IA</span>
                <Edit2 size={16} className="text-slate-400" />
             </button>
          </div>
          <div className="lg:col-span-9 bg-slate-900/40 rounded-3xl p-8 border border-slate-800">
             <div className="flex justify-between items-center mb-8">
                <h2 className="text-xl font-black text-white uppercase tracking-tighter">
                  {student.weeklyPlan.days[selectedDayIndex].dayOfWeek} - {student.weeklyPlan.days[selectedDayIndex].focus}
                </h2>
                <div className="flex gap-2">
                    <button onClick={() => setShowEditWorkoutModal(true)} className="flex items-center gap-2 bg-slate-800 px-4 py-2 rounded-xl text-white hover:bg-slate-700 border border-slate-700 font-bold text-xs">
                      <Edit2 size={14} /> Editar
                    </button>
                    <button onClick={() => addExercise(selectedDayIndex)} className="bg-lime-400 p-2 rounded-xl text-slate-900 hover:bg-lime-500 transition-all shadow-lg"><Plus size={18} /></button>
                </div>
             </div>
             <div className="space-y-4">
               {student.weeklyPlan.days[selectedDayIndex].exercises.length === 0 ? (
                 <div className="text-center py-16 text-slate-700 italic border border-dashed border-slate-800 rounded-2xl">
                   Nenhum exercício para hoje.
                 </div>
               ) : (
                 student.weeklyPlan.days[selectedDayIndex].exercises.map(ex => (
                    <div key={ex.id} className="bg-slate-800/40 border border-slate-800 p-6 rounded-2xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4 hover:border-lime-400/20 transition-all">
                       <div>
                          <span className="text-[10px] font-black text-lime-400 uppercase tracking-widest">{ex.muscleGroup}</span>
                          <h3 className="text-lg font-bold text-white mt-1">{ex.name}</h3>
                          {ex.notes && <p className="text-slate-500 text-xs mt-1">{ex.notes}</p>}
                       </div>
                       <div className="flex items-center gap-6">
                          <div className="text-center">
                             <p className="text-slate-500 text-[10px] font-black uppercase">Séries</p>
                             <p className="text-xl font-black text-white">{ex.sets}</p>
                          </div>
                          <div className="text-center">
                             <p className="text-slate-500 text-[10px] font-black uppercase">Reps</p>
                             <p className="text-xl font-black text-white">{ex.reps}</p>
                          </div>
                          <a href={ex.videoUrl} target="_blank" rel="noreferrer" className="p-3 bg-slate-900 rounded-xl text-slate-400 hover:text-lime-400 transition-all"><Video size={18} /></a>
                       </div>
                    </div>
                 ))
               )}
             </div>
          </div>
        </div>
      )}

      {activeTab === 'PROGRESS' && (
        <div className="space-y-6">
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800 shadow-lg">
                 <h4 className="text-slate-500 font-black uppercase text-[10px] mb-2 tracking-widest">Peso Atual</h4>
                 <div className="flex items-baseline gap-1">
                    <span className="text-4xl font-black text-white">{weightToUse}</span>
                    <span className="text-sm font-bold text-slate-500 uppercase">KG</span>
                 </div>
              </div>
              <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800 shadow-lg">
                 <h4 className="text-slate-500 font-black uppercase text-[10px] mb-2 tracking-widest">Índice IMC</h4>
                 <div className="flex items-baseline gap-3">
                    <span className="text-4xl font-black text-white">{bmi}</span>
                    <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded ${getBmiStatus(parseFloat(bmi)).color} bg-slate-900/50`}>{getBmiStatus(parseFloat(bmi)).label}</span>
                 </div>
              </div>
              <div className="bg-gradient-to-br from-indigo-900/40 to-slate-900/40 p-6 rounded-2xl border border-indigo-500/20 shadow-lg relative group">
                 <h4 className="text-indigo-400 font-black uppercase text-[10px] mb-2 tracking-widest flex items-center gap-2">IA Coach <Sparkles size={12} /></h4>
                 <p className="text-slate-300 text-xs italic leading-relaxed line-clamp-3">{student.progress[0]?.aiInsights || "Sem insights."}</p>
                 <button onClick={handleGenInsights} disabled={isGenerating} className="mt-3 w-full bg-slate-800/50 hover:bg-slate-800 text-white p-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all">
                    {isGenerating ? <Loader2 className="animate-spin inline" size={12} /> : 'Atualizar Diagnóstico'}
                 </button>
              </div>
           </div>

           <div className="bg-slate-900/40 rounded-3xl p-8 border border-slate-800">
              <div className="flex justify-between items-center mb-6">
                 <h3 className="text-lg font-black text-white uppercase tracking-tighter">Histórico de Medidas</h3>
                 <button onClick={() => setShowProgressModal(true)} className="bg-lime-400 text-slate-900 px-4 py-2 rounded-xl font-black text-xs hover:bg-lime-500 transition-all">
                    Novo Check-in
                 </button>
              </div>
              <div className="space-y-4">
                {student.progress.length === 0 ? (
                  <div className="text-center py-10 text-slate-700 italic border border-dashed border-slate-800 rounded-2xl">Aguardando check-in.</div>
                ) : (
                  student.progress.map(entry => (
                     <div key={entry.id} className="bg-slate-800/40 p-6 rounded-2xl border border-slate-800">
                        <div className="flex justify-between items-center mb-4 pb-2 border-b border-slate-700/50">
                           <p className="text-white font-bold text-sm">{entry.date}</p>
                           <p className="text-lime-400 font-black">{entry.weight} kg</p>
                        </div>
                        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-8 gap-3">
                           {Object.entries(entry.measurements).map(([key, val]) => (
                              <div key={key} className="bg-slate-900/50 p-2 rounded-lg text-center">
                                 <p className="text-slate-500 text-[8px] font-black uppercase">{key}</p>
                                 <p className="text-white font-bold text-xs">{val}cm</p>
                              </div>
                           ))}
                        </div>
                     </div>
                  ))
                )}
              </div>
           </div>
        </div>
      )}

      {activeTab === 'NUTRI' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
           <div className="lg:col-span-3 space-y-4">
              <div className="bg-slate-900/40 p-6 rounded-2xl border border-slate-800 shadow-lg">
                <h4 className="text-slate-500 font-black uppercase text-[10px] mb-4 tracking-widest">Macros do Plano</h4>
                {student.nutriPlan ? (
                  <div className="space-y-2 text-xs">
