export const generateNutriPlan = async (student: Student, notes: string): Promise<NutriPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const weightToUse = student.progress[0]?.weight || student.weight;
  const prompt = `Atue como um Nutricionista Esportivo de elite. Crie um plano alimentar semanal para:
    Nome: ${student.name}, Idade: ${student.age}, Peso: ${weightToUse}kg, Altura: ${student.height}cm.
    Objetivo: ${student.goal}, Sedentarismo: ${student.sedentaryLevel}.
    Notas adicionais do professor: ${notes}.
    Retorne JSON com: weeklyMeals (7 dias, 5-6 refeições/dia), recipes (3 receitas), shoppingList (organizada por categoria), dailyMacrosTarget.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weeklyMeals: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  meals: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        time: { type: Type.STRING },
                        label: { type: Type.STRING },
                        description: { type: Type.STRING }
                      }
                    }
                  }
                }
              }
            },
            recipes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                  instructions: { type: Type.STRING },
                  macros: {
                    type: Type.OBJECT,
                    properties: {
                      protein: { type: Type.NUMBER },
                      carbs: { type: Type.NUMBER },
                      fats: { type: Type.NUMBER },
                      calories: { type: Type.NUMBER }
                    }
                  }
                }
              }
            },
            shoppingList: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  category: { type: Type.STRING }
                }
              }
            },
            dailyMacrosTarget: {
              type: Type.OBJECT,
              properties: {
                protein: { type: Type.NUMBER },
                carbs: { type: Type.NUMBER },
                fats: { type: Type.NUMBER },
                calories: { type: Type.NUMBER }
              }
            }
          }
        }
      }
    });

    const data = JSON.parse(response.text);
    return {
      ...data,
      recipes: data.recipes.map((r: any, i: number) => ({ ...r, id: `rec-${i}` })),
      shoppingList: data.shoppingList.map((s: any) => ({ ...s, checked: false }))
    };
  } catch (e) {
    console.error("Erro ao gerar dieta:", e);
    return null;
  }
};

