    let interval: number;
    if (timerRunning && timeLeft > 0) {
      interval = window.setInterval(() => setTimeLeft((prev) => prev - 1), 1000);
    } else if (timeLeft === 0) {
      setTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [timerRunning, timeLeft]);

  useEffect(() => {
    let interval: number;
    if (poseTimerRunning && poseTimerSeconds > 0) {
      interval = window.setInterval(() => setPoseTimerSeconds((prev) => prev - 1), 1000);
    } else if (poseTimerSeconds === 0) {
      setPoseTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [poseTimerRunning, poseTimerSeconds]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleGenWorkout = async () => {
    setIsGenerating(true);
    const plan = await generateWorkoutPlan(student, workoutPromptInput);
    if (plan) onUpdateStudent({ ...student, weeklyPlan: plan });
    setIsGenerating(false);
    setShowWorkoutPromptModal(false);
  };

  const handleGenYoga = async () => {
    setIsGenerating(true);
    const plan = await generateYogaPlan(student, yogaInput);
    if (plan) onUpdateStudent({ ...student, yogaPlan: plan });
    setIsGenerating(false);
    setShowYogaPrompt(false);
  };

  const handleGenNutri = async () => {
    setIsGenerating(true);
    const plan = await generateNutriPlan(student, nutriPromptInput);
    if (plan) onUpdateStudent({ ...student, nutriPlan: plan });
    setIsGenerating(false);
    setShowNutriPromptModal(false);
  };

  const handleGenMeditationTips = async () => {
    setIsGeneratingTips(true);
    const tips = await generateMeditationTips(student);
    setMeditationTips(tips);
    setIsGeneratingTips(false);
  };

  const startPoseTimer = (poseName: string, durationStr: string) => {
    // Parse duration like "45s" or "1 min"
    let seconds = 30; // default
    if (durationStr.includes('s')) {
      seconds = parseInt(durationStr.replace('s', '')) || 30;
    } else if (durationStr.includes('min')) {
      seconds = (parseInt(durationStr.replace('min', '')) || 1) * 60;
    }
    setActivePoseTimer(poseName);
    setPoseTimerSeconds(seconds);
    setPoseTimerRunning(true);
  };

  const handleRecipeClick = (recipeName: string) => {
    window.open(`https://www.google.com/search?q=receita+de+${encodeURIComponent(recipeName)}`, '_blank');
  };

  const handleGenInsights = async () => {
    setIsGenerating(true);
    const insights = await generateProgressInsights(student);
    const updatedProgress = [...student.progress];
    if (updatedProgress.length) {
      updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
      onUpdateStudent({ ...student, progress: updatedProgress });
    } else {
      onUpdateStudent({ 
        ...student, 
        progress: [{ 
          id: 'temp-insight', 
          date: new Date().toLocaleDateString(), 
          weight: student.weight, 
          measurements: {}, 
          photos: [], 
          aiInsights: insights 
        }] 
      });
