  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmi = weightToUse && student.height ? (weightToUse / Math.pow(student.height / 100, 2)).toFixed(1) : '0';

  const getBmiStatus = (val: number) => {
