                        <button onClick={() => deleteExercise(selectedDayIndex, ex.id)} className="w-full bg-red-500/10 text-red-500 flex items-center justify-center rounded-lg p-2 hover:bg-red-500 hover:text-white transition-all">
                          <Trash2 size={18} />
                        </button>
                      </div>
