      {/* Progress Entry Modal - Novo Check-in */}
      {showProgressModal && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-xl flex items-center justify-center p-4 z-[60]">
          <div className="bg-[#0f172a] rounded-[2rem] p-10 w-full max-w-2xl border border-slate-800 shadow-2xl">
            <h3 className="text-2xl font-black text-white flex items-center gap-4 mb-8">
              <Ruler className="text-lime-400" /> AVALIAÇÃO
            </h3>
            <div className="space-y-8">
              <div className="bg-slate-900/60 p-8 rounded-2xl border border-slate-800 text-center">
                 <label className="text-[10px] font-black text-slate-700 uppercase mb-2 block">Peso Corporal (kg)</label>
                 <input autoFocus type="number" defaultValue={weightToUse} className="bg-transparent text-white text-6xl font-black outline-none w-full text-center tabular-nums" />
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                 {['Peito', 'Cintura', 'Quadril', 'Bíceps', 'Coxa', 'Panturrilha'].map(item => (
                   <div key={item} className="bg-slate-900/40 p-4 rounded-xl border border-slate-800">
                      <label className="text-[8px] font-black text-slate-700 uppercase mb-1 block">{item} (cm)</label>
