  weeklyPlan: WeeklyPlan;
  nutriPlan?: NutriPlan;
  yogaPlan?: YogaPlan;
  meditationChallenges: MeditationChallenge[];
  progress: ProgressEntry[];
  avatarUrl: string;
  restrictions?: string;
  whatsapp?: string;
  instagram?: string;
  email?: string;
}

