  LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X, 
  Apple, Utensils, ShoppingCart, Activity, Clock, Edit2, Info,
  Sparkles, Flower2, Wind, Timer as TimerIcon, Play, Pause, RotateCcw, CheckCircle2, Circle, Volume2, VolumeX, Flame, Search, User, MessageCircle, Instagram, Mail, Brain
} from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

const GOAL_OPTIONS = [
  'Hipertrofia',
  'Emagrecimento',
  'Condicionamento Físico',
  'Flexibilidade',
  'Saúde/Bem-estar',
  'Performance Atleta',
