export const generateNutriPlan = async (student: Student, notes: string): Promise<NutriPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const weightToUse = student.progress[0]?.weight || student.weight;
  const prompt = `Nutricionista Esportivo: Plano para ${student.name}, ${weightToUse}kg, ${student.height}cm.
    Objetivo: ${student.goal}, Atividade: ${student.sedentaryLevel}.
    Notas: ${notes}.
    JSON: weeklyMeals (7 dias), recipes (3 principais), shoppingList (por categoria), dailyMacrosTarget.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weeklyMeals: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  meals: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        time: { type: Type.STRING },
                        label: { type: Type.STRING },
                        description: { type: Type.STRING }
                      }
                    }
                  }
                }
              }
            },
            recipes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
                  instructions: { type: Type.STRING },
                  macros: {
                    type: Type.OBJECT,
                    properties: {
                      protein: { type: Type.NUMBER },
                      carbs: { type: Type.NUMBER },
                      fats: { type: Type.NUMBER },
                      calories: { type: Type.NUMBER }
                    }
                  }
                }
              }
            },
            shoppingList: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  item: { type: Type.STRING },
                  category: { type: Type.STRING }
                }
              }
            },
            dailyMacrosTarget: {
              type: Type.OBJECT,
              properties: {
                protein: { type: Type.NUMBER },
                carbs: { type: Type.NUMBER },
                fats: { type: Type.NUMBER },
                calories: { type: Type.NUMBER }
              }
            }
          }
        }
      }
    });

    const data = JSON.parse(cleanJSON(response.text));
    return {
      ...data,
      recipes: (data.recipes || []).map((r: any, i: number) => ({ ...r, id: `rec-${i}` })),
      shoppingList: (data.shoppingList || []).map((s: any) => ({ ...s, checked: false }))
    };
  } catch (e) {
    console.error("Erro ao gerar dieta:", e);
    return null;
  }
};

