                   <h3 className="text-white font-black text-sm uppercase tracking-widest mb-8 flex items-center gap-3"><Info size={20} className="text-lime-400" /> Dados Sociais</h3>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="relative">
                        <MessageCircle size={20} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-500" />
                        <input type="text" placeholder="WhatsApp" value={editStudentForm.whatsapp} onChange={e => setEditStudentForm({...editStudentForm, whatsapp: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl pl-14 pr-5 py-5 text-white font-bold outline-none" />
                      </div>
                      <div className="relative">
                        <Instagram size={20} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-500" />
                        <input type="text" placeholder="Instagram" value={editStudentForm.instagram} onChange={e => setEditStudentForm({...editStudentForm, instagram: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl pl-14 pr-5 py-5 text-white font-bold outline-none" />
                      </div>
                   </div>
                </div>
              </div>
              <button type="submit" className="w-full bg-lime-400 py-6 rounded-2xl font-black text-slate-900 text-xl shadow-2xl shadow-lime-400/30 active:scale-95 transition-all uppercase tracking-widest">Salvar Perfil</button>
            </form>
          </div>
        </div>
      )}

      {/* Manual Workout Editor Modal */}
      {showEditWorkoutModal && (
        <div className="fixed inset-0 bg-black/98 backdrop-blur-2xl flex items-center justify-center p-4 z-[100] animate-fade-in">
          <div className="bg-[#0f172a] rounded-[3rem] p-12 w-full max-w-5xl border border-slate-800 shadow-2xl overflow-y-auto max-h-[90vh] no-scrollbar">
            <div className="flex justify-between items-center mb-10">
              <h2 className="text-3xl font-black text-white tracking-tighter">Editor Manual de Treino</h2>
              <button onClick={() => setShowEditWorkoutModal(false)} className="text-slate-500 hover:text-white transition-colors"><X size={32} /></button>
