                <input type="text" value={student.weeklyPlan.days[selectedDayIndex].focus} onChange={(e) => {
                     const updatedWeeklyPlan = { ...student.weeklyPlan };
                     updatedWeeklyPlan.days[selectedDayIndex].focus = e.target.value;
                     onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
                   }} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 text-white font-black text-2xl outline-none focus:ring-2 focus:ring-lime-400/50" />
              </div>

              <div className="space-y-4">
                {student.weeklyPlan.days[selectedDayIndex].exercises.map((ex) => (
                  <div key={ex.id} className="bg-slate-900/40 p-8 rounded-[2rem] border border-slate-800 flex flex-col gap-6 group">
                      <div className="grid grid-cols-1 md:grid-cols-12 gap-6 items-end">
                        <div className="md:col-span-5">
                          <label className="text-[10px] font-black text-slate-700 uppercase mb-3 block">Nome</label>
                          <input type="text" value={ex.name} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'name', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-xl p-4 text-white font-bold focus:ring-2 focus:ring-lime-400/50 outline-none" />
                        </div>
                        <div className="md:col-span-3">
                          <label className="text-[10px] font-black text-slate-700 uppercase mb-3 block">Grupo</label>
                          <select value={ex.muscleGroup} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'muscleGroup', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-xl p-4 text-white font-bold appearance-none outline-none">
                            {Object.values(MuscleGroup).map(g => <option key={g} value={g}>{g}</option>)}
                          </select>
                        </div>
                        <div className="md:col-span-2">
                          <label className="text-[10px] font-black text-slate-700 uppercase mb-3 block text-center">Séries</label>
                          <input type="number" value={ex.sets} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'sets', parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-800 rounded-xl p-4 text-white font-bold text-center outline-none" />
                        </div>
                        <div className="md:col-span-1">
                          <label className="text-[10px] font-black text-slate-700 uppercase mb-3 block text-center">Reps</label>
                          <input type="text" value={ex.reps} onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'reps', e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-xl p-4 text-white font-bold text-center outline-none" />
                        </div>
                        <div className="md:col-span-1">
                          <button onClick={() => deleteExercise(selectedDayIndex, ex.id)} className="w-full h-[58px] bg-red-500/10 text-red-500 flex items-center justify-center rounded-xl hover:bg-red-500 hover:text-white transition-all shadow-inner">
                            <Trash2 size={24} />
                          </button>
                        </div>
                      </div>

                      {/* Notas de Exercício */}
                      <div>
                        <label className="text-[10px] font-black text-slate-700 uppercase mb-3 block">Notas / Observações específicas</label>
                        <textarea 
                          value={ex.notes || ''} 
                          onChange={(e) => updateExercise(selectedDayIndex, ex.id, 'notes', e.target.value)} 
                          className="w-full bg-slate-900/50 border border-slate-800 rounded-xl p-4 text-slate-300 text-sm font-medium outline-none focus:ring-2 focus:ring-lime-400/50 min-h-[80px]" 
                          placeholder="Ex: Descanso de 60s entre séries, cadência 2:2, focar na contração máxima..." 
                        />
                      </div>
                  </div>
                ))}
                <button onClick={() => addExercise(selectedDayIndex)} className="w-full border-2 border-dashed border-slate-800 p-8 rounded-[2rem] text-slate-600 hover:text-lime-400 hover:border-lime-400 transition-all font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-4 active:scale-[0.99]">
                  <Plus size={24} /> Adicionar Exercício
                </button>
              </div>
            </div>

            <button onClick={() => setShowEditWorkoutModal(false)} className="w-full mt-12 bg-lime-400 py-6 rounded-2xl font-black text-slate-950 shadow-2xl shadow-lime-400/30 active:scale-95 transition-all uppercase tracking-widest">
               Concluir Edição Manual
            </button>
          </div>
        </div>
      )}

      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s ease-out; }
        .animate-scale-in { animation: scaleIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1); }
        .animate-bounce-gentle { animation: bounceGentle 3s infinite ease-in-out; }
        .animate-pulse-scale { animation: pulseScale 1.5s infinite ease-in-out; }
        .animate-spin-slow { animation: spinSlow 6s infinite linear; }

        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes scaleIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        @keyframes bounceGentle { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-15px); } }
        @keyframes pulseScale { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.1); } }
        @keyframes spinSlow { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

        .drop-shadow-glow { filter: drop-shadow(0 0 10px rgba(163,230,53,0.3)); }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .shadow-text { text-shadow: 0 0 30px rgba(56,189,248,0.3); }

        /* Estilo para input range */
        input[type=range] {
          -webkit-appearance: none;
          background: transparent;
        }
        input[type=range]:focus {
          outline: none;
        }
        input[type=range]::-webkit-slider-runnable-track {
          width: 100%;
          height: 4px;
          cursor: pointer;
          background: #1e293b;
          border-radius: 2px;
        }
        input[type=range]::-webkit-slider-thumb {
          height: 16px;
          width: 16px;
          border-radius: 8px;
          background: currentColor;
          cursor: pointer;
          -webkit-appearance: none;
          margin-top: -6px;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Student, WeeklyPlan, DayPlan, Exercise, MuscleGroup, ProgressEntry, Measurements, YogaPlan, NutriPlan, YogaPose } from '../types';
import { generateWorkoutPlan, generateYogaPlan, generateProgressInsights, generateMeditationAudio, generateNutriPlan, generateMeditationTips } from '../services/geminiService';
import { 
  ArrowLeft, BrainCircuit, Loader2, Plus, Trash2, Dumbbell, Video, 
  LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X, 
  Apple, Utensils, ShoppingCart, Activity, Clock, Edit2, Info,
  Sparkles, Flower2, Wind, Timer as TimerIcon, Play, Pause, RotateCcw, CheckCircle2, Circle, Volume2, VolumeX, Flame, Search, User, MessageCircle, Instagram, Mail, Brain, RefreshCw, Wand2, Download
} from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

const GOAL_OPTIONS = [
  'Hipertrofia',
  'Emagrecimento',
  'Condicionamento Físico',
  'Flexibilidade',
  'Saúde/Bem-estar',
  'Performance Atleta',
  'Reabilitação',
  'Ganho de Força'
];

const AMBIENT_SOUNDS = [
  { id: 'chuva', name: 'Chuva Tropical', url: 'https://actions.google.com/sounds/v1/weather/rain_heavy_loud.ogg' },
  { id: 'floresta', name: 'Floresta Zen', url: 'https://actions.google.com/sounds/v1/ambient/morning_birds.ogg' },
  { id: 'ondas', name: 'Ondas do Mar', url: 'https://actions.google.com/sounds/v1/water/waves_crashing_on_shore.ogg' },
  { id: 'alfa', name: 'Ondas Alfa', url: 'https://actions.google.com/sounds/v1/science_fiction/low_frequency_hum.ogg' },
];

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);

  // Modals visibility
  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [showEditWorkoutModal, setShowEditWorkoutModal] = useState(false);
  const [showYogaPrompt, setShowYogaPrompt] = useState(false);
  const [showWorkoutPromptModal, setShowWorkoutPromptModal] = useState(false);
  const [showNutriPromptModal, setShowNutriPromptModal] = useState(false);

  // Prompt Inputs
  const [workoutPromptInput, setWorkoutPromptInput] = useState("");
  const [nutriPromptInput, setNutriPromptInput] = useState("");
  const [yogaInput, setYogaInput] = useState("");

  // Edit Student Form State
  const [editStudentForm, setEditStudentForm] = useState({
    name: student.name,
    age: student.age,
    height: student.height,
    weight: student.weight,
    goal: student.goal,
    level: student.level,
    avatarUrl: student.avatarUrl,
    restrictions: student.restrictions || '',
    whatsapp: student.whatsapp || '',
    instagram: student.instagram || '',
    email: student.email || '',
    sedentaryLevel: student.sedentaryLevel
  });

  // Progress Form State
  const [progressForm, setProgressForm] = useState<{weight: number, measurements: Measurements}>({
    weight: student.progress[0]?.weight || student.weight,
    measurements: student.progress[0]?.measurements || {
      chest: 0, waist: 0, hips: 0, bicepsR: 0, thighR: 0, calf: 0
    }
  });

  // Audio/Meditation States
  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [activeAmbient, setActiveAmbient] = useState<string | null>(null);
  const [ambientVolume, setAmbientVolume] = useState(0.5);
  const ambientAudioRef = useRef<HTMLAudioElement | null>(null);
  const [meditationTips, setMeditationTips] = useState<string>("");
  const [isGeneratingTips, setIsGeneratingTips] = useState(false);

  // Timers
  const [globalTimer, setGlobalTimer] = useState(900);
  const [globalTimerRunning, setGlobalTimerRunning] = useState(false);
  const [activePoseTimer, setActivePoseTimer] = useState<{name: string, total: number, remaining: number} | null>(null);
  const [poseTimerRunning, setPoseTimerRunning] = useState(false);

  useEffect(() => {
    let interval: number;
    if (globalTimerRunning && globalTimer > 0) {
      interval = window.setInterval(() => setGlobalTimer((prev) => prev - 1), 1000);
    }
    return () => clearInterval(interval);
  }, [globalTimerRunning, globalTimer]);

  useEffect(() => {
    let interval: number;
    if (poseTimerRunning && activePoseTimer && activePoseTimer.remaining > 0) {
      interval = window.setInterval(() => {
        setActivePoseTimer(prev => prev ? { ...prev, remaining: prev.remaining - 1 } : null);
      }, 1000);
    } else if (activePoseTimer?.remaining === 0) {
      setPoseTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [poseTimerRunning, activePoseTimer]);

  // Handle Ambient Audio Playback
  useEffect(() => {
    if (activeAmbient) {
      const sound = AMBIENT_SOUNDS.find(s => s.name === activeAmbient);
      if (sound) {
        if (!ambientAudioRef.current) {
          ambientAudioRef.current = new Audio(sound.url);
          ambientAudioRef.current.loop = true;
        } else {
          ambientAudioRef.current.src = sound.url;
        }
        ambientAudioRef.current.volume = ambientVolume;
        ambientAudioRef.current.play().catch(console.error);
      }
    } else {
      if (ambientAudioRef.current) {
        ambientAudioRef.current.pause();
      }
    }
    return () => {
      if (ambientAudioRef.current) {
        ambientAudioRef.current.pause();
      }
    };
  }, [activeAmbient]);

  useEffect(() => {
    if (ambientAudioRef.current) {
      ambientAudioRef.current.volume = ambientVolume;
    }
  }, [ambientVolume]);

  const addExercise = (dayIndex: number) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    const newExercise: Exercise = {
      id: `ex-${Date.now()}`,
      name: 'Novo Exercício',
      muscleGroup: MuscleGroup.CHEST,
      sets: 3,
      reps: '12',
      videoUrl: 'https://www.youtube.com/results?search_query=exercicio'
    };
    updatedWeeklyPlan.days[dayIndex].exercises.push(newExercise);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const updateExercise = (dayIndex: number, exerciseId: string, field: string, value: any) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    const day = updatedWeeklyPlan.days[dayIndex];
    day.exercises = day.exercises.map(ex => 
      ex.id === exerciseId ? { ...ex, [field as keyof Exercise]: value } : ex
    );
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const deleteExercise = (dayIndex: number, exerciseId: string) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIndex].exercises = updatedWeeklyPlan.days[dayIndex].exercises.filter(ex => ex.id !== exerciseId);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const playMeditation = async (theme: string) => {
    setIsGenerating(true);
    try {
      const audioBase64Data = await generateMeditationAudio(theme);
      if (audioBase64Data) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const decode = (base64: string) => {
          const binaryString = atob(base64);
          const bytes = new Uint8Array(binaryString.length);
          for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }
          return bytes;
        };
        const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
          const dataInt16 = new Int16Array(data.buffer);
          const frameCount = dataInt16.length / numChannels;
          const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
          for (let channel = 0; channel < numChannels; channel++) {
            const channelData = buffer.getChannelData(channel);
            for (let i = 0; i < frameCount; i++) {
              channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
            }
          }
          return buffer;
        };
        const audioBuffer = await decodeAudioData(decode(audioBase64Data), audioContext, 24000, 1);
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);
        source.start();
        setAudioBase64(audioBase64Data);
      }
    } catch (error) {
      console.error("Error playing meditation:", error);
    } finally {
      setIsGenerating(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleGenWorkout = async () => {
    setIsGenerating(true);
    const plan = await generateWorkoutPlan(student, workoutPromptInput);
    if (plan) onUpdateStudent({ ...student, weeklyPlan: plan });
    setIsGenerating(false);
    setShowWorkoutPromptModal(false);
  };

  const handleGenNutri = async () => {
    setIsGenerating(true);
    const plan = await generateNutriPlan(student, nutriPromptInput);
    if (plan) onUpdateStudent({ ...student, nutriPlan: plan });
    setIsGenerating(false);
    setShowNutriPromptModal(false);
  };

  const handleGenYoga = async () => {
    setIsGenerating(true);
    const plan = await generateYogaPlan(student, yogaInput);
    if (plan) onUpdateStudent({ ...student, yogaPlan: plan });
    setIsGenerating(false);
    setShowYogaPrompt(false);
  };

  const handleGenMeditationTips = async () => {
    setIsGeneratingTips(true);
    const tips = await generateMeditationTips(student);
    setMeditationTips(tips);
    setIsGeneratingTips(false);
  };

  const handleGenInsights = async () => {
    setIsGenerating(true);
    const insights = await generateProgressInsights(student);
    const updatedProgress = [...student.progress];
    if (updatedProgress.length > 0) {
      updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
      onUpdateStudent({ ...student, progress: updatedProgress });
    }
    setIsGenerating(false);
  };

  const startPoseTimer = (poseName: string, durationStr: string) => {
    let seconds = 60;
    const match = durationStr.match(/(\d+)/);
    if (match) {
      const val = parseInt(match[0]);
      if (durationStr.includes('min')) seconds = val * 60;
      else seconds = val;
    }
    setActivePoseTimer({ name: poseName, total: seconds, remaining: seconds });
    setPoseTimerRunning(true);
  };

  const handleRecipeClick = (recipeName: string) => {
    window.open(`https://www.google.com/search?q=receita+de+${encodeURIComponent(recipeName)}`, '_blank');
  };

  const handleSaveStudentEdit = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateStudent({ ...student, ...editStudentForm });
    setShowEditStudentModal(false);
  };

  const handleSaveProgress = () => {
    const newEntry: ProgressEntry = {
      id: Date.now().toString(),
      date: new Date().toLocaleDateString('pt-BR'),
      weight: progressForm.weight,
      measurements: { ...progressForm.measurements },
      photos: []
    };
    onUpdateStudent({
      ...student,
      progress: [newEntry, ...student.progress]
    });
    setShowProgressModal(false);
  };

  const handleSyncCalendar = () => {
    const icsContent = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//PersonalProAI//TrainingSchedule//PT',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH',
    ];

    const weekDaysMap: Record<string, number> = {
      'Segunda': 1, 'Terça': 2, 'Quarta': 3, 'Quinta': 4, 'Sexta': 5, 'Sábado': 6, 'Domingo': 0
    };

    const today = new Date();
    const currentDay = today.getDay(); // 0 is Sunday

    student.weeklyPlan.days.forEach(day => {
      if (day.focus && day.focus.toLowerCase() !== 'descanso' && day.exercises.length > 0) {
        const targetDayOfWeek = weekDaysMap[day.dayOfWeek];
        const diff = targetDayOfWeek - currentDay;
        const eventDate = new Date(today);
        eventDate.setDate(today.getDate() + (diff < 0 ? diff + 7 : diff));

        // Format YYYYMMDD
        const dateStr = eventDate.toISOString().split('T')[0].replace(/-/g, '');

        const description = day.exercises.map(ex => 
          `- ${ex.name}: ${ex.sets}x${ex.reps}${ex.notes ? ' (' + ex.notes + ')' : ''}`
        ).join('\\n');

        icsContent.push('BEGIN:VEVENT');
        icsContent.push(`SUMMARY:Treino: ${day.focus} (${student.name})`);
        icsContent.push(`DTSTART;VALUE=DATE:${dateStr}`);
        icsContent.push(`DTEND;VALUE=DATE:${dateStr}`);
        icsContent.push(`DESCRIPTION:Objetivo: ${student.goal}\\n\\nExercícios:\\n${description}`);
        icsContent.push('RRULE:FREQ=WEEKLY');
        icsContent.push('STATUS:CONFIRMED');
        icsContent.push('TRANSP:TRANSPARENT');
        icsContent.push('END:VEVENT');
      }
    });

    icsContent.push('END:VCALENDAR');

    const blob = new Blob([icsContent.join('\r\n')], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = window.URL.createObjectURL(blob);
    link.setAttribute('download', `treino-${student.name.toLowerCase().replace(/\s+/g, '-')}.ics`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmi = (weightToUse / Math.pow(student.height / 100, 2)).toFixed(1);

  const shuffleAvatar = () => {
    setEditStudentForm({
      ...editStudentForm,
      avatarUrl: `https://picsum.photos/200/200?random=${Date.now()}`
    });
  };

  return (
    <div className="animate-fade-in space-y-8 pb-32 relative">
      {/* Balão Central de IA - Feedback de Geração */}
      {(isGenerating || isGeneratingTips) && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[250] flex items-center justify-center p-6 animate-fade-in">
          <div className="bg-[#1e293b]/95 border border-lime-400/30 p-8 rounded-[3rem] shadow-[0_0_50px_rgba(163,230,53,0.1)] flex flex-col items-center gap-6 max-w-xs w-full text-center animate-bounce-gentle">
            <div className="relative">
              {/* Emoticon Animado */}
              <div className="text-6xl animate-pulse-scale drop-shadow-glow">
                {activeTab === 'WORKOUT' ? '💪' : 
                 activeTab === 'NUTRI' ? '🥗' : 
                 activeTab === 'YOGA' ? '🧘' : 
                 activeTab === 'MEDITATION' ? '✨' : '🧠'}
              </div>
              {/* Partículas de Brilho */}
              <div className="absolute -top-2 -right-2 text-lime-400 animate-spin-slow">
                <Sparkles size={24} />
              </div>
            </div>
            <div className="space-y-2">
              <div className="flex items-center justify-center gap-2">
                <span className="h-2 w-2 bg-lime-400 rounded-full animate-ping"></span>
                <h3 className="text-white font-black text-lg tracking-tight uppercase">IA Gerando...</h3>
              </div>
