import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup, NutriPlan, YogaPlan, ProgressEntry } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Utilitário para limpar a resposta da IA caso ela venha envolta em blocos de markdown
 */
const cleanJSON = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").trim();
};

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como Personal Trainer de elite. Crie um cronograma de treino semanal de 7 dias (Segunda a Domingo) para o atleta ${student.name}.
    Objetivo: ${student.goal}
    Nível: ${student.level}
    Idade: ${student.age} anos, Peso: ${student.weight}kg, Nível de Sedentarismo: ${student.sedentaryLevel}.
    Restrições Médicas/Lesões: ${student.restrictions}. 
    Notas Adicionais do Professor: ${notes}.

    REGRAS CRÍTICAS:
    1. O retorno DEVE ser um objeto JSON puro.
    2. Use EXATAMENTE estes nomes para grupos musculares: ${Object.values(MuscleGroup).join(', ')}.
    3. Inclua exercícios para todos os dias. Se for dia de descanso, o campo 'focus' deve ser 'Descanso' e 'exercises' deve ser uma lista vazia.
    4. Cada exercício deve ter sets (número), reps (string) e notes (string explicativa da técnica).`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          },
          required: ["days"]
        }
      }
    });

    const data = JSON.parse(cleanJSON(response.text));
    if (!data.days) return null;

    return {
      days: data.days.map((day: any, dayIdx: number) => ({
        dayOfWeek: day.dayOfWeek,
        focus: day.focus,
        exercises: (day.exercises || []).map((ex: any, i: number) => ({
          ...ex,
          id: `ex-${Date.now()}-${dayIdx}-${i}`,
          muscleGroup: Object.values(MuscleGroup).includes(ex.muscleGroup as MuscleGroup) 
            ? ex.muscleGroup as MuscleGroup 
            : MuscleGroup.FULL_BODY,
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name + " exercicio musculacao")}`
        }))
      }))
    };
  } catch (e) { 
    console.error("Erro na geração de treino:", e); 
    return null; 
  }
};

