                {activeTab === 'WORKOUT' ? 'Ajustando cargas e reps...' : 
                 activeTab === 'NUTRI' ? 'Equilibrando macros...' : 
                 activeTab === 'YOGA' ? 'Alinhando chakras...' : 
                 activeTab === 'MEDITATION' ? 'Sintonizando frequências...' : 'Processando dados...'}
