import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup, NutriPlan, YogaPlan, ProgressEntry } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const cleanJSON = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").trim();
};

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como Personal Trainer Master. Gere um treino semanal de 7 dias (Segunda a Domingo) em JSON para ${student.name}.
    Objetivo: ${student.goal}. Nível: ${student.level}. Restrições: ${student.restrictions}. 
    Notas: ${notes}. Use apenas estes grupos musculares: ${Object.values(MuscleGroup).join(', ')}.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          },
          required: ["days"]
        }
      }
    });

    const data = JSON.parse(cleanJSON(response.text));
    return {
      days: data.days.map((day: any, dIdx: number) => ({
        ...day,
        exercises: (day.exercises || []).map((ex: any, eIdx: number) => ({
          ...ex,
          id: `ai-ex-${Date.now()}-${dIdx}-${eIdx}`,
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name + " execucao musculacao")}`
        }))
      }))
    };
  } catch (e) {
    console.error("Workout generation error:", e);
    return null;
  }
};

export const generateNutriPlan = async (student: Student, notes: string): Promise<NutriPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Nutricionista: Gere um plano alimentar de 7 dias em JSON para ${student.name}. Objetivo: ${student.goal}. Peso: ${student.weight}kg. Altura: ${student.height}cm. Notas: ${notes}.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weeklyMeals: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT, 
                properties: { 
                  dayOfWeek: { type: Type.STRING }, 
                  meals: { 
                    type: Type.ARRAY, 
                    items: { 
                      type: Type.OBJECT, 
                      properties: { 
                        time: { type: Type.STRING }, 
                        label: { type: Type.STRING }, 
                        description: { type: Type.STRING } 
                      } 
                    } 
                  } 
                } 
              } 
            },
            recipes: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT, 
                properties: { 
                  name: { type: Type.STRING }, 
                  ingredients: { type: Type.ARRAY, items: { type: Type.STRING } }, 
                  instructions: { type: Type.STRING }, 
                  macros: { 
                    type: Type.OBJECT, 
                    properties: { 
                      protein: { type: Type.NUMBER }, 
                      carbs: { type: Type.NUMBER }, 
                      fats: { type: Type.NUMBER }, 
                      calories: { type: Type.NUMBER } 
                    } 
                  } 
                } 
              } 
            },
            shoppingList: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { item: { type: Type.STRING }, category: { type: Type.STRING } } } },
            dailyMacrosTarget: { type: Type.OBJECT, properties: { protein: { type: Type.NUMBER }, carbs: { type: Type.NUMBER }, fats: { type: Type.NUMBER }, calories: { type: Type.NUMBER } } }
          }
        }
      }
    });

    const data = JSON.parse(cleanJSON(response.text));
    return {
      ...data,
      recipes: data.recipes.map((r: any, i: number) => ({ ...r, id: `r-${i}` })),
      shoppingList: data.shoppingList.map((s: any) => ({ ...s, checked: false }))
    };
  } catch (e) {
    console.error("Nutri generation error:", e);
    return null;
  }
};

