export const generateProgressInsights = async (student: Student): Promise<string> => {
  if (!process.env.API_KEY || student.progress.length === 0) return "Continue treinando para gerar insights!";
  const ai = getAI();
  const prompt = `Analise os dados de evolução de ${student.name}: ${JSON.stringify(student.progress[0])}. Objetivo: ${student.goal}. Dê um feedback de 2 frases.`;
  try {
    const response = await ai.models.generateContent({ model: "gemini-3-flash-preview", contents: prompt });
    return response.text || "Ótimo trabalho!";
  } catch (e) { return "Mantenha o foco nos resultados!"; }
};

export const generateMeditationAudio = async (theme: string): Promise<string | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Guia de meditação curta sobre ${theme}. Fale de forma relaxante.`;
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      }
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
  } catch (e) { return null; }
};

