  { id: 'chuva', name: 'Chuva Tropical', url: 'https://actions.google.com/sounds/v1/weather/rain_heavy_loud.ogg' },
  { id: 'floresta', name: 'Floresta Zen', url: 'https://actions.google.com/sounds/v1/ambient/morning_birds.ogg' },
