                      <th>Grupo</th>
                      <th>Séries</th>
                      <th>Reps</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${day.exercises.map(ex => `
                      <tr>
                        <td>
                          <strong>${ex.name}</strong>
                          ${ex.notes ? `<div class="notes">${ex.notes}</div>` : ''}
                        </td>
                        <td>${ex.muscleGroup}</td>
                        <td>${ex.sets}</td>
                        <td>${ex.reps}</td>
                      </tr>
                    `).join('')}
                  </tbody>
                </table>
              ` : '<p>Dia de Descanso Ativo / Recuperação.</p>'}
            </div>
          `).join('')}
        </body>
      </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
  };

  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmiNumber = parseFloat((weightToUse / Math.pow(student.height / 100, 2)).toFixed(1));

  const getBMICategory = (bmi: number) => {
    if (bmi < 18.5) return { category: 'Abaixo do peso', tip: 'Considere aumentar o aporte calórico com alimentos nutritivos.', color: 'text-blue-400', bg: 'bg-blue-400/10 border-blue-400/30' };
    if (bmi < 25) return { category: 'Peso normal', tip: 'Excelente! Mantenha seus hábitos saudáveis de nutrição e treino.', color: 'text-lime-400', bg: 'bg-lime-400/10 border-lime-400/30' };
    if (bmi < 30) return { category: 'Sobrepeso', tip: 'Foco em déficit calórico moderado e aumento do gasto energético.', color: 'text-orange-400', bg: 'bg-orange-400/10 border-orange-400/30' };
    return { category: 'Obesidade', tip: 'Procure orientação multidisciplinar para um plano de saúde seguro.', color: 'text-red-400', bg: 'bg-red-400/10 border-red-400/30' };
  };

  const bmiInfo = getBMICategory(bmiNumber);

  const shuffleAvatar = () => {
    setEditStudentForm({
      ...editStudentForm,
      avatarUrl: `https://picsum.photos/200/200?random=${Date.now()}`
    });
  };

  // Evolution Graph Logic (Simple SVG implementation)
  const evolutionGraph = useMemo(() => {
    if (student.progress.length < 2) return null;
    const data = [...student.progress].reverse();
    const minWeight = Math.min(...data.map(d => d.weight)) - 2;
    const maxWeight = Math.max(...data.map(d => d.weight)) + 2;
    const range = maxWeight - minWeight;
    const width = 500;
    const height = 150;

    const points = data.map((d, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((d.weight - minWeight) / range) * height;
      return `${x},${y}`;
    }).join(' ');

