  waist: 'Cintura',
  hips: 'Quadril',
  bicepsR: 'Bíceps (Dir)',
  bicepsL: 'Bíceps (Esq)',
  thighR: 'Coxa (Dir)',
  thighL: 'Coxa (Esq)',
  calf: 'Panturrilha',
  neck: 'Pescoço',
  forearm: 'Antebraço'
};

const AMBIENT_SOUNDS = [
  { id: 'chuva', name: 'Chuva Tropical', url: 'https://actions.google.com/sounds/v1/weather/rain_heavy_loud.ogg' },
  { id: 'floresta', name: 'Floresta Zen', url: 'https://actions.google.com/sounds/v1/ambient/morning_birds.ogg' },
  { id: 'ondas', name: 'Ondas do Mar', url: 'https://actions.google.com/sounds/v1/water/waves_crashing_on_shore.ogg' },
  { id: 'alfa', name: 'Ondas Alfa', url: 'https://actions.google.com/sounds/v1/science_fiction/low_frequency_hum.ogg' },
];

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);
  const [isGenerating, setIsGenerating] = useState(false);

  // Modals visibility
  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [showEditWorkoutModal, setShowEditWorkoutModal] = useState(false);
  const [showYogaPrompt, setShowYogaPrompt] = useState(false);
  const [showWorkoutPromptModal, setShowWorkoutPromptModal] = useState(false);
  const [showNutriPromptModal, setShowNutriPromptModal] = useState(false);

  // New Modals for History/Delete
  const [viewingHistoryPlan, setViewingHistoryPlan] = useState<WeeklyPlan | null>(null);
  const [deletingProgressId, setDeletingProgressId] = useState<string | null>(null);
  const [deleteStep, setDeleteStep] = useState<1 | 2>(1); // 1 = First confirm, 2 = "Really delete?"
  const [editingProgressId, setEditingProgressId] = useState<string | null>(null);

  // Prompt Inputs
  const [workoutPromptInput, setWorkoutPromptInput] = useState("");
  const [nutriPromptInput, setNutriPromptInput] = useState("");
  const [yogaInput, setYogaInput] = useState("");

  // Edit Student Form State
  const [editStudentForm, setEditStudentForm] = useState({
    name: student.name,
    age: student.age,
    height: student.height,
    weight: student.weight,
    goal: student.goal,
    level: student.level,
    avatarUrl: student.avatarUrl,
    restrictions: student.restrictions || '',
    whatsapp: student.whatsapp || '',
    instagram: student.instagram || '',
    email: student.email || '',
    sedentaryLevel: student.sedentaryLevel
  });

  // Progress Form State
  const [progressForm, setProgressForm] = useState<{weight: number, measurements: Measurements}>({
    weight: student.progress[0]?.weight || student.weight,
    measurements: student.progress[0]?.measurements || {
      chest: 0, waist: 0, hips: 0, bicepsR: 0, bicepsL: 0, thighR: 0, thighL: 0, calf: 0, neck: 0, forearm: 0
    }
  });

  // Audio/Meditation States
  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [activeAmbient, setActiveAmbient] = useState<string | null>(null);
  const [ambientVolume, setAmbientVolume] = useState(0.5);
  const ambientAudioRef = useRef<HTMLAudioElement | null>(null);
  const [meditationTips, setMeditationTips] = useState<string>("");
  const [isGeneratingTips, setIsGeneratingTips] = useState(false);

  // Timers
  const [globalTimer, setGlobalTimer] = useState(900);
  const [globalTimerRunning, setGlobalTimerRunning] = useState(false);
  const [activePoseTimer, setActivePoseTimer] = useState<{name: string, total: number, remaining: number} | null>(null);
  const [poseTimerRunning, setPoseTimerRunning] = useState(false);

  useEffect(() => {
    let interval: number;
    if (globalTimerRunning && globalTimer > 0) {
      interval = window.setInterval(() => setGlobalTimer((prev) => prev - 1), 1000);
    }
    return () => clearInterval(interval);
  }, [globalTimerRunning, globalTimer]);

  useEffect(() => {
    let interval: number;
    if (poseTimerRunning && activePoseTimer && activePoseTimer.remaining > 0) {
      interval = window.setInterval(() => {
        setActivePoseTimer(prev => prev ? { ...prev, remaining: prev.remaining - 1 } : null);
      }, 1000);
    } else if (activePoseTimer?.remaining === 0) {
      setPoseTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [poseTimerRunning, activePoseTimer]);

  // Handle Ambient Audio Playback
  useEffect(() => {
    if (activeAmbient) {
      const sound = AMBIENT_SOUNDS.find(s => s.name === activeAmbient);
      if (sound) {
        if (!ambientAudioRef.current) {
          ambientAudioRef.current = new Audio(sound.url);
          ambientAudioRef.current.loop = true;
        } else {
          ambientAudioRef.current.src = sound.url;
        }
        ambientAudioRef.current.volume = ambientVolume;
        ambientAudioRef.current.play().catch(console.error);
      }
    } else {
      if (ambientAudioRef.current) {
        ambientAudioRef.current.pause();
      }
    }
    return () => {
      if (ambientAudioRef.current) {
        ambientAudioRef.current.pause();
      }
    };
  }, [activeAmbient]);

  useEffect(() => {
    if (ambientAudioRef.current) {
      ambientAudioRef.current.volume = ambientVolume;
    }
  }, [ambientVolume]);

  const addExercise = (dayIndex: number) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    const newExercise: Exercise = {
      id: `ex-${Date.now()}`,
      name: 'Novo Exercício',
      muscleGroup: MuscleGroup.CHEST,
      sets: 3,
      reps: '12',
      videoUrl: 'https://www.youtube.com/results?search_query=exercicio',
      notes: 'Ajustar carga/repetição conforme necessário'
    };
    updatedWeeklyPlan.days[dayIndex].exercises.push(newExercise);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const updateExercise = (dayIndex: number, exerciseId: string, field: string, value: any) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    const day = updatedWeeklyPlan.days[dayIndex];
    day.exercises = day.exercises.map(ex => 
      ex.id === exerciseId ? { ...ex, [field as keyof Exercise]: value } : ex
    );
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const deleteExercise = (dayIndex: number, exerciseId: string) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    updatedWeeklyPlan.days[dayIndex].exercises = updatedWeeklyPlan.days[dayIndex].exercises.filter(ex => ex.id !== exerciseId);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const playMeditation = async (theme: string) => {
    setIsGenerating(true);
    try {
      const audioBase64Data = await generateMeditationAudio(theme);
      if (audioBase64Data) {
        const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const decode = (base64: string) => {
          const binaryString = atob(base64);
          const bytes = new Uint8Array(binaryString.length);
          for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }
          return bytes;
        };
        const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
          const dataInt16 = new Int16Array(data.buffer);
          const frameCount = dataInt16.length / numChannels;
          const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
          for (let channel = 0; channel < numChannels; channel++) {
            const channelData = buffer.getChannelData(channel);
            for (let i = 0; i < frameCount; i++) {
              channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
            }
          }
          return buffer;
        };
        const audioBuffer = await decodeAudioData(decode(audioBase64Data), audioContext, 24000, 1);
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);
        source.start();
        setAudioBase64(audioBase64Data);
      }
    } catch (error) {
      console.error("Error playing meditation:", error);
    } finally {
      setIsGenerating(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleGenWorkout = async () => {
    setIsGenerating(true);
    try {
      const plan = await generateWorkoutPlan(student, workoutPromptInput);
      if (plan) {
        const updatedHistory = student.workoutHistory ? [student.weeklyPlan, ...student.workoutHistory] : [student.weeklyPlan];
        onUpdateStudent({ ...student, weeklyPlan: { ...plan, generatedAt: new Date().toLocaleDateString('pt-BR') }, workoutHistory: updatedHistory.slice(0, 10) });
      }
    } finally {
      setIsGenerating(false);
      setShowWorkoutPromptModal(false);
    }
  };

  const handleGenIANote = async (dayIndex: number, exId: string, exName: string) => {
    setIsGenerating(true);
    try {
      const note = await generateExerciseNote(student, exName);
      updateExercise(dayIndex, exId, 'notes', note);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleGenNutri = async () => {
    setIsGenerating(true);
    try {
      const plan = await generateNutriPlan(student, nutriPromptInput);
      if (plan) onUpdateStudent({ ...student, nutriPlan: plan });
    } finally {
      setIsGenerating(false);
      setShowNutriPromptModal(false);
    }
  };

  const handleGenYoga = async () => {
    setIsGenerating(true);
    try {
      const plan = await generateYogaPlan(student, yogaInput);
      if (plan) {
        const updatedHistory = student.yogaHistory ? [student.yogaPlan!, ...student.yogaHistory] : (student.yogaPlan ? [student.yogaPlan] : []);
        onUpdateStudent({ ...student, yogaPlan: { ...plan, generatedAt: new Date().toLocaleDateString('pt-BR') }, yogaHistory: updatedHistory.slice(0, 10) });
      }
    } finally {
      setIsGenerating(false);
      setShowYogaPrompt(false);
    }
  };

  const handleGenMeditationTips = async () => {
    setIsGeneratingTips(true);
    try {
      const tips = await generateMeditationTips(student);
      setMeditationTips(tips);
    } finally {
      setIsGeneratingTips(false);
    }
  };

  const handleGenInsights = async () => {
    setIsGenerating(true);
    try {
      const insights = await generateProgressInsights(student);
      const updatedProgress = [...student.progress];
      if (updatedProgress.length > 0) {
        updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
        onUpdateStudent({ ...student, progress: updatedProgress });
      } else {
        alert("Dica da IA: " + insights);
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const startPoseTimer = (poseName: string, durationStr: string) => {
    let seconds = 60;
    const match = durationStr.match(/(\d+)/);
    if (match) {
      const val = parseInt(match[0]);
      if (durationStr.includes('min')) seconds = val * 60;
      else seconds = val;
    }
    setActivePoseTimer({ name: poseName, total: seconds, remaining: seconds });
    setPoseTimerRunning(true);
  };

  const handleRecipeClick = (recipeName: string) => {
    window.open(`https://www.google.com/search?q=receita+de+${encodeURIComponent(recipeName)}`, '_blank');
  };

  const handleSaveStudentEdit = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateStudent({ ...student, ...editStudentForm });
    setShowEditStudentModal(false);
  };

  // --- PROGRESS LOGIC (Create, Update, Delete) ---

  const openNewCheckin = () => {
    setEditingProgressId(null);
    setProgressForm({
      weight: student.weight,
      measurements: { chest: 0, waist: 0, hips: 0, bicepsR: 0, bicepsL: 0, thighR: 0, thighL: 0, calf: 0, neck: 0, forearm: 0 }
    });
    setShowProgressModal(true);
  };

  const openEditCheckin = (entry: ProgressEntry) => {
    setEditingProgressId(entry.id);
    setProgressForm({
      weight: entry.weight,
      measurements: { 
        chest: 0, waist: 0, hips: 0, bicepsR: 0, bicepsL: 0, thighR: 0, thighL: 0, calf: 0, neck: 0, forearm: 0,
        ...entry.measurements 
      }
    });
    setShowProgressModal(true);
  };

  const handleSaveProgress = () => {
    let updatedProgress = [...student.progress];

    if (editingProgressId) {
      // Update existing
      updatedProgress = updatedProgress.map(entry => {
        if (entry.id === editingProgressId) {
          return {
            ...entry,
            weight: progressForm.weight,
            measurements: { ...progressForm.measurements }
          };
        }
        return entry;
      });
    } else {
      // Create new
      const newEntry: ProgressEntry = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString('pt-BR'),
        weight: progressForm.weight,
        measurements: { ...progressForm.measurements },
        photos: []
      };
      updatedProgress = [newEntry, ...updatedProgress];
    }

    onUpdateStudent({
      ...student,
      progress: updatedProgress
    });
    setShowProgressModal(false);
    setEditingProgressId(null);
  };

  const confirmDeleteProgress = () => {
    if (deleteStep === 1) {
      setDeleteStep(2);
      return;
    }
    // Step 2 confirmed
    const updatedProgress = student.progress.filter(p => p.id !== deletingProgressId);
    onUpdateStudent({ ...student, progress: updatedProgress });
    setDeletingProgressId(null);
    setDeleteStep(1);
  };

  // --- PDF GENERATION LOGIC ---

  const generatePDF = (plan: WeeklyPlan, title: string) => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const htmlContent = `
      <html>
        <head>
          <title>${title}</title>
          <style>
            body { font-family: sans-serif; padding: 40px; color: #333; }
            h1 { color: #0f172a; border-bottom: 2px solid #0f172a; padding-bottom: 10px; }
            .student-info { margin-bottom: 30px; background: #f8fafc; padding: 20px; border-radius: 8px; }
            .day-block { margin-bottom: 40px; break-inside: avoid; }
            .day-header { font-size: 1.4em; font-weight: bold; background: #e2e8f0; padding: 10px; border-radius: 4px; margin-bottom: 15px; }
            table { width: 100%; border-collapse: collapse; }
            th, td { text-align: left; padding: 12px; border-bottom: 1px solid #cbd5e1; }
            th { background: #f1f5f9; text-transform: uppercase; font-size: 0.8em; color: #64748b; }
            .notes { font-style: italic; color: #64748b; font-size: 0.9em; margin-top: 4px; }
          </style>
        </head>
        <body>
          <h1>${title}</h1>
          <div class="student-info">
            <strong>Atleta:</strong> ${student.name}<br>
            <strong>Objetivo:</strong> ${student.goal}<br>
            <strong>Nível:</strong> ${student.level}<br>
            <strong>Gerado em:</strong> ${plan.generatedAt || new Date().toLocaleDateString('pt-BR')}<br>
            <strong>Personal Trainer:</strong> Personal Pro AI
          </div>
          ${plan.days.map(day => `
            <div class="day-block">
              <div class="day-header">${day.dayOfWeek} - ${day.focus}</div>
              ${day.exercises.length > 0 ? `
                <table>
                  <thead>
                    <tr>
                      <th>Exercício</th>
                      <th>Grupo</th>
                      <th>Séries</th>
                      <th>Reps</th>
                    </tr>
                  </thead>
                  <tbody>
                    ${day.exercises.map(ex => `
                      <tr>
                        <td>
                          <strong>${ex.name}</strong>
                          ${ex.notes ? `<div class="notes">${ex.notes}</div>` : ''}
                        </td>
                        <td>${ex.muscleGroup}</td>
                        <td>${ex.sets}</td>
                        <td>${ex.reps}</td>
                      </tr>
                    `).join('')}
                  </tbody>
                </table>
              ` : '<p>Dia de Descanso Ativo / Recuperação.</p>'}
            </div>
          `).join('')}
        </body>
      </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
  };

  const handleExportCurrentPDF = () => generatePDF(student.weeklyPlan, `Ficha de Treino - ${student.name}`);
  const handleExportHistoryPDF = (plan: WeeklyPlan, date: string) => generatePDF(plan, `Histórico ${date} - ${student.name}`);

  const handleSyncCalendar = () => {
    const icsContent = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//PersonalProAI//TrainingSchedule//PT',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH',
    ];

    const weekDaysMap: Record<string, number> = {
      'Segunda': 1, 'Terça': 2, 'Quarta': 3, 'Quinta': 4, 'Sexta': 5, 'Sábado': 6, 'Domingo': 0
    };

    const today = new Date();
    const currentDay = today.getDay(); 

    student.weeklyPlan.days.forEach(day => {
      if (day.focus && day.focus.toLowerCase() !== 'descanso' && day.exercises.length > 0) {
        const targetDayOfWeek = weekDaysMap[day.dayOfWeek];
        const diff = targetDayOfWeek - currentDay;
        const eventDate = new Date(today);
        eventDate.setDate(today.getDate() + (diff < 0 ? diff + 7 : diff));

        const dateStr = eventDate.toISOString().split('T')[0].replace(/-/g, '');

        const description = day.exercises.map(ex => 
          `- ${ex.name}: ${ex.sets}x${ex.reps}${ex.notes ? ' (' + ex.notes + ')' : ''}`
        ).join('\\n');

        icsContent.push('BEGIN:VEVENT');
        icsContent.push(`SUMMARY:Treino: ${day.focus} (${student.name})`);
        icsContent.push(`DTSTART;VALUE=DATE:${dateStr}`);
        icsContent.push(`DTEND;VALUE=DATE:${dateStr}`);
        icsContent.push(`DESCRIPTION:Objetivo: ${student.goal}\\n\\nExercícios:\\n${description}`);
        icsContent.push('RRULE:FREQ=WEEKLY');
        icsContent.push('STATUS:CONFIRMED');
        icsContent.push('TRANSP:TRANSPARENT');
        icsContent.push('END:VEVENT');
      }
    });

    icsContent.push('END:VCALENDAR');

    const blob = new Blob([icsContent.join('\r\n')], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = window.URL.createObjectURL(blob);
    link.setAttribute('download', `treino-${student.name.toLowerCase().replace(/\s+/g, '-')}.ics`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmiNumber = parseFloat((weightToUse / Math.pow(student.height / 100, 2)).toFixed(1));

  const getBMICategory = (bmi: number) => {
    if (bmi < 18.5) return { category: 'Abaixo do peso', tip: 'Considere aumentar o aporte calórico com alimentos nutritivos.', color: 'text-blue-400', bg: 'bg-blue-400/10 border-blue-400/30' };
    if (bmi < 25) return { category: 'Peso normal', tip: 'Excelente! Mantenha seus hábitos saudáveis de nutrição e treino.', color: 'text-lime-400', bg: 'bg-lime-400/10 border-lime-400/30' };
    if (bmi < 30) return { category: 'Sobrepeso', tip: 'Foco em déficit calórico moderado e aumento do gasto energético.', color: 'text-orange-400', bg: 'bg-orange-400/10 border-orange-400/30' };
    return { category: 'Obesidade', tip: 'Procure orientação multidisciplinar para um plano de saúde seguro.', color: 'text-red-400', bg: 'bg-red-400/10 border-red-400/30' };
  };

  const bmiInfo = getBMICategory(bmiNumber);

  const shuffleAvatar = () => {
    setEditStudentForm({
      ...editStudentForm,
      avatarUrl: `https://picsum.photos/200/200?random=${Date.now()}`
    });
  };

  // Evolution Graph Logic (Simple SVG implementation)
  const evolutionGraph = useMemo(() => {
    if (student.progress.length < 2) return null;
    const data = [...student.progress].reverse();
    const minWeight = Math.min(...data.map(d => d.weight)) - 2;
    const maxWeight = Math.max(...data.map(d => d.weight)) + 2;
    const range = maxWeight - minWeight;
    const width = 500;
    const height = 150;

    const points = data.map((d, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((d.weight - minWeight) / range) * height;
      return `${x},${y}`;
    }).join(' ');

    return (
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-32 mt-4 overflow-visible">
        <defs>
          <linearGradient id="gradientLine" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#a3e635" stopOpacity="0.5"/>
            <stop offset="100%" stopColor="#a3e635" stopOpacity="0"/>
          </linearGradient>
        </defs>
        <polyline fill="none" stroke="#a3e635" strokeWidth="4" points={points} className="drop-shadow-glow" strokeLinecap="round" strokeLinejoin="round" />
        {data.map((d, i) => {
          const x = (i / (data.length - 1)) * width;
          const y = height - ((d.weight - minWeight) / range) * height;
          return (
            <g key={i}>
              <circle cx={x} cy={y} r="6" className="fill-slate-900 stroke-lime-400 stroke-2" />
              <text x={x} y={y - 15} textAnchor="middle" fill="#94a3b8" fontSize="12" fontWeight="bold">{d.weight}kg</text>
            </g>
          );
        })}
      </svg>
    );
  }, [student.progress]);

  return (
    <div className="animate-fade-in space-y-8 pb-32 relative">
      {/* Balão Central de IA */}
      {(isGenerating || isGeneratingTips) && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[500] flex items-center justify-center p-6 animate-fade-in">
          <div className="bg-[#1e293b]/95 border border-lime-400/30 p-10 rounded-[4rem] shadow-[0_0_60px_rgba(163,230,53,0.2)] flex flex-col items-center gap-6 max-w-sm w-full text-center animate-bounce-gentle">
            <div className="relative">
              <div className="text-7xl animate-pulse-scale drop-shadow-glow">
                {activeTab === 'WORKOUT' ? '💪' : activeTab === 'NUTRI' ? '🥗' : activeTab === 'YOGA' ? '🧘' : activeTab === 'MEDITATION' ? '✨' : '🧠'}
              </div>
              <div className="absolute -top-3 -right-3 text-lime-400 animate-spin-slow">
                <Sparkles size={28} />
              </div>
            </div>
            <div className="space-y-3">
              <div className="flex items-center justify-center gap-3">
                <span className="h-3 w-3 bg-lime-400 rounded-full animate-ping"></span>
                <h3 className="text-white font-black text-xl tracking-tighter uppercase">Processando</h3>
              </div>
              <p className="text-slate-400 text-sm font-medium leading-relaxed px-4">Gerando dados otimizados...</p>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col gap-6 bg-[#1e293b] p-6 rounded-3xl border border-slate-800 shadow-xl">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-center gap-6">
            <button onClick={onBack} className="p-2 hover:bg-slate-800 rounded-xl transition-all text-slate-400 hover:text-white"><ArrowLeft size={24} /></button>
            <img src={student.avatarUrl} className="w-20 h-20 rounded-2xl border-2 border-lime-400 object-cover" />
            <div>
              <div className="flex flex-wrap items-center gap-4">
                <h1 className="text-3xl font-black text-white leading-none tracking-tight">{student.name}</h1>
