    if (editingProgressId) {
      // Update existing
      updatedProgress = updatedProgress.map(entry => {
        if (entry.id === editingProgressId) {
          return {
            ...entry,
            weight: progressForm.weight,
            measurements: { ...progressForm.measurements }
          };
        }
        return entry;
      });
    } else {
      // Create new
      const newEntry: ProgressEntry = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString('pt-BR'),
        weight: progressForm.weight,
        measurements: { ...progressForm.measurements },
        photos: []
      };
      updatedProgress = [newEntry, ...updatedProgress];
    }

    onUpdateStudent({
      ...student,
      progress: updatedProgress
    });
    setShowProgressModal(false);
    setEditingProgressId(null);
  };

  const confirmDeleteProgress = () => {
    if (deleteStep === 1) {
      setDeleteStep(2);
      return;
    }
    // Step 2 confirmed
    const updatedProgress = student.progress.filter(p => p.id !== deletingProgressId);
    onUpdateStudent({ ...student, progress: updatedProgress });
