  const handleExportCurrentPDF = () => generatePDF(student.weeklyPlan, `Ficha de Treino - ${student.name}`);
  const handleExportHistoryPDF = (plan: WeeklyPlan, date: string) => generatePDF(plan, `Histórico ${date} - ${student.name}`);

  const handleSyncCalendar = () => {
    const icsContent = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//PersonalProAI//TrainingSchedule//PT',
      'CALSCALE:GREGORIAN',
      'METHOD:PUBLISH',
    ];

    const weekDaysMap: Record<string, number> = {
      'Segunda': 1, 'Terça': 2, 'Quarta': 3, 'Quinta': 4, 'Sexta': 5, 'Sábado': 6, 'Domingo': 0
    };

    const today = new Date();
    const currentDay = today.getDay(); 

    student.weeklyPlan.days.forEach(day => {
      if (day.focus && day.focus.toLowerCase() !== 'descanso' && day.exercises.length > 0) {
        const targetDayOfWeek = weekDaysMap[day.dayOfWeek];
        const diff = targetDayOfWeek - currentDay;
        const eventDate = new Date(today);
        eventDate.setDate(today.getDate() + (diff < 0 ? diff + 7 : diff));

        const dateStr = eventDate.toISOString().split('T')[0].replace(/-/g, '');

        const description = day.exercises.map(ex => 
          `- ${ex.name}: ${ex.sets}x${ex.reps}${ex.notes ? ' (' + ex.notes + ')' : ''}`
        ).join('\\n');

        icsContent.push('BEGIN:VEVENT');
        icsContent.push(`SUMMARY:Treino: ${day.focus} (${student.name})`);
        icsContent.push(`DTSTART;VALUE=DATE:${dateStr}`);
        icsContent.push(`DTEND;VALUE=DATE:${dateStr}`);
        icsContent.push(`DESCRIPTION:Objetivo: ${student.goal}\\n\\nExercícios:\\n${description}`);
        icsContent.push('RRULE:FREQ=WEEKLY');
        icsContent.push('STATUS:CONFIRMED');
        icsContent.push('TRANSP:TRANSPARENT');
        icsContent.push('END:VEVENT');
      }
    });

    icsContent.push('END:VCALENDAR');

    const blob = new Blob([icsContent.join('\r\n')], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = window.URL.createObjectURL(blob);
    link.setAttribute('download', `treino-${student.name.toLowerCase().replace(/\s+/g, '-')}.ics`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

