  const evolutionGraph = useMemo(() => {
    if (student.progress.length < 2) return null;
    const data = [...student.progress].reverse();
    const minWeight = Math.min(...data.map(d => d.weight)) - 2;
    const maxWeight = Math.max(...data.map(d => d.weight)) + 2;
    const range = maxWeight - minWeight;
    const width = 500;
    const height = 150;

    const points = data.map((d, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((d.weight - minWeight) / range) * height;
      return `${x},${y}`;
    }).join(' ');

    return (
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-32 mt-4 overflow-visible">
        <defs>
          <linearGradient id="gradientLine" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#a3e635" stopOpacity="0.5"/>
            <stop offset="100%" stopColor="#a3e635" stopOpacity="0"/>
          </linearGradient>
        </defs>
        <polyline fill="none" stroke="#a3e635" strokeWidth="4" points={points} className="drop-shadow-glow" strokeLinecap="round" strokeLinejoin="round" />
        {data.map((d, i) => {
          const x = (i / (data.length - 1)) * width;
          const y = height - ((d.weight - minWeight) / range) * height;
          return (
            <g key={i}>
              <circle cx={x} cy={y} r="6" className="fill-slate-900 stroke-lime-400 stroke-2" />
              <text x={x} y={y - 15} textAnchor="middle" fill="#94a3b8" fontSize="12" fontWeight="bold">{d.weight}kg</text>
