                    <div key={idx} className="bg-slate-900/50 rounded-[2.5rem] p-8 border border-slate-800">
                       <h3 className="text-xl font-black text-lime-400 uppercase tracking-widest mb-6 border-b border-slate-800 pb-4">{day.dayOfWeek} • {day.focus}</h3>
