                                   </div>
                                   <div className="text-right">
                                      <p className="text-white font-black text-xl">{ex.sets} x {ex.reps}</p>
                                   </div>
                                </div>
                             ))}
                          </div>
                       )}
                    </div>
                 ))}
              </div>
              <div className="p-6 border-t border-slate-800 bg-[#1e293b] flex justify-end">
                 <button onClick={() => handleExportHistoryPDF(viewingHistoryPlan, viewingHistoryPlan.generatedAt || 'N/A')} className="bg-lime-400 text-slate-900 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-lime-500 transition-all shadow-lg flex items-center gap-2">
                    <FileDown size={20} /> Exportar PDF
                 </button>
              </div>
           </div>
        </div>
      )}

      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s ease-out; }
        .animate-scale-in { animation: scaleIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1); }
        .animate-bounce-gentle { animation: bounceGentle 3s infinite ease-in-out; }
        .animate-pulse-scale { animation: pulseScale 1.5s infinite ease-in-out; }
        .animate-spin-slow { animation: spinSlow 6s infinite linear; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes scaleIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        @keyframes bounceGentle { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-15px); } }
        @keyframes pulseScale { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.1); } }
        @keyframes spinSlow { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        .drop-shadow-glow { filter: drop-shadow(0 0 10px rgba(163,230,53,0.3)); }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .shadow-text { text-shadow: 0 0 30px rgba(168,85,247,0.4); }
      `}</style>
    </div>
  );
};

