import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Student, WeeklyPlan, MuscleGroup, NutriPlan, YogaPlan, ProgressEntry, Exercise } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const cleanJSON = (text: string) => {
  if (!text) return "{}";
  try {
    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      return text.substring(firstBrace, lastBrace + 1);
    }
    return text.replace(/```json/g, "").replace(/```/g, "").trim();
  } catch (e) {
    return text;
  }
};

export const generateWorkoutPlan = async (student: Student, notes: string): Promise<WeeklyPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Atue como Personal Trainer Master. Gere um treino semanal de 7 dias (Segunda a Domingo) em JSON para ${student.name}.
    Objetivo: ${student.goal}. Nível: ${student.level}. Restrições: ${student.restrictions}. 
    Notas: ${notes}. Use apenas estes grupos musculares: ${Object.values(MuscleGroup).join(', ')}.
    Para cada exercício, o campo 'notes' deve vir preenchido com: "Ajustar carga/repetição conforme necessário" ou dicas específicas.
    Responda APENAS o JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            days: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  dayOfWeek: { type: Type.STRING },
                  focus: { type: Type.STRING },
                  exercises: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        muscleGroup: { type: Type.STRING },
                        sets: { type: Type.NUMBER },
                        reps: { type: Type.STRING },
                        notes: { type: Type.STRING },
                      },
                      required: ["name", "muscleGroup", "sets", "reps"]
                    }
                  }
                },
                required: ["dayOfWeek", "focus", "exercises"]
              }
            }
          },
          required: ["days"]
        }
      }
    });

    if (!response.text) throw new Error("Sem resposta de texto");

    const jsonStr = cleanJSON(response.text);
    const data = JSON.parse(jsonStr);

    if (!data.days || !Array.isArray(data.days)) return null;

    return {
      days: data.days.map((day: any, dIdx: number) => ({
        dayOfWeek: day.dayOfWeek || 'Dia Desconhecido',
        focus: day.focus || 'Geral',
        exercises: (day.exercises || []).map((ex: any, eIdx: number) => ({
          ...ex,
          id: `ai-ex-${Date.now()}-${dIdx}-${eIdx}`,
          name: ex.name || 'Exercício',
          muscleGroup: ex.muscleGroup || 'Geral',
          sets: Number(ex.sets) || 3,
          reps: String(ex.reps) || '10',
          videoUrl: `https://www.youtube.com/results?search_query=${encodeURIComponent((ex.name || 'exercicio') + " execucao musculacao")}`
        }))
      }))
    };
  } catch (e) {
    console.error("Workout generation error:", e);
    return null;
  }
};

export const generateExerciseNote = async (student: Student, exerciseName: string): Promise<string> => {
  if (!process.env.API_KEY) return "Foco na execução correta.";
  const ai = getAI();
  const prompt = `Gere uma observação técnica curta (máximo 15 palavras) para o exercício "${exerciseName}" focado no aluno ${student.name} que tem objetivo de ${student.goal} e nível ${student.level}. Restrições: ${student.restrictions}.`;
  try {
    const response = await ai.models.generateContent({ model: "gemini-3-flash-preview", contents: prompt });
    return response.text || "Foco na cadência e controle do movimento.";
  } catch (e) {
    return "Ajustar carga conforme percepção de esforço.";
  }
};

export const generateNutriPlan = async (student: Student, notes: string): Promise<NutriPlan | null> => {
  if (!process.env.API_KEY) return null;
  const ai = getAI();
  const prompt = `Nutricionista: Gere um plano alimentar de 7 dias em JSON para ${student.name}. Objetivo: ${student.goal}. Peso: ${student.weight}kg. Altura: ${student.height}cm. Notas: ${notes}. Responda APENAS o JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weeklyMeals: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT, 
                properties: { 
                  dayOfWeek: { type: Type.STRING }, 
                  meals: { 
                    type: Type.ARRAY, 
                    items: { 
                      type: Type.OBJECT, 
                      properties: { 
                        time: { type: Type.STRING }, 
                        label: { type: Type.STRING }, 
                        description: { type: Type.STRING } 
                      } 
                    } 
                  } 
                } 
              } 
            },
            recipes: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT, 
                properties: { 
                  name: { type: Type.STRING }, 
                  ingredients: { type: Type.ARRAY, items: { type: Type.STRING } }, 
                  instructions: { type: Type.STRING }, 
                  macros: { 
                    type: Type.OBJECT, 
                    properties: { 
                      protein: { type: Type.NUMBER }, 
                      carbs: { type: Type.NUMBER }, 
                      fats: { type: Type.NUMBER }, 
                      calories: { type: Type.NUMBER } 
                    } 
                  } 
                } 
              } 
            },
            shoppingList: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { item: { type: Type.STRING }, category: { type: Type.STRING } } } },
            dailyMacrosTarget: { type: Type.OBJECT, properties: { protein: { type: Type.NUMBER }, carbs: { type: Type.NUMBER }, fats: { type: Type.NUMBER }, calories: { type: Type.NUMBER } } }
          }
        }
      }
    });

    const jsonStr = cleanJSON(response.text || "{}");
    const data = JSON.parse(jsonStr);

    if (!data.weeklyMeals) return null;

    return {
      weeklyMeals: data.weeklyMeals || [],
      recipes: (data.recipes || []).map((r: any, i: number) => ({ ...r, id: `r-${i}` })),
      shoppingList: (data.shoppingList || []).map((s: any) => ({ ...s, checked: false })),
      dailyMacrosTarget: data.dailyMacrosTarget || { protein: 0, carbs: 0, fats: 0, calories: 0 }
    };
  } catch (e) {
    console.error("Nutri generation error:", e);
    return null;
  }
};

export const generateYogaPlan = async (student: Student, notes: string): Promise<YogaPlan | null> => {
