        const diff = targetDayOfWeek - currentDay;
        const eventDate = new Date(today);
        eventDate.setDate(today.getDate() + (diff < 0 ? diff + 7 : diff));

        const dateStr = eventDate.toISOString().split('T')[0].replace(/-/g, '');

        const description = day.exercises.map(ex => 
          `- ${ex.name}: ${ex.sets}x${ex.reps}${ex.notes ? ' (' + ex.notes + ')' : ''}`
        ).join('\\n');

        icsContent.push('BEGIN:VEVENT');
        icsContent.push(`SUMMARY:Treino: ${day.focus} (${student.name})`);
        icsContent.push(`DTSTART;VALUE=DATE:${dateStr}`);
        icsContent.push(`DTEND;VALUE=DATE:${dateStr}`);
        icsContent.push(`DESCRIPTION:Objetivo: ${student.goal}\\n\\nExercícios:\\n${description}`);
        icsContent.push('RRULE:FREQ=WEEKLY');
        icsContent.push('STATUS:CONFIRMED');
        icsContent.push('TRANSP:TRANSPARENT');
        icsContent.push('END:VEVENT');
      }
    });

    icsContent.push('END:VCALENDAR');

    const blob = new Blob([icsContent.join('\r\n')], { type: 'text/calendar;charset=utf-8' });
    const link = document.createElement('a');
    link.href = window.URL.createObjectURL(blob);
    link.setAttribute('download', `treino-${student.name.toLowerCase().replace(/\s+/g, '-')}.ics`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmiNumber = parseFloat((weightToUse / Math.pow(student.height / 100, 2)).toFixed(1));

  const getBMICategory = (bmi: number) => {
    if (bmi < 18.5) return { category: 'Abaixo do peso', tip: 'Considere aumentar o aporte calórico com alimentos nutritivos.', color: 'text-blue-400', bg: 'bg-blue-400/10 border-blue-400/30' };
    if (bmi < 25) return { category: 'Peso normal', tip: 'Excelente! Mantenha seus hábitos saudáveis de nutrição e treino.', color: 'text-lime-400', bg: 'bg-lime-400/10 border-lime-400/30' };
    if (bmi < 30) return { category: 'Sobrepeso', tip: 'Foco em déficit calórico moderado e aumento do gasto energético.', color: 'text-orange-400', bg: 'bg-orange-400/10 border-orange-400/30' };
    return { category: 'Obesidade', tip: 'Procure orientação multidisciplinar para um plano de saúde seguro.', color: 'text-red-400', bg: 'bg-red-400/10 border-red-400/30' };
  };

  const bmiInfo = getBMICategory(bmiNumber);

  const evolutionGraph = useMemo(() => {
    if (student.progress.length < 2) return null;
    const data = [...student.progress].reverse();
    const minWeight = Math.min(...data.map(d => d.weight)) - 2;
    const maxWeight = Math.max(...data.map(d => d.weight)) + 2;
    const range = maxWeight - minWeight;
    const width = 500;
    const height = 150;

    const points = data.map((d, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((d.weight - minWeight) / range) * height;
      return `${x},${y}`;
    }).join(' ');

    return (
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-32 mt-4 overflow-visible">
        <defs>
          <linearGradient id="gradientLine" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#a3e635" stopOpacity="0.5"/>
            <stop offset="100%" stopColor="#a3e635" stopOpacity="0"/>
          </linearGradient>
        </defs>
        <polyline fill="none" stroke="#a3e635" strokeWidth="4" points={points} className="drop-shadow-glow" strokeLinecap="round" strokeLinejoin="round" />
        {data.map((d, i) => {
          const x = (i / (data.length - 1)) * width;
          const y = height - ((d.weight - minWeight) / range) * height;
          return (
            <g key={i}>
              <circle cx={x} cy={y} r="6" className="fill-slate-900 stroke-lime-400 stroke-2" />
              <text x={x} y={y - 15} textAnchor="middle" fill="#94a3b8" fontSize="12" fontWeight="bold">{d.weight}kg</text>
            </g>
          );
        })}
      </svg>
    );
  }, [student.progress]);

  // Dynamic Styles for Balloon
  const getBalloonStyles = () => {
    switch (generationState.type) {
      case 'WORKOUT': return { icon: '💪', color: 'text-lime-400', border: 'border-lime-400/50', shadow: 'shadow-lime-400/20' };
      case 'NUTRI': return { icon: '🥗', color: 'text-emerald-400', border: 'border-emerald-400/50', shadow: 'shadow-emerald-400/20' };
      case 'YOGA': return { icon: '🧘', color: 'text-purple-400', border: 'border-purple-400/50', shadow: 'shadow-purple-400/20' };
      case 'MEDITATION': return { icon: '✨', color: 'text-sky-400', border: 'border-sky-400/50', shadow: 'shadow-sky-400/20' };
      case 'PROGRESS': return { icon: '📊', color: 'text-indigo-400', border: 'border-indigo-400/50', shadow: 'shadow-indigo-400/20' };
      default: return { icon: '⚙️', color: 'text-slate-400', border: 'border-slate-400/50', shadow: 'shadow-slate-400/20' };
    }
