             {student.workoutHistory && student.workoutHistory.length > 0 ? (
               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                 {student.workoutHistory.map((h, i) => (
                   <div key={i} className="flex flex-col justify-between p-6 bg-slate-800/20 rounded-[2rem] border border-slate-800 hover:border-lime-400/30 transition-all group">
