              <div className="bg-slate-900/40 p-10 rounded-[2.5rem] border border-slate-800 shadow-xl">
                 <h4 className="text-slate-500 font-black uppercase text-[11px] mb-6 tracking-[0.2em] flex items-center gap-2"><Activity size={14} /> Metabolismo (IMC)</h4>
