};

export default App;

import React, { useState, useRef } from 'react';
import { Student, ViewState, TrainerProfile } from './types';
import { INITIAL_STUDENTS, WEEK_DAYS, INITIAL_TRAINER } from './constants';
import { StudentDetails } from './components/StudentDetails';
import { Users, LayoutDashboard, PlusCircle, Search, ChevronRight, Dumbbell, X, Info, Instagram, MessageCircle, Mail, Activity, Trophy, TrendingUp, Calendar, Edit3, Save, Camera, Wand2, Loader2, Upload, Check } from 'lucide-react';
import { generateTrainerBio } from './services/geminiService';

const GOAL_OPTIONS = [
  'Hipertrofia',
  'Emagrecimento',
  'Condicionamento Físico',
  'Flexibilidade',
  'Saúde/Bem-estar',
  'Performance Atleta',
  'Reabilitação',
  'Ganho de Força'
];

const SEDENTARY_LEVELS = [
  'Sedentário',
  'Levemente Ativo',
  'Moderadamente Ativo',
  'Muito Ativo',
  'Atleta'
];

const TITLE_SUGGESTIONS = [
  'Personal Trainer',
  'Consultor Online',
  'Especialista em Hipertrofia',
  'Coach de Emagrecimento',
  'Treinador de Alta Performance',
  'Especialista em Reabilitação'
];

const App: React.FC = () => {
  const [viewState, setViewState] = useState<ViewState>('DASHBOARD');
  const [students, setStudents] = useState<Student[]>(INITIAL_STUDENTS);
  const [trainer, setTrainer] = useState<TrainerProfile>(INITIAL_TRAINER);
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Trainer Edit Modal State
  const [showTrainerModal, setShowTrainerModal] = useState(false);
  const [trainerForm, setTrainerForm] = useState<TrainerProfile>(INITIAL_TRAINER);
  const [isGeneratingBio, setIsGeneratingBio] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeStudent = students.find(s => s.id === selectedStudentId);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    age: 25,
    height: 175,
    weight: 75,
    sedentaryLevel: 'Moderadamente Ativo' as Student['sedentaryLevel'],
    goal: GOAL_OPTIONS[0],
    level: 'Iniciante' as Student['level'],
    restrictions: '',
    whatsapp: '',
    instagram: '',
    email: ''
  });

  const handleStudentClick = (id: string) => {
    setSelectedStudentId(id);
    setViewState('STUDENT_DETAILS');
  };

  const handleUpdateStudent = (updatedStudent: Student) => {
    setStudents(prev => prev.map(s => s.id === updatedStudent.id ? updatedStudent : s));
  };

  const handleOpenTrainerEdit = () => {
    setTrainerForm(trainer);
    setShowTrainerModal(true);
  };

  const handleSaveTrainer = (e: React.FormEvent) => {
    e.preventDefault();
    setTrainer(trainerForm);
    setShowTrainerModal(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setTrainerForm(prev => ({ ...prev, avatarUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateBio = async () => {
    setIsGeneratingBio(true);
    try {
      const bio = await generateTrainerBio(trainerForm.name, trainerForm.title);
      if (bio) {
        setTrainerForm(prev => ({ ...prev, bio }));
      }
    } finally {
      setIsGeneratingBio(false);
    }
  };

  const toggleSpecialty = (specialty: string) => {
    const separator = " • ";
    const currentTitles = trainerForm.title 
      ? trainerForm.title.split(separator).map(t => t.trim()).filter(Boolean) 
      : [];

    let newTitles;
    if (currentTitles.includes(specialty)) {
      newTitles = currentTitles.filter(t => t !== specialty);
    } else {
      newTitles = [...currentTitles, specialty];
    }

    setTrainerForm(prev => ({ ...prev, title: newTitles.join(separator) }));
  };

  const handleConfirmCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const newStudent: Student = {
      id: Date.now().toString(),
      name: formData.name,
      age: formData.age,
      height: formData.height,
      weight: formData.weight,
      sedentaryLevel: formData.sedentaryLevel,
      goal: formData.goal,
      level: formData.level,
      restrictions: formData.restrictions,
      whatsapp: formData.whatsapp,
      instagram: formData.instagram,
      email: formData.email,
      avatarUrl: `https://picsum.photos/200/200?random=${Date.now()}`,
      weeklyPlan: { 
        days: WEEK_DAYS.map(day => ({ 
          dayOfWeek: day, 
          exercises: [], 
          focus: 'A definir' 
        })) 
      },
      meditationChallenges: [
        { title: 'Foco Inicial', description: 'Realizar 2 minutos de respiração', completed: false }
      ],
      progress: []
    };

    setStudents([newStudent, ...students]);
    setSelectedStudentId(newStudent.id);
    setViewState('STUDENT_DETAILS');
    setShowCreateModal(false);

    // Reset form
    setFormData({
      name: '', age: 25, height: 175, weight: 75,
      sedentaryLevel: 'Moderadamente Ativo', goal: GOAL_OPTIONS[0],
      level: 'Iniciante', restrictions: '', whatsapp: '', instagram: '', email: ''
    });
  };

  const filteredStudents = students.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.goal.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Dynamic Stats
  const activePlans = students.filter(s => s.weeklyPlan.days.some(d => d.exercises.length > 0)).length;
  const totalWeightChange = students.reduce((acc, curr) => {
    if (curr.progress.length === 0) return acc;
    const diff = curr.progress[0].weight - curr.weight;
    return acc + diff;
  }, 0).toFixed(1);

  return (
    <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex font-sans overflow-hidden">
      <aside className="hidden lg:flex flex-col w-72 border-r border-slate-800 bg-[#0f172a] h-screen sticky top-0 p-8 z-20 shadow-2xl">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-lime-400 p-2.5 rounded-2xl shadow-[0_0_20px_rgba(163,230,53,0.3)]">
            <Dumbbell className="text-slate-900 w-6 h-6" />
          </div>
          <span className="text-2xl font-black tracking-tighter text-white italic">PERSONAL<span className="text-lime-400">PRO</span></span>
        </div>

        <nav className="space-y-3">
          <button onClick={() => setViewState('DASHBOARD')} className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-2xl transition-all font-bold tracking-wide ${viewState === 'DASHBOARD' ? 'bg-slate-800 text-lime-400 shadow-xl shadow-lime-400/5 border border-slate-700' : 'text-slate-500 hover:bg-slate-800/40 hover:text-slate-200'}`}>
            <LayoutDashboard size={20} /> Dashboard
          </button>
          <button onClick={() => setViewState('DASHBOARD')} className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-2xl transition-all font-bold tracking-wide ${viewState === 'STUDENT_DETAILS' ? 'bg-slate-800 text-lime-400' : 'text-slate-500 hover:bg-slate-800/40 hover:text-slate-200'}`}>
            <Users size={20} /> Alunos
          </button>
        </nav>

        <div className="mt-auto pt-8 border-t border-slate-800/50">
           <div className="flex items-center gap-3 bg-slate-900/50 p-4 rounded-2xl border border-slate-800">
              <img src={trainer.avatarUrl} className="w-10 h-10 rounded-full border border-lime-400/30 object-cover" />
              <div className="flex-1 overflow-hidden">
                 <p className="text-xs font-black text-white truncate">{trainer.name}</p>
                 <p className="text-[10px] text-lime-400 font-bold truncate">Online</p>
              </div>
           </div>
        </div>
      </aside>

      <main className="flex-1 p-6 lg:p-10 overflow-y-auto h-screen relative">
        {/* Background Elements */}
        <div className="fixed top-0 right-0 w-[500px] h-[500px] bg-lime-500/5 rounded-full blur-[120px] pointer-events-none" />
        <div className="fixed bottom-0 left-0 w-[500px] h-[500px] bg-indigo-500/5 rounded-full blur-[120px] pointer-events-none" />

        {viewState === 'DASHBOARD' && (
