                </div>
                <div className="md:col-span-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2 block">Objetivo Principal</label>
                  <select value={formData.goal} onChange={e => setFormData({...formData, goal: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-4 text-white focus:ring-2 focus:ring-lime-400 outline-none appearance-none">
                    {GOAL_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                  </select>
                </div>
                <div className="md:col-span-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2 block">Nível de Atividade / Sedentarismo</label>
                  <select value={formData.sedentaryLevel} onChange={e => setFormData({...formData, sedentaryLevel: e.target.value as any})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-4 text-white focus:ring-2 focus:ring-lime-400 outline-none appearance-none">
                    {SEDENTARY_LEVELS.map(lvl => <option key={lvl} value={lvl}>{lvl}</option>)}
                  </select>
                </div>
                <div className="md:col-span-2">
                   <label className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2 block">Restrições Médicas / Lesões</label>
                   <textarea value={formData.restrictions} onChange={e => setFormData({...formData, restrictions: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-4 text-white focus:ring-2 focus:ring-lime-400 outline-none min-h-[100px]" placeholder="Hérnias, asma, dor articular, cirurgias..." />
                </div>
                <div className="md:col-span-2 border-t border-slate-800 pt-8 mt-4">
                  <h3 className="text-white font-black text-sm uppercase tracking-widest mb-6 flex items-center gap-2">
                    <Info size={18} className="text-lime-400" /> Contatos e Social
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="relative">
                      <MessageCircle size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
                      <input type="text" placeholder="WhatsApp (DDD + Número)" value={formData.whatsapp} onChange={e => setFormData({...formData, whatsapp: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-lime-400 outline-none" />
                    </div>
                    <div className="relative">
                      <Instagram size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
                      <input type="text" placeholder="Instagram (@usuario)" value={formData.instagram} onChange={e => setFormData({...formData, instagram: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-lime-400 outline-none" />
                    </div>
                    <div className="relative md:col-span-2">
                      <Mail size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
                      <input type="email" placeholder="E-mail profissional" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full bg-slate-900 border border-slate-800 rounded-2xl pl-12 pr-4 py-4 text-white focus:ring-2 focus:ring-lime-400 outline-none" />
                    </div>
                  </div>
                </div>
              </div>
              <button type="submit" className="w-full bg-lime-400 py-6 rounded-2xl font-black text-slate-900 text-lg shadow-xl shadow-lime-400/20 active:scale-95 transition-all uppercase tracking-widest">Matricular Aluno</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

