  BACK = 'Costas',
  LEGS = 'Pernas',
  SHOULDERS = 'Ombros',
  ARMS = 'Braços',
  CORE = 'Abdômen',
  CARDIO = 'Cardio',
  FULL_BODY = 'Corpo Todo'
}

export interface Exercise {
