type GenerationType = 'WORKOUT' | 'NUTRI' | 'YOGA' | 'MEDITATION' | 'PROGRESS' | 'SPORTS' | 'CALISTHENICS' | 'ASSESSMENT' | 'GENERAL';

interface GenerationState {
  active: boolean;
  message: string;
  subMessage: string;
  type: GenerationType;
}

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION' | 'ASSESSMENT' | 'SPORTS' | 'CALISTHENICS'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);

  // New States for Sports and Calisthenics
  const [selectedSport, setSelectedSport] = useState(SPORTS_LIST[0]);
  const [selectedCaliSkill, setSelectedCaliSkill] = useState(CALISTHENICS_SKILLS[0]);

  // Assessment State
  const [assessmentReport, setAssessmentReport] = useState<string>('');

  // Unified Generation State
  const [generationState, setGenerationState] = useState<GenerationState>({
    active: false,
    message: '',
    subMessage: '',
    type: 'GENERAL'
  });

  const startGeneration = (message: string, subMessage: string, type: GenerationType) => {
    setGenerationState({ active: true, message, subMessage, type });
  };

  const stopGeneration = () => {
    setGenerationState(prev => ({ ...prev, active: false }));
  };

  // Modals visibility
  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [showEditWorkoutModal, setShowEditWorkoutModal] = useState(false);
  const [showYogaPrompt, setShowYogaPrompt] = useState(false);
  const [showWorkoutPromptModal, setShowWorkoutPromptModal] = useState(false);
  const [showNutriPromptModal, setShowNutriPromptModal] = useState(false);
  const [showSportsPromptModal, setShowSportsPromptModal] = useState(false);

  // New Modals for History/Delete
  const [viewingHistoryPlan, setViewingHistoryPlan] = useState<WeeklyPlan | null>(null);
  const [deletingProgressId, setDeletingProgressId] = useState<string | null>(null);
  const [deleteStep, setDeleteStep] = useState<1 | 2>(1);
  const [editingProgressId, setEditingProgressId] = useState<string | null>(null);

  // Prompt Inputs
  const [workoutPromptInput, setWorkoutPromptInput] = useState("");
  const [nutriPromptInput, setNutriPromptInput] = useState("");
  const [yogaInput, setYogaInput] = useState("");
  const [sportsPromptInput, setSportsPromptInput] = useState("");

  // Edit Student Form State
  const [editStudentForm, setEditStudentForm] = useState({
    name: student.name,
    age: student.age,
    height: student.height,
    weight: student.weight,
    goal: student.goal,
    level: student.level,
    avatarUrl: student.avatarUrl,
    restrictions: student.restrictions || '',
    whatsapp: student.whatsapp || '',
    instagram: student.instagram || '',
    email: student.email || '',
    sedentaryLevel: student.sedentaryLevel
  });

  const [progressForm, setProgressForm] = useState<{weight: number, measurements: Measurements}>({
    weight: student.progress[0]?.weight || student.weight,
    measurements: {
      chest: 0, waist: 0, hips: 0, bicepsR: 0, bicepsL: 0, thighR: 0, thighL: 0, calf: 0, neck: 0, forearm: 0,
      ...(student.progress[0]?.measurements || {})
    }
  });

  // Audio/Meditation States
  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [activeAmbient, setActiveAmbient] = useState<string | null>(null);
  const [ambientVolume, setAmbientVolume] = useState(0.5);
  const ambientAudioRef = useRef<HTMLAudioElement | null>(null);
  const [meditationTips, setMeditationTips] = useState<string>("");

  // Timers
  const [globalTimer, setGlobalTimer] = useState(900);
  const [globalTimerRunning, setGlobalTimerRunning] = useState(false);
  const [activePoseTimer, setActivePoseTimer] = useState<{name: string, total: number, remaining: number} | null>(null);
  const [poseTimerRunning, setPoseTimerRunning] = useState(false);

  useEffect(() => {
    let interval: number;
    if (globalTimerRunning && globalTimer > 0) {
      interval = window.setInterval(() => setGlobalTimer((prev) => prev - 1), 1000);
    }
    return () => clearInterval(interval);
  }, [globalTimerRunning, globalTimer]);

  useEffect(() => {
    let interval: number;
    if (poseTimerRunning && activePoseTimer && activePoseTimer.remaining > 0) {
      interval = window.setInterval(() => {
        setActivePoseTimer(prev => prev ? { ...prev, remaining: prev.remaining - 1 } : null);
      }, 1000);
    } else if (activePoseTimer?.remaining === 0) {
      setPoseTimerRunning(false);
    }
    return () => clearInterval(interval);
  }, [poseTimerRunning, activePoseTimer]);

  useEffect(() => {
    if (activeAmbient) {
      const sound = AMBIENT_SOUNDS.find(s => s.name === activeAmbient);
      if (sound) {
        if (!ambientAudioRef.current) {
          ambientAudioRef.current = new Audio(sound.url);
          ambientAudioRef.current.loop = true;
        } else {
          ambientAudioRef.current.src = sound.url;
        }
        ambientAudioRef.current.volume = ambientVolume;
        ambientAudioRef.current.play().catch(console.error);
      }
    } else {
      if (ambientAudioRef.current) {
        ambientAudioRef.current.pause();
      }
    }
    return () => {
      if (ambientAudioRef.current) {
        ambientAudioRef.current.pause();
      }
    };
  }, [activeAmbient]);

  useEffect(() => {
    if (ambientAudioRef.current) {
      ambientAudioRef.current.volume = ambientVolume;
    }
  }, [ambientVolume]);

  const addExercise = (dayIndex: number) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    const newExercise: Exercise = {
      id: `ex-${Date.now()}`,
      name: 'Novo Exercício',
      muscleGroup: MuscleGroup.CHEST,
      sets: 3,
      reps: '12',
      videoUrl: 'https://www.youtube.com/results?search_query=exercicio',
      notes: 'Ajustar carga/repetição conforme necessário'
    };
    updatedWeeklyPlan.days[dayIndex].exercises.push(newExercise);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const updateExercise = (dayIndex: number, exerciseId: string, field: string, value: any) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    const day = updatedWeeklyPlan.days[dayIndex];
    day.exercises = day.exercises.map(ex => 
      ex.id === exerciseId ? { ...ex, [field as keyof Exercise]: value } : ex
    );
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const playMeditation = async (theme: string) => {
    startGeneration(`Criando Meditação: ${theme}`, "A IA está sintetizando uma experiência sonora...", 'MEDITATION');
    try {
      const audioBase64Data = await generateMeditationAudio(theme);
      if (audioBase64Data) {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        const audioContext = new AudioContextClass({ sampleRate: 24000 });
        const decode = (base64: string) => {
          const binaryString = atob(base64);
          const bytes = new Uint8Array(binaryString.length);
          for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }
          return bytes;
        };
        const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
          const dataInt16 = new Int16Array(data.buffer);
          const frameCount = dataInt16.length / numChannels;
          const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
          for (let channel = 0; channel < numChannels; channel++) {
            const channelData = buffer.getChannelData(channel);
            for (let i = 0; i < frameCount; i++) {
              channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
            }
          }
          return buffer;
        };
        const audioBuffer = await decodeAudioData(decode(audioBase64Data), audioContext, 24000, 1);
        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);
        source.start();
        setAudioBase64(audioBase64Data);
      } else {
        alert("Não foi possível gerar o áudio. Tente novamente.");
      }
    } catch (error) {
      console.error("Error playing meditation:", error);
      alert("Erro ao reproduzir meditação.");
    } finally {
      stopGeneration();
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleGenWorkout = async () => {
    startGeneration("Construindo Treino de Elite", "Analisando biomecânica e objetivos...", 'WORKOUT');
    try {
      const plan = await generateWorkoutPlan(student, workoutPromptInput);
      if (plan) {
        const updatedHistory = student.workoutHistory ? [student.weeklyPlan, ...student.workoutHistory] : [student.weeklyPlan];
        onUpdateStudent({ ...student, weeklyPlan: { ...plan, generatedAt: new Date().toLocaleDateString('pt-BR') }, workoutHistory: updatedHistory.slice(0, 10) });
      } else {
        alert("Erro ao gerar treino. Tente novamente com mais detalhes.");
      }
    } finally {
      stopGeneration();
      setShowWorkoutPromptModal(false);
    }
  };

  const handleGenIANote = async (dayIndex: number, exId: string, exName: string) => {
    startGeneration("Ajustando Técnica", `Otimizando instruções para ${exName}...`, 'WORKOUT');
    try {
      const note = await generateExerciseNote(student, exName);
      updateExercise(dayIndex, exId, 'notes', note);
    } finally {
      stopGeneration();
    }
  };

  const handleGenNutri = async () => {
    startGeneration("Calculando Nutrição", "Balanceando macros e selecionando receitas...", 'NUTRI');
    try {
      const plan = await generateNutriPlan(student, nutriPromptInput);
      if (plan) {
        onUpdateStudent({ ...student, nutriPlan: plan });
      } else {
        alert("Erro ao gerar plano nutricional. Tente novamente.");
      }
    } finally {
      stopGeneration();
      setShowNutriPromptModal(false);
    }
  };

  const handleGenYoga = async () => {
    startGeneration("Desenhando Fluxo de Yoga", "Selecionando asanas para seus objetivos...", 'YOGA');
    try {
      const plan = await generateYogaPlan(student, yogaInput);
      if (plan) {
        const currentPlan = student.yogaPlan;
        const updatedHistory = student.yogaHistory ? [...student.yogaHistory] : [];
        if (currentPlan) {
             updatedHistory.unshift(currentPlan);
        }

        onUpdateStudent({ 
