        if (currentPlan) {
             updatedHistory.unshift(currentPlan);
        }

        onUpdateStudent({ 
            ...student, 
            yogaPlan: { ...plan, generatedAt: new Date().toLocaleDateString('pt-BR') }, 
            yogaHistory: updatedHistory.slice(0, 10) 
        });
      } else {
        alert("Erro ao gerar sessão de Yoga. Tente novamente.");
