    const range = maxWeight - minWeight;
    const width = 500;
    const height = 150;

    const points = data.map((d, i) => {
      const x = (i / (data.length - 1)) * width;
      // Prevent division by zero if range is 0 (all weights same)
      const y = range === 0 ? height / 2 : height - ((d.weight - minWeight) / range) * height;
      return `${x},${y}`;
    }).join(' ');

