  LineChart, Calendar, Scale, Ruler, Camera, ChevronRight, X, 
  Apple, Utensils, ShoppingCart, Activity, Clock, Edit2, Info,
  Sparkles, Flower2, Wind, Timer as TimerIcon, Play, Pause, RotateCcw, CheckCircle2, Circle, Volume2, VolumeX, Flame, Search, User, MessageCircle, Instagram, Mail, Brain, RefreshCw, Wand2, Download, Send, Youtube, FileText, Wand, History, TrendingUp, TrendingDown, ChevronDown, Eye, Pencil, AlertTriangle, FileDown, Trophy, Medal, ClipboardList
} from 'lucide-react';

interface StudentDetailsProps {
  student: Student;
  onBack: () => void;
  onUpdateStudent: (updatedStudent: Student) => void;
}

const MEASUREMENT_LABELS: Record<string, string> = {
  chest: 'Peitoral',
  waist: 'Cintura',
  hips: 'Quadril',
  bicepsR: 'Bíceps (Dir)',
  bicepsL: 'Bíceps (Esq)',
  thighR: 'Coxa (Dir)',
  thighL: 'Coxa (Esq)',
  calf: 'Panturrilha',
  neck: 'Pescoço',
  forearm: 'Antebraço'
};

const SPORTS_LIST = ['Futebol', 'Futsal', 'Vôlei', 'Basquete', 'Corrida', 'Natação', 'Tênis', 'Crossfit'];
const CALISTHENICS_SKILLS = ['Fundamentos', 'Muscle Up', 'Front Lever', 'Planche', 'Handstand', 'Pistol Squat'];

const AMBIENT_SOUNDS = [
  { id: 'chuva', name: 'Chuva Tropical', url: 'https://actions.google.com/sounds/v1/weather/rain_heavy_loud.ogg' },
  { id: 'floresta', name: 'Floresta Zen', url: 'https://actions.google.com/sounds/v1/ambient/morning_birds.ogg' },
  { id: 'ondas', name: 'Ondas do Mar', url: 'https://actions.google.com/sounds/v1/water/waves_crashing_on_shore.ogg' },
  { id: 'alfa', name: 'Ondas Alfa', url: 'https://actions.google.com/sounds/v1/science_fiction/low_frequency_hum.ogg' },
];

type GenerationType = 'WORKOUT' | 'NUTRI' | 'YOGA' | 'MEDITATION' | 'PROGRESS' | 'SPORTS' | 'CALISTHENICS' | 'ASSESSMENT' | 'GENERAL';

interface GenerationState {
  active: boolean;
  message: string;
  subMessage: string;
  type: GenerationType;
}

export const StudentDetails: React.FC<StudentDetailsProps> = ({ student, onBack, onUpdateStudent }) => {
  const [activeTab, setActiveTab] = useState<'WORKOUT' | 'PROGRESS' | 'NUTRI' | 'YOGA' | 'MEDITATION' | 'ASSESSMENT' | 'SPORTS' | 'CALISTHENICS'>('WORKOUT');
  const [selectedDayIndex, setSelectedDayIndex] = useState<number>(0);
  const [selectedNutriDayIndex, setSelectedNutriDayIndex] = useState<number>(0);

  const [selectedSport, setSelectedSport] = useState(SPORTS_LIST[0]);
  const [selectedCaliSkill, setSelectedCaliSkill] = useState(CALISTHENICS_SKILLS[0]);

  const [assessmentReport, setAssessmentReport] = useState<string>('');

  const [generationState, setGenerationState] = useState<GenerationState>({
    active: false,
    message: '',
    subMessage: '',
    type: 'GENERAL'
  });

  const startGeneration = (message: string, subMessage: string, type: GenerationType) => {
    setGenerationState({ active: true, message, subMessage, type });
  };

  const stopGeneration = () => {
    setGenerationState(prev => ({ ...prev, active: false }));
  };

  const [showEditStudentModal, setShowEditStudentModal] = useState(false);
  const [showProgressModal, setShowProgressModal] = useState(false);
  const [showEditWorkoutModal, setShowEditWorkoutModal] = useState(false);
  const [showYogaPrompt, setShowYogaPrompt] = useState(false);
  const [showWorkoutPromptModal, setShowWorkoutPromptModal] = useState(false);
  const [showNutriPromptModal, setShowNutriPromptModal] = useState(false);
  const [showSportsPromptModal, setShowSportsPromptModal] = useState(false);
  const [showCaliPromptModal, setShowCaliPromptModal] = useState(false);

  const [deletingProgressId, setDeletingProgressId] = useState<string | null>(null);
  const [deleteStep, setDeleteStep] = useState<1 | 2>(1);
  const [editingProgressId, setEditingProgressId] = useState<string | null>(null);

  const [workoutPromptInput, setWorkoutPromptInput] = useState("");
  const [nutriPromptInput, setNutriPromptInput] = useState("");
  const [yogaInput, setYogaInput] = useState("");
  const [sportsPromptInput, setSportsPromptInput] = useState("");
  const [caliPromptInput, setCaliPromptInput] = useState("");

  const [editStudentForm, setEditStudentForm] = useState({
    name: student.name,
    age: student.age,
    height: student.height,
    weight: student.weight,
    goal: student.goal,
    level: student.level,
    avatarUrl: student.avatarUrl,
    restrictions: student.restrictions || '',
    whatsapp: student.whatsapp || '',
    instagram: student.instagram || '',
    email: student.email || '',
    sedentaryLevel: student.sedentaryLevel
  });

  const [progressForm, setProgressForm] = useState<{weight: number, measurements: Measurements}>({
    weight: student.progress[0]?.weight || student.weight,
    measurements: {
      chest: 0, waist: 0, hips: 0, bicepsR: 0, bicepsL: 0, thighR: 0, thighL: 0, calf: 0, neck: 0, forearm: 0,
      ...(student.progress[0]?.measurements || {})
    }
  });

  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [activeAmbient, setActiveAmbient] = useState<string | null>(null);
  const [ambientVolume, setAmbientVolume] = useState(0.5);
  const ambientAudioRef = useRef<HTMLAudioElement | null>(null);
  const [meditationTips, setMeditationTips] = useState<string>("");

  useEffect(() => {
    if (activeAmbient) {
      const sound = AMBIENT_SOUNDS.find(s => s.name === activeAmbient);
      if (sound) {
        if (!ambientAudioRef.current) {
          ambientAudioRef.current = new Audio(sound.url);
          ambientAudioRef.current.loop = true;
        } else {
          ambientAudioRef.current.src = sound.url;
        }
        ambientAudioRef.current.volume = ambientVolume;
        ambientAudioRef.current.play().catch(console.error);
      }
    } else if (ambientAudioRef.current) {
      ambientAudioRef.current.pause();
    }
    return () => { if (ambientAudioRef.current) ambientAudioRef.current.pause(); };
  }, [activeAmbient]);

  const addExercise = (dayIndex: number) => {
    const updatedWeeklyPlan = { ...student.weeklyPlan };
    const newExercise: Exercise = {
      id: `ex-${Date.now()}`,
      name: 'Novo Exercício',
      muscleGroup: MuscleGroup.CHEST,
      sets: 3,
      reps: '12',
      videoUrl: 'https://www.youtube.com/results?search_query=exercicio',
      notes: 'Ajustar carga/repetição conforme necessário'
    };
    updatedWeeklyPlan.days[dayIndex].exercises.push(newExercise);
    onUpdateStudent({ ...student, weeklyPlan: updatedWeeklyPlan });
  };

  const handleGenWorkout = async () => {
    startGeneration("Construindo Treino de Elite", "Analisando biomecânica e objetivos...", 'WORKOUT');
    try {
      const plan = await generateWorkoutPlan(student, workoutPromptInput);
      if (plan) {
        const updatedHistory = student.workoutHistory ? [student.weeklyPlan, ...student.workoutHistory] : [student.weeklyPlan];
        onUpdateStudent({ ...student, weeklyPlan: { ...plan, generatedAt: new Date().toLocaleDateString('pt-BR') }, workoutHistory: updatedHistory.slice(0, 10) });
      }
    } finally {
      stopGeneration();
      setShowWorkoutPromptModal(false);
    }
  };

  const handleGenCalisthenics = async () => {
    startGeneration("Calistenia IA", `Criando progressão para ${selectedCaliSkill}...`, 'CALISTHENICS');
    try {
      const plan = await generateCalisthenicsPlan(student, selectedCaliSkill, caliPromptInput);
      if (plan) onUpdateStudent({ ...student, calisthenicsPlan: { ...plan, generatedAt: new Date().toLocaleDateString('pt-BR') }});
    } finally {
      stopGeneration();
      setShowCaliPromptModal(false);
    }
  };

  const handleGenInsights = async () => {
    startGeneration("Processando Evolução", "Analisando dados biométricos e histórico...", 'PROGRESS');
    try {
      const insights = await generateProgressInsights(student);
      const updatedProgress = [...student.progress];
      if (updatedProgress.length > 0) {
        updatedProgress[0] = { ...updatedProgress[0], aiInsights: insights };
        onUpdateStudent({ ...student, progress: updatedProgress });
      }
    } finally {
      stopGeneration();
    }
  };

  const openNewCheckin = () => {
    setEditingProgressId(null);
    setProgressForm({
      weight: student.weight,
      measurements: { 
        chest: 0, waist: 0, hips: 0, bicepsR: 0, bicepsL: 0, thighR: 0, thighL: 0, calf: 0, neck: 0, forearm: 0,
        ...(student.progress[0]?.measurements || {}) 
      }
    });
    setShowProgressModal(true);
  };

  const weightToUse = student.progress.length ? student.progress[0].weight : student.weight;
  const bmiNumber = parseFloat((weightToUse / Math.pow(student.height / 100, 2)).toFixed(1));

  const balloonStyle = useMemo(() => {
    switch (generationState.type) {
      case 'WORKOUT': return { icon: '💪', color: 'text-lime-400', border: 'border-lime-400/50' };
      case 'NUTRI': return { icon: '🥗', color: 'text-emerald-400', border: 'border-emerald-400/50' };
      case 'CALISTHENICS': return { icon: '🤸', color: 'text-yellow-400', border: 'border-yellow-400/50' };
      case 'PROGRESS': return { icon: '📊', color: 'text-indigo-400', border: 'border-indigo-400/50' };
      default: return { icon: '⚙️', color: 'text-slate-400', border: 'border-slate-400/50' };
    }
  }, [generationState.type]);

  const daysOfWeek = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
  const currentWeekDay = daysOfWeek[new Date().getDay()];

  return (
    <div className="animate-fade-in space-y-4 md:space-y-8 pb-32 relative overflow-x-hidden">
      {/* Central Loading Balloon */}
      {generationState.active && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[999] flex items-center justify-center p-4">
          <div className={`bg-slate-900 border-2 ${balloonStyle.border} p-8 rounded-[2rem] md:rounded-[3rem] shadow-2xl flex flex-col items-center gap-6 max-w-sm w-full text-center animate-bounce-gentle`}>
            <div className="text-6xl md:text-8xl animate-pulse filter drop-shadow-2xl">{balloonStyle.icon}</div>
            <div className="space-y-2">
              <h3 className="font-black text-xl md:text-2xl uppercase text-white">{generationState.message}</h3>
              {/* Corrected: Access subMessage from generationState instead of balloonStyle */}
              <p className={`text-xs font-bold uppercase tracking-widest ${balloonStyle.color} opacity-80`}>{generationState.subMessage}</p>
            </div>
            <div className="w-full bg-slate-800 h-1.5 rounded-full overflow-hidden">
               <div className={`h-full w-1/3 ${balloonStyle.color.replace('text-', 'bg-')} animate-loading-bar`}></div>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col gap-4 bg-slate-800/50 p-4 md:p-6 rounded-3xl border border-slate-700/50 shadow-xl">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4 flex-1">
            <button onClick={onBack} className="p-2 hover:bg-slate-700 rounded-xl transition-all text-slate-400"><ArrowLeft size={20} /></button>
            <img src={student.avatarUrl} className="w-12 h-12 md:w-16 md:h-16 rounded-2xl border-2 border-lime-400 object-cover shadow-lg" />
            <div className="flex-1 min-w-0">
              <h1 className="text-xl md:text-2xl font-black text-white truncate leading-tight">{student.name}</h1>
              <div className="flex gap-2 mt-1">
                <span className="text-[10px] font-black uppercase tracking-widest text-lime-400 bg-lime-400/10 px-2 py-0.5 rounded-lg border border-lime-400/20">{student.goal}</span>
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 bg-slate-700/50 px-2 py-0.5 rounded-lg">{student.level}</span>
              </div>
            </div>
          </div>
          <div className="flex gap-2 self-end md:self-auto">
             <button onClick={() => setShowEditStudentModal(true)} className="p-3 bg-slate-700/50 rounded-xl text-slate-300 hover:text-white border border-slate-600/50"><Edit2 size={18} /></button>
             {student.whatsapp && <a href={`https://wa.me/${student.whatsapp.replace(/\D/g,'')}`} target="_blank" className="p-3 bg-slate-700/50 rounded-xl text-lime-400 border border-slate-600/50"><MessageCircle size={18} /></a>}
          </div>
        </div>

        {/* Scrollable Tabs Menu */}
        <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 -mx-2 px-2 scroll-smooth">
          {[
            { id: 'WORKOUT', icon: Dumbbell, label: 'Treino', color: 'lime-400' },
            { id: 'PROGRESS', icon: LineChart, label: 'Evolução', color: 'indigo-400' },
            { id: 'NUTRI', icon: Apple, label: 'Nutri', color: 'emerald-400' },
            { id: 'CALISTHENICS', icon: Activity, label: 'Calistenia', color: 'yellow-400' },
            { id: 'ASSESSMENT', icon: ClipboardList, label: 'Avaliação', color: 'pink-400' },
            { id: 'SPORTS', icon: Trophy, label: 'Esportes', color: 'orange-400' },
            { id: 'YOGA', icon: Flower2, label: 'Yoga', color: 'purple-400' },
            { id: 'MEDITATION', icon: Wind, label: 'Zen', color: 'sky-400' },
          ].map(tab => (
            <button 
