      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            weeklyMeals: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT, 
                properties: { 
                  dayOfWeek: { type: Type.STRING }, 
                  meals: { 
                    type: Type.ARRAY, 
                    items: { 
                      type: Type.OBJECT, 
                      properties: { 
                        time: { type: Type.STRING }, 
                        label: { type: Type.STRING }, 
                        description: { type: Type.STRING } 
                      } 
                    } 
                  } 
                } 
              } 
            },
            recipes: { 
